#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let res = lgwks_bot::script::FanOut::new(ids)
        .at_most(4)
        .within(deadline)
        .run({
            let fetch = fetch;
            move |id: u32| {
                let fetch = fetch.clone();
                async move { fetch.fetch(id).await.map_err(|_| id) }
            }
        })
        .await;
    match res {
        Ok(vals) => Ok(vals.into_iter().sum()),
        Err(lgwks_bot::script::FanOutError::Item { error: id, .. }) => {
            Err(SolveError::Fetch { id })
        }
        Err(lgwks_bot::script::FanOutError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(lgwks_bot::script::FanOutError::Flow(e)) => {
            if e.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Deadline)
            }
        }
        Err(_) => Err(SolveError::Deadline),
    }
}

