struct SharedReader {
    result: std::sync::Mutex<Option<(Vec<u8>, u64)>>,
}

struct ChildGuard {
    child: Option<std::process::Child>,
    pid: u32,
}

impl Drop for ChildGuard {
    fn drop(&mut self) {
        kill_group_and_tree(self.pid);
        if let Some(mut c) = self.child.take() {
            let _ = c.kill();
            let _ = c.wait();
        }
    }
}

fn kill_group_and_tree(pid: u32) {
    let _ = std::process::Command::new("kill")
        .arg("-KILL")
        .arg(format!("-{}", pid))
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
    if let Ok(out) = std::process::Command::new("ps")
        .arg("-eo")
        .arg("pid,ppid")
        .output()
    {
        let txt = String::from_utf8_lossy(&out.stdout);
        let mut kids: std::collections::HashMap<u32, Vec<u32>> =
            std::collections::HashMap::new();
        for line in txt.lines().skip(1) {
            let mut it = line.split_whitespace();
            let a = it.next();
            let b = it.next();
            if let (Some(a), Some(b)) = (a, b) {
                if let (Ok(p), Ok(pp)) = (a.parse::<u32>(), b.parse::<u32>()) {
                    kids.entry(pp).or_default().push(p);
                }
            }
        }
        let mut stack = vec![pid];
        let mut seen = std::collections::HashSet::new();
        seen.insert(pid);
        let mut to_kill = Vec::new();
        while let Some(cur) = stack.pop() {
            if let Some(v) = kids.get(&cur) {
                for &c in v {
                    if seen.insert(c) {
                        to_kill.push(c);
                        stack.push(c);
                    }
                }
            }
        }
        for p in to_kill {
            let _ = std::process::Command::new("kill")
                .arg("-KILL")
                .arg(format!("{}", p))
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .status();
        }
        let _ = std::process::Command::new("kill")
            .arg("-KILL")
            .arg(format!("-{}", pid))
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status();
    }
    let _ = std::process::Command::new("kill")
        .arg("-KILL")
        .arg(format!("{}", pid))
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
}

fn reader_main(
    stdout: std::process::ChildStdout,
    head_limit: usize,
    shared: std::sync::Arc<SharedReader>,
) {
    use std::io::Read;
    let mut head: Vec<u8> = Vec::new();
    head.reserve(std::cmp::min(head_limit, 8192));
    let mut total: u64 = 0;
    let mut buf = [0u8; 8192];
    let mut s = stdout;
    loop {
        match s.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                total += n as u64;
                if head.len() < head_limit {
                    let rem = head_limit - head.len();
                    let take = std::cmp::min(rem, n);
                    head.extend_from_slice(&buf[..take]);
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(_) => break,
        }
    }
    *shared.result.lock().unwrap() = Some((head, total));
}

struct Sleep {
    dur: std::time::Duration,
    spawned: bool,
}

impl std::future::Future for Sleep {
    type Output = ();
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<()> {
        let this = self.get_mut();
        if this.dur.is_zero() {
            return std::task::Poll::Ready(());
        }
        if this.spawned {
            return std::task::Poll::Pending;
        }
        this.spawned = true;
        let w = cx.waker().clone();
        let d = this.dur;
        std::thread::spawn(move || {
            std::thread::sleep(d);
            w.wake();
        });
        std::task::Poll::Pending
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        cmd.process_group(0);
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let pid = child.id();
    let stdout = child.stdout.take().unwrap();
    let shared = std::sync::Arc::new(SharedReader {
        result: std::sync::Mutex::new(None),
    });
    let sc = shared.clone();
    let hl = head_limit;
    std::thread::spawn(move || {
        reader_main(stdout, hl, sc);
    });
    let mut guard = ChildGuard {
        child: Some(child),
        pid,
    };
    let start = std::time::Instant::now();
    loop {
        let exited = match guard.child.as_mut().unwrap().try_wait() {
            Ok(Some(_)) => true,
            Ok(None) => false,
            Err(_) => false,
        };
        if exited {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(CaptureError::Deadline);
        }
        let remaining = deadline
            .checked_sub(start.elapsed())
            .unwrap_or(std::time::Duration::ZERO);
        let sd = std::cmp::min(remaining, std::time::Duration::from_millis(5));
        Sleep {
            dur: sd,
            spawned: false,
        }
        .await;
    }
    let (head, total) = loop {
        if let Some(v) = shared.result.lock().unwrap().take() {
            break v;
        }
        Sleep {
            dur: std::time::Duration::from_millis(5),
            spawned: false,
        }
        .await;
    };
    let truncated = total > head_limit as u64;
    Ok(CaptureResult::new(head, total, truncated))
}

use std::num::NonZeroUsize;
use std::time::Duration;

#[derive(Debug)]
pub enum CaptureError {
    Spawn(String),
    Deadline,
    Cancelled,
}

#[derive(Debug, PartialEq, Eq)]
pub struct CaptureResult {
    head: Vec<u8>,
    total_bytes: u64,
    truncated: bool,
}

impl CaptureResult {
    pub fn new(head: Vec<u8>, total_bytes: u64, truncated: bool) -> Self {
        Self {
            head,
            total_bytes,
            truncated,
        }
    }
    pub fn head(&self) -> &[u8] {
        &self.head
    }
    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }
    pub fn truncated(&self) -> bool {
        self.truncated
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let program = argv[0].clone();
    let rest: Vec<String> = argv[1..].to_vec();

    let cap_u: usize = if head_limit == 0 { 1 } else { head_limit };
    let cap: NonZeroUsize = match NonZeroUsize::new(cap_u) {
        Some(v) => v,
        None => return Err(CaptureError::Spawn("invalid head_limit".to_string())),
    };

    let mut spec = lgwks_bot::rt::process::ProcessSpec::new(program);
    for a in &rest {
        spec.arg(a);
    }
    spec.capture_stdout(cap);
    spec.deadline(deadline);

    // The supervisor owns the child process group. It is owned by this
    // future, and the run_process future borrows it, so dropping this
    // `solve` future drops the run future and the supervisor, stopping the
    // whole group (children, grandchildren) and reaping zombies. Nothing
    // is spawned detached; all work stops with this future.
    let mut sup: lgwks_bot::rt::supervise::Supervisor =
        <lgwks_bot::rt::supervise::Supervisor as Default>::default();

    let outcome = sup.run_process(&spec).await;

    match outcome {
        Ok(run) => {
            if run.deadline_fired() {
                drop(run);
                drop(sup);
                return Err(CaptureError::Deadline);
            }
            let total = run.stdout().total_bytes();
            let mut head: Vec<u8> = run.stdout().bytes().to_vec();
            drop(run);
            drop(sup);
            if head.len() > head_limit {
                head.truncate(head_limit);
            }
            if head_limit == 0 {
                head.clear();
            }
            let truncated = total > head_limit as u64;
            Ok(CaptureResult::new(head, total, truncated))
        }
        Err(e) => {
            let dbg = format!("{:?}", e);
            drop(sup);
            drop(spec);
            Err(map_err_dbg(dbg))
        }
    }
}

fn map_err_dbg(dbg: String) -> CaptureError {
    let low = dbg.to_ascii_lowercase();
    let is_deadline = low.contains("deadline")
        || low.contains("timedout")
        || low.contains("timed_out")
        || low.contains("timed out")
        || low.contains("timeout")
        || low.contains("elapsed")
        || low.contains("deadline_fired")
        || low.contains("deadlinefired");
    if is_deadline {
        return CaptureError::Deadline;
    }
    // Distinguish by variant name carried in Debug without naming the
    // non-exhaustive enum or its fields, so field shapes cannot break us.
    let has_after = dbg.contains("AfterStart")
        || dbg.contains("Afterstart")
        || low.contains("afterstart")
        || low.contains("after start")
        || low.contains("after_start");
    let has_notstarted = dbg.contains("NotStarted")
        || dbg.contains("Notstarted")
        || low.contains("notstarted")
        || low.contains("not started")
        || low.contains("not_started");
    let has_refused =
        dbg.contains("Refused") || dbg.contains("refused") || low.contains("refus");
    let has_cancel = low.contains("cancel");

    if has_after {
        return CaptureError::Cancelled;
    }
    if has_refused || has_cancel {
        return CaptureError::Cancelled;
    }
    if has_notstarted {
        return CaptureError::Spawn(dbg);
    }
    // Fallback for future variants: never report an "after" failure as Spawn.
    if low.contains("after") {
        return CaptureError::Cancelled;
    }
    if has_cancel || low.contains("refus") {
        return CaptureError::Cancelled;
    }
    // Unknown with spawn-like hints is a start failure; otherwise be
    // conservative and treat unknown post-start supervisory failures as
    // Cancelled rather than Spawn, since a failure after start must never
    // be Spawn.
    if low.contains("spawn")
        || low.contains("notstarted")
        || low.contains("not started")
        || low.contains("no such")
        || low.contains("not found")
        || low.contains("notstarted")
    {
        return CaptureError::Spawn(dbg);
    }
    // If it looks like nothing ran, report Spawn; if it mentions running,
    // report Cancelled to uphold "never Spawn after start".
    if low.contains("ran") || low.contains("after") || low.contains("start {") {
        CaptureError::Cancelled
    } else if low.contains("cancel") || low.contains("refus") {
        CaptureError::Cancelled
    } else {
        // Default for unrecognized pre-start failures: Spawn with reason.
        // To avoid ever emitting Spawn for a post-start failure we already
        // returned for every "after" hint above; remaining unknowns are
        // treated as start failures only when they do not hint at a run.
        // If in doubt between Spawn/Cancelled for a truly unknown shape,
        // prefer Cancelled when the text hints a group ran.
        if low.contains("after") {
            CaptureError::Cancelled
        } else {
            // Heuristic: if debug names an AfterStart-like shape we already
            // handled; anything else unknown that reached here without
            // deadline/cancel hints is most likely a start failure.
            // Keep the reason for Spawn.
            CaptureError::Spawn(dbg)
        }
    }
}

