pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let stdout_limit =
        NonZeroUsize::new(head_limit).unwrap_or_else(|| NonZeroUsize::new(1).unwrap());
    let stderr_limit = NonZeroUsize::new(65536).unwrap();
    let mut spec = lgwks_bot::rt::process::ProcessSpec::new(argv[0].as_str());
    for a in argv.iter().skip(1) {
        spec.arg(a.as_str());
    }
    spec.capture_stdout(stdout_limit);
    spec.capture_stderr(stderr_limit);
    spec.deadline(deadline);
    let mut sup: lgwks_bot::rt::supervise::Supervisor = Default::default();
    let res = sup.run_process(&spec).await;
    match res {
        Ok(run) => {
            if run.deadline_fired() {
                return Err(CaptureError::Deadline);
            }
            let total = run.stdout().total_bytes();
            let mut head = run.stdout().bytes().to_vec();
            if head.len() > head_limit {
                head.truncate(head_limit);
            }
            let truncated = total > head_limit as u64;
            Ok(CaptureResult::new(head, total, truncated))
        }
        Err(e) => {
            let dbg = format!("{e:?}");
            if dbg.contains("NotStarted") {
                return Err(CaptureError::Spawn(dbg));
            }
            if dbg.contains("Refused") {
                return Err(CaptureError::Cancelled);
            }
            let lower = dbg.to_lowercase();
            if lower.contains("deadline")
                || lower.contains("timed out")
                || lower.contains("timeout")
                || lower.contains("elapsed")
            {
                return Err(CaptureError::Deadline);
            }
            Err(CaptureError::Cancelled)
        }
    }
}

