pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let program = argv[0].clone();
    let args: Vec<String> = argv[1..].to_vec();

    let spec_limit: NonZeroUsize =
        NonZeroUsize::new(head_limit).unwrap_or_else(|| NonZeroUsize::new(1).unwrap());

    let mut spec = lgwks_bot::rt::process::ProcessSpec::new(OsStr::new(&program));
    for a in &args {
        spec.arg(OsStr::new(a));
    }
    spec.capture_stdout(spec_limit);
    spec.deadline(deadline);

    let mut supervisor = make_supervisor();

    let start = std::time::Instant::now();
    let run_result = supervisor.run_process(&spec).await;
    let elapsed = start.elapsed();

    match run_result {
        Ok(run) => {
            if run.deadline_fired() {
                return Err(CaptureError::Deadline);
            }
            let stream = run.stdout();
            let total = stream.total_bytes();
            let raw = stream.bytes();
            let mut head: Vec<u8> = if head_limit == 0 {
                Vec::new()
            } else {
                raw.to_vec()
            };
            if head.len() > head_limit {
                head.truncate(head_limit);
            }
            let truncated = total > head_limit as u64;
            Ok(CaptureResult::new(head, total, truncated))
        }
        Err(e) => Err(map_run_error(e, elapsed, deadline)),
    }
}

fn make_supervisor() -> lgwks_bot::rt::supervise::Supervisor {
    <lgwks_bot::rt::supervise::Supervisor as Default>::default()
}

fn map_run_error(
    e: lgwks_bot::rt::process::ProcessRunError,
    elapsed: Duration,
    deadline: Duration,
) -> CaptureError {
    use lgwks_bot::rt::process::ProcessRunError as PRE;
    match e {
        PRE::Refused => CaptureError::Cancelled,
        PRE::NotStarted { source } => CaptureError::Spawn(source_to_string(source)),
        PRE::AfterStart { source } => {
            if elapsed >= deadline {
                return CaptureError::Deadline;
            }
            let msg = source_to_string(source).to_ascii_lowercase();
            if msg.contains("deadline")
                || msg.contains("timed out")
                || msg.contains("timeout")
                || msg.contains("elapsed")
            {
                CaptureError::Deadline
            } else {
                CaptureError::Cancelled
            }
        }
        _ => CaptureError::Cancelled,
    }
}

fn source_to_string(source: std::io::Error) -> String {
    source.to_string()
}

use std::num::NonZeroUsize;

use lgwks_bot::rt::process::ProcessSpec;
use lgwks_bot::rt::supervise::Supervisor;

#[derive(Debug)]
pub enum CaptureError {
    Spawn(String),
    Deadline,
    Cancelled,
}

#[derive(Debug, PartialEq, Eq)]
pub struct CaptureResult {
    head: Vec<u8>,
    total_bytes: u64,
    truncated: bool,
}

impl CaptureResult {
    pub fn new(head: Vec<u8>, total_bytes: u64, truncated: bool) -> Self {
        Self {
            head,
            total_bytes,
            truncated,
        }
    }

    pub fn head(&self) -> &[u8] {
        &self.head
    }

    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }

    pub fn truncated(&self) -> bool {
        self.truncated
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }

    let mut spec = ProcessSpec::new(argv[0].as_str());
    for arg in argv.iter().skip(1) {
        spec.arg(arg.as_str());
    }

    let one = NonZeroUsize::new(1).expect("1 is non-zero");
    let stdout_limit = NonZeroUsize::new(head_limit).unwrap_or(one);
    spec.capture_stdout(stdout_limit);
    spec.capture_stderr(one);
    spec.deadline(deadline);

    let mut supervisor = Supervisor::new(8);

    let run = match supervisor.run_process(&spec).await {
        Ok(r) => r,
        Err(e) => {
            let dbg = format!("{:?}", e);
            let lower = dbg.to_lowercase();
            if lower.contains("deadline")
                || lower.contains("timedout")
                || lower.contains("timed_out")
                || lower.contains("elapsed")
            {
                return Err(CaptureError::Deadline);
            }
            if dbg.contains("NotStarted") {
                return Err(CaptureError::Spawn(dbg));
            }
            if dbg.contains("Refused") {
                return Err(CaptureError::Cancelled);
            }
            if dbg.contains("AfterStart") {
                return Err(CaptureError::Cancelled);
            }
            if dbg.contains("Spawn") || lower.contains("not started") || lower.contains("notstarted") {
                return Err(CaptureError::Spawn(dbg));
            }
            return Err(CaptureError::Cancelled);
        }
    };

    if run.deadline_fired() {
        return Err(CaptureError::Deadline);
    }

    let total = run.stdout().total_bytes();
    let raw = run.stdout().bytes().to_vec();
    let truncated = total > head_limit as u64;
    let head = if head_limit == 0 {
        Vec::new()
    } else if raw.len() > head_limit {
        raw[..head_limit].to_vec()
    } else {
        raw
    };

    Ok(CaptureResult::new(head, total, truncated))
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

async fn sleep_async(dur: std::time::Duration) {
    if dur.is_zero() {
        return;
    }
    use std::sync::{Arc, Mutex};
    use std::sync::atomic::{AtomicBool, Ordering};
    struct Shared {
        done: AtomicBool,
        waker: Mutex<Option<std::task::Waker>>,
        spawned: AtomicBool,
    }
    let shared = Arc::new(Shared {
        done: AtomicBool::new(false),
        waker: Mutex::new(None),
        spawned: AtomicBool::new(false),
    });
    std::future::poll_fn(|cx| {
        if shared.done.load(Ordering::Acquire) {
            return std::task::Poll::Ready(());
        }
        *shared.waker.lock().unwrap() = Some(cx.waker().clone());
        if !shared.spawned.swap(true, Ordering::AcqRel) {
            let s = shared.clone();
            std::thread::spawn(move || {
                std::thread::sleep(dur);
                s.done.store(true, Ordering::Release);
                let w = s.waker.lock().unwrap().take();
                if let Some(w) = w {
                    w.wake();
                }
            });
        }
        std::task::Poll::Pending
    })
    .await
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let line = format!("applied:{key}");
    let line_with_nl = format!("{line}\n");

    let _ = std::fs::create_dir_all(&effect_dir);

    let already: bool = match std::fs::read_to_string(&applied_path) {
        Ok(content) => content.lines().any(|l| l == line),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => return Err(RecoverError::Deadline),
    };

    let did_append: bool = if already {
        false
    } else {
        let mut opts = std::fs::OpenOptions::new();
        opts.create(true).append(true).write(true);
        match opts.open(&applied_path) {
            Ok(mut f) => {
                use std::io::Write;
                if f.write_all(line_with_nl.as_bytes()).is_err() {
                    return Err(RecoverError::Deadline);
                }
                let _ = f.flush();
                let _ = f.sync_all();
                true
            }
            Err(_) => return Err(RecoverError::Deadline),
        }
    };

    let start = std::time::Instant::now();
    loop {
        if std::fs::metadata(&release_path).is_ok() {
            break;
        }
        let elapsed = start.elapsed();
        if elapsed >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.saturating_sub(elapsed);
        let cap = std::time::Duration::from_millis(10);
        let interval = if remaining < cap { remaining } else { cap };
        if interval.is_zero() {
            return Err(RecoverError::Deadline);
        }
        sleep_async(interval).await;
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let start = std::time::Instant::now();

    let appended: bool = loop {
        match try_mark_applied_once(&effect_dir, &key) {
            Ok(v) => break v,
            Err(_) => {
                if start.elapsed() >= deadline {
                    return Err(RecoverError::Deadline);
                }
                std::thread::sleep(std::time::Duration::from_millis(5));
                coop_yield().await;
                if start.elapsed() >= deadline {
                    return Err(RecoverError::Deadline);
                }
                continue;
            }
        }
    };

    loop {
        let release_path = effect_dir.join("release");
        let present = std::path::Path::new(&release_path).exists();
        if present {
            if appended {
                return Ok(format!("applied:{key}"));
            } else {
                return Ok(format!("recovered:{key}"));
            }
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let elapsed = start.elapsed();
        let remaining = match deadline.checked_sub(elapsed) {
            Some(r) => r,
            None => return Err(RecoverError::Deadline),
        };
        let interval = std::time::Duration::from_millis(5);
        let sleep_for = if remaining < interval { remaining } else { interval };
        if !sleep_for.is_zero() {
            std::thread::sleep(sleep_for);
        }
        coop_yield().await;
    }
}

fn try_mark_applied_once(
    effect_dir: &std::path::Path,
    key: &str,
) -> Result<bool, std::io::Error> {
    match std::fs::create_dir_all(effect_dir) {
        Ok(()) => {},
        Err(e) => return Err(e),
    }

    let log_path = effect_dir.join("applied.log");
    let target = format!("applied:{key}");
    let target_line = format!("applied:{key}\n");

    let already_present: bool = match std::fs::read_to_string(&log_path) {
        Ok(content) => {
            let mut found = false;
            for line in content.lines() {
                if line == target {
                    found = true;
                    break;
                }
            }
            found
        },
        Err(e) => match e.kind() {
            std::io::ErrorKind::NotFound => false,
            _ => return Err(e),
        },
    };

    if already_present {
        return Ok(false);
    }

    let mut file = match std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_path)
    {
        Ok(f) => f,
        Err(e) => return Err(e),
    };

    let write_res: Result<(), std::io::Error> = (|| {
        match std::io::Write::write_all(&mut file, target_line.as_bytes()) {
            Ok(()) => {},
            Err(e) => return Err(e),
        }
        match std::io::Write::flush(&mut file) {
            Ok(()) => {},
            Err(e) => return Err(e),
        }
        match file.sync_all() {
            Ok(()) => {},
            Err(e) => return Err(e),
        }
        Ok(())
    })();

    std::mem::drop(file);

    match write_res {
        Ok(()) => {},
        Err(e) => return Err(e),
    }

    Ok(true)
}

async fn coop_yield() {
    let mut yielded = false;
    std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
        if yielded {
            std::task::Poll::Ready(())
        } else {
            yielded = true;
            cx.waker().wake_by_ref();
            std::task::Poll::Pending
        }
    })
    .await;
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let _ = std::fs::create_dir_all(&effect_dir);
    let log_path = effect_dir.join("applied.log");
    let needle = format!("applied:{key}");
    let already = std::fs::read_to_string(&log_path)
        .map(|c| c.lines().any(|l| l == needle))
        .unwrap_or(false);
    let did_append = if already {
        false
    } else {
        {
            use std::io::Write;
            let mut f = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&log_path)
                .map_err(|_| RecoverError::Deadline)?;
            writeln!(f, "{needle}").map_err(|_| RecoverError::Deadline)?;
            let _ = f.sync_all();
        }
        true
    };
    let release = effect_dir.join("release");
    let start = std::time::Instant::now();
    loop {
        if release.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.saturating_sub(start.elapsed());
        let step = std::cmp::min(remaining, std::time::Duration::from_millis(1));
        if !step.is_zero() {
            std::thread::sleep(step);
        }
        let mut first = true;
        std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
            if first {
                first = false;
                cx.waker().wake_by_ref();
                std::task::Poll::Pending
            } else {
                std::task::Poll::Ready(())
            }
        })
        .await;
    }
    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let start = std::time::Instant::now();
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");

    // Synchronous, atomic-before-first-await check-and-append.
    // No `.await` occurs in this block, so async cancellation cannot
    // interleave in the middle of it. SIGKILL can only leave either
    // zero bytes or the single atomic append behind.
    let did_append: bool = {
        if std::fs::create_dir_all(&effect_dir).is_err() {
            return Err(RecoverError::Deadline);
        }
        let needle = format!("applied:{key}");
        let needle_bytes = needle.as_bytes();
        let already: bool = match std::fs::read(&applied_path) {
            Ok(bytes) => {
                let mut found = false;
                for line in bytes.split(|&b| b == b'\n') {
                    let mut l = line;
                    if !l.is_empty() && l[l.len() - 1] == b'\r' {
                        l = &l[..l.len() - 1];
                    }
                    if l == needle_bytes {
                        found = true;
                        break;
                    }
                }
                found
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
            Err(_) => return Err(RecoverError::Deadline),
        };
        if already {
            false
        } else {
            let line = format!("applied:{key}\n");
            let open_res = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&applied_path);
            let f = match open_res {
                Ok(f) => f,
                Err(_) => return Err(RecoverError::Deadline),
            };
            {
                use std::io::Write as _;
                let mut f = f;
                if f.write_all(line.as_bytes()).is_err() {
                    return Err(RecoverError::Deadline);
                }
                let _ = f.flush();
                let _ = f.sync_all();
            }
            true
        }
    };

    loop {
        if release_path.exists() {
            if did_append {
                return Ok(format!("applied:{key}"));
            } else {
                return Ok(format!("recovered:{key}"));
            }
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.saturating_sub(start.elapsed());
        let interval = std::cmp::min(std::time::Duration::from_millis(5), remaining);
        if interval.is_zero() {
            return Err(RecoverError::Deadline);
        }
        sleep_async(interval).await;
    }
}

async fn sleep_async(dur: std::time::Duration) {
    use std::sync::Arc;
    use std::sync::atomic::{AtomicBool, Ordering};
    if dur.is_zero() {
        return;
    }
    let done = Arc::new(AtomicBool::new(false));
    let spawned = Arc::new(AtomicBool::new(false));
    std::future::poll_fn({
        let done = Arc::clone(&done);
        let spawned = Arc::clone(&spawned);
        move |cx: &mut std::task::Context<'_>| {
            if done.load(Ordering::SeqCst) {
                return std::task::Poll::Ready(());
            }
            if !spawned.swap(true, Ordering::SeqCst) {
                let done2 = Arc::clone(&done);
                let waker = cx.waker().clone();
                std::thread::spawn(move || {
                    std::thread::sleep(dur);
                    done2.store(true, Ordering::SeqCst);
                    waker.wake();
                });
                return std::task::Poll::Pending;
            }
            std::task::Poll::Pending
        }
    })
    .await
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let lock_path = effect_dir.join(".applied.lock");
    let line = format!("applied:{key}");
    let line_nl = format!("applied:{key}\n");

    if std::fs::create_dir_all(&effect_dir).is_err() {
        return Err(RecoverError::Deadline);
    }

    loop {
        match std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&lock_path)
        {
            Ok(_) => break,
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                let stale = std::fs::metadata(&lock_path)
                    .and_then(|m| m.modified())
                    .ok()
                    .and_then(|t| std::time::SystemTime::now().duration_since(t).ok())
                    .map(|d| d.as_secs() >= 2)
                    .unwrap_or(false);
                if stale {
                    let _ = std::fs::remove_file(&lock_path);
                    continue;
                }
                std::thread::sleep(std::time::Duration::from_millis(2));
                yield_now().await;
            }
            Err(_) => {
                std::thread::sleep(std::time::Duration::from_millis(2));
                yield_now().await;
            }
        }
    }

    let appended = {
        let already = match std::fs::read(&applied_path) {
            Ok(bytes) => {
                let target = line.as_bytes();
                bytes.split(|b| *b == b'\n').any(|chunk| {
                    let c = if chunk.last() == Some(&b'\r') {
                        &chunk[..chunk.len() - 1]
                    } else {
                        chunk
                    };
                    c == target
                })
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
            Err(_) => false,
        };
        if already {
            false
        } else {
            {
                use std::io::Write;
                if let Ok(mut f) = std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .write(true)
                    .open(&applied_path)
                {
                    let _ = f.write_all(line_nl.as_bytes());
                    let _ = f.sync_all();
                }
            }
            true
        }
    };

    let _ = std::fs::remove_file(&lock_path);

    let start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline
            .checked_sub(start.elapsed())
            .unwrap_or(std::time::Duration::from_secs(0));
        let sleep_for =
            std::cmp::min(std::time::Duration::from_millis(2), remaining);
        if !sleep_for.is_zero() {
            std::thread::sleep(sleep_for);
        }
        yield_now().await;
    }

    if appended {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

async fn yield_now() {
    let mut yielded = false;
    std::future::poll_fn(|cx| {
        if yielded {
            std::task::Poll::Ready(())
        } else {
            yielded = true;
            cx.waker().wake_by_ref();
            std::task::Poll::Pending
        }
    })
    .await
}

use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FanOut, FanOutError};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(r) => r,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(
    stage: ai_task_support::Stage,
) -> Result<ai_task_support::Published, PipelineError> {
    let fetch_stage = stage.clone();
    let _fetched = FanOut::new([0u8, 1u8])
        .run(|idx| {
            let s = fetch_stage.clone();
            async move {
                if idx == 0 {
                    s.run(ai_task_support::StageName::FetchA)
                        .await
                        .map_err(|_| PipelineError::Stage {
                            name: ai_task_support::StageName::FetchA,
                        })
                } else {
                    s.run(ai_task_support::StageName::FetchB)
                        .await
                        .map_err(|_| PipelineError::Stage {
                            name: ai_task_support::StageName::FetchB,
                        })
                }
            }
        })
        .await
        .map_err(|e| match e {
            FanOutError::Item { error, .. } => error,
            FanOutError::TimedOut { .. } => PipelineError::Deadline,
            _ => PipelineError::Cancelled,
        })?;

    let _combined = stage
        .run(ai_task_support::StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: ai_task_support::StageName::Combine,
        })?;

    let published_artifact = stage
        .run(ai_task_support::StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: ai_task_support::StageName::Publish,
        })?;

    Ok(published_artifact.into())
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let inner = async move {
        let fetcher = stage.clone();
        let fetched = lgwks_bot::script::FanOut::new([
            ai_task_support::StageName::FetchA,
            ai_task_support::StageName::FetchB,
        ])
        .at_most(2)
        .run(|name| {
            let s = fetcher.clone();
            async move { s.run(name).await.map_err(|_| name) }
        })
        .await;
        match fetched {
            Ok(_) => {},
            Err(lgwks_bot::script::FanOutError::Item { error: name, .. }) => {
                return Err(PipelineError::Stage { name });
            }
            Err(lgwks_bot::script::FanOutError::TimedOut { .. }) => {
                return Err(PipelineError::Deadline);
            }
            Err(lgwks_bot::script::FanOutError::Flow(e)) => {
                if e.is_cancelled() {
                    return Err(PipelineError::Cancelled);
                } else {
                    return Err(PipelineError::Deadline);
                }
            }
            Err(_) => {
                return Err(PipelineError::Deadline);
            }
        }
        stage
            .run(ai_task_support::StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Combine,
            })?;
        let artifact = stage
            .run(ai_task_support::StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Publish,
            })?;
        Ok(ai_task_support::Published::from(artifact))
    };
    match lgwks_bot::rt::time::timeout(deadline, inner).await {
        Ok(r) => r,
        Err(_) => Err(PipelineError::Deadline),
    }
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
