struct CancelOnDrop<'a>(&'a lgwks_bot::task::Host);

impl Drop for CancelOnDrop<'_> {
    fn drop(&mut self) {
        self.0.cancel();
    }
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let builder = lgwks_bot::task::Host::builder("recovery").map_err(|_| RecoveryError::NoStore)?;
    let builder = builder
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?;
    let builder = builder.default_deadline(deadline);
    let host = builder.build().map_err(|_| RecoveryError::NoStore)?;
    let _guard = CancelOnDrop(&host);

    let task = lgwks_bot::task::task(
        "recover",
        move |scope: lgwks_bot::script::Scope, _input: ()| {
            let w = world.clone();
            async move {
                let width = w.width();
                let limit = std::num::NonZeroUsize::new(16)
                    .ok_or_else(|| lgwks_bot::script::FlowError::failed("limit"))?;
                let w2 = w.clone();
                let rows: Vec<Result<u64, u32>> = lgwks_bot::script::each(
                    &scope,
                    "units",
                    Some(limit),
                    0..width,
                    move |sub: lgwks_bot::script::Scope, idx: u32| {
                        let ww = w2.clone();
                        async move {
                            match ww.unit(&sub, idx).await {
                                Ok(v) => Ok::<Result<u64, u32>, lgwks_bot::script::FlowError>(Ok(v)),
                                Err(ai_task_support::recovery::UnitError::Unit { index }) => {
                                    Ok(Err(index))
                                }
                                _ => Ok(Err(idx)),
                            }
                        }
                    },
                )
                .await?;
                for r in &rows {
                    if let Err(idx) = r {
                        return Ok::<Result<u64, u32>, lgwks_bot::script::FlowError>(Err(*idx));
                    }
                }
                let total: u64 = rows
                    .into_iter()
                    .map(|r| r.unwrap_or(0))
                    .fold(0u64, |a, b| a.wrapping_add(b));
                if !w.ledger().applied("recover") {
                    w.ledger().apply("recover");
                }
                Ok::<Result<u64, u32>, lgwks_bot::script::FlowError>(Ok(total))
            }
        },
    )
    .map_err(|_| RecoveryError::NoStore)?;

    let run_id = lgwks_bot::effect::RunId::from_hex("0123456789abcdef0123456789abcdef")
        .map_err(|_| RecoveryError::NoStore)?;

    let fut = host.resume(run_id, &task, ());
    let report = match lgwks_bot::rt::time::timeout(deadline, fut).await {
        Ok(r) => r,
        Err(_) => {
            host.cancel();
            return Err(RecoveryError::Deadline);
        }
    };

    match report.disposition() {
        lgwks_bot::task::Disposition::Succeeded => match report.output() {
            Some(Ok(total)) => Ok(*total),
            Some(Err(index)) => Err(RecoveryError::Unit { index: *index }),
            None => Err(RecoveryError::NoLedger),
        },
        lgwks_bot::task::Disposition::DeadlineExceeded => {
            host.cancel();
            Err(RecoveryError::Deadline)
        }
        lgwks_bot::task::Disposition::Cancelled => {
            host.cancel();
            Err(RecoveryError::Deadline)
        }
        lgwks_bot::task::Disposition::Failed => {
            host.cancel();
            Err(RecoveryError::Deadline)
        }
        lgwks_bot::task::Disposition::Refused => Err(RecoveryError::NoStore),
        _ => Err(RecoveryError::NoStore),
    }
}

