struct Cancel<'a> {
    host: &'a lgwks_bot::task::Host,
}

impl Drop for Cancel<'_> {
    fn drop(&mut self) {
        self.host.cancel();
    }
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let host = lgwks_bot::task::Host::builder("recover")
        .map_err(|_| RecoveryError::NoLedger)?
        .default_deadline(deadline)
        .run_store(store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let world_for_task = world.clone();
    let task = lgwks_bot::task::task(
        "recover",
        move |scope: lgwks_bot::script::Scope, _input: ()| {
            let w = world_for_task.clone();
            async move {
                let width = w.width();
                let values = lgwks_bot::script::each(
                    &scope,
                    "units",
                    None,
                    0..width,
                    |sub: lgwks_bot::script::Scope, index: u32| {
                        let ww = w.clone();
                        async move {
                            match ww.unit(&sub, index).await {
                                Ok(v) => Ok(v),
                                Err(_) => Err(
                                    lgwks_bot::script::FlowError::failed(format!(
                                        "unit {}",
                                        index
                                    )),
                                ),
                            }
                        }
                    },
                )
                .await?;
                Ok(values.into_iter().sum::<u64>())
            }
        },
    )
    .map_err(|_| RecoveryError::NoLedger)?;

    let run = lgwks_bot::effect::RunId::from_hex("11111111111111111111111111111111")
        .map_err(|_| RecoveryError::NoStore)?;

    let _guard = Cancel { host: &host };

    let report = match lgwks_bot::rt::time::timeout(deadline, host.resume(run, &task, ())).await
    {
        Ok(r) => r,
        Err(_) => {
            host.cancel();
            return Err(RecoveryError::Deadline);
        }
    };

    match report.into_result() {
        Ok(total) => {
            let ledger = world.ledger();
            if !ledger.applied("recover") {
                ledger.apply("recover");
            }
            Ok(total)
        }
        Err(e) => {
            if e.is_cancelled() {
                host.cancel();
                return Err(RecoveryError::Deadline);
            }
            match e {
                lgwks_bot::script::FlowError::TimedOut { .. } => {
                    host.cancel();
                    Err(RecoveryError::Deadline)
                }
                lgwks_bot::script::FlowError::Cancelled { .. } => {
                    host.cancel();
                    Err(RecoveryError::Deadline)
                }
                lgwks_bot::script::FlowError::Failed { reason, .. } => {
                    if let Some(rest) = reason.strip_prefix("unit ") {
                        if let Ok(idx) = rest.trim().parse::<u32>() {
                            return Err(RecoveryError::Unit { index: idx });
                        }
                    }
                    if let Some(last) = reason.split_whitespace().last() {
                        if let Ok(idx) = last.parse::<u32>() {
                            return Err(RecoveryError::Unit { index: idx });
                        }
                    }
                    Err(RecoveryError::NoLedger)
                }
                other => {
                    if other.is_cancelled() {
                        host.cancel();
                        Err(RecoveryError::Deadline)
                    } else {
                        Err(RecoveryError::NoLedger)
                    }
                }
            }
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::rt::time::timeout;
use lgwks_bot::script::{FlowError, Scope, each};
use lgwks_bot::task::{Host, task};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let run =
        RunId::from_hex("00000000000000000000000000000001").map_err(|_| RecoveryError::NoStore)?;
    let fail: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let fail_task = fail.clone();

    let host = Host::builder("recover")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .max_concurrent_tasks(NonZeroUsize::new(16).ok_or(RecoveryError::NoStore)?)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let t = task("recover", move |scope: Scope, w: World| {
        let f = fail_task.clone();
        async move {
            let width = w.width();
            let vals: Vec<u64> = each(&scope, "units", None, 0..width, |s: Scope, idx: u32| {
                let ww = w.clone();
                let ff = f.clone();
                async move {
                    match ww.unit(&s, idx).await {
                        Ok(v) => Ok(v),
                        Err(e) => {
                            let ui = match e {
                                ai_task_support::recovery::UnitError::Unit { index } => index,
                                _ => idx,
                            };
                            if let Ok(mut g) = ff.lock() {
                                *g = Some(ui);
                            }
                            Err(FlowError::failed(format!("unit {}", ui)))
                        }
                    }
                }
            })
            .await?;
            let total: u64 = vals.into_iter().sum();
            if !w.ledger().applied("recover") {
                w.ledger().apply("recover");
            }
            Ok(total)
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let world2 = world.clone();
    let report = timeout(deadline, host.resume(run, &t, world2))
        .await
        .map_err(|_| RecoveryError::Deadline)?;

    if report.disposition().is_success() {
        let total = *report.output().ok_or(RecoveryError::NoLedger)?;
        if !world.ledger().applied("recover") {
            world.ledger().apply("recover");
        }
        Ok(total)
    } else {
        if let Some(e) = report.error() {
            if e.is_cancelled() {
                return Err(RecoveryError::Deadline);
            }
            if matches!(e, FlowError::TimedOut { .. }) {
                return Err(RecoveryError::Deadline);
            }
            if matches!(e, FlowError::Cancelled { .. }) {
                return Err(RecoveryError::Deadline);
            }
        }
        if let Ok(g) = fail.lock() {
            if let Some(idx) = *g {
                return Err(RecoveryError::Unit { index: idx });
            }
        }
        return Err(RecoveryError::Deadline);
    }
}

