) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let work = futures::stream::iter(ids)
        .map(move |id| {
            let f = fetch.clone();
            async move { f.fetch(id).await.map_err(|_| SolveError::Fetch { id }) }
        })
        .buffer_unordered(4)
        .try_fold(0u64, |sum, v| async move {
            Ok::<u64, SolveError>(sum + v)
        });
    match lgwks_bot::rt::time::timeout(deadline, work).await {
        Ok(r) => r,
        Err(_) => Err(SolveError::Deadline),
    }
}

