#[cfg(unix)]
unsafe extern "C" {
    fn kill(pid: i32, sig: i32) -> i32;
    fn fcntl(fd: i32, cmd: i32, arg: i32) -> i32;
}

struct Guard(Option<std::process::Child>);

impl Drop for Guard {
    fn drop(&mut self) {
        if let Some(mut c) = self.0.take() {
            #[cfg(unix)]
            {
                let pid = c.id() as i32;
                unsafe {
                    let _ = kill(-pid, 9);
                    let _ = kill(pid, 9);
                }
                let _ = c.kill();
                let _ = c.wait();
                unsafe {
                    let mut waited: u32 = 0;
                    loop {
                        let exists = kill(-pid, 0) == 0;
                        if !exists {
                            break;
                        }
                        if waited >= 200 {
                            break;
                        }
                        let _ = kill(-pid, 9);
                        let _ = kill(pid, 9);
                        std::thread::sleep(std::time::Duration::from_millis(5));
                        waited += 1;
                    }
                }
            }
            #[cfg(not(unix))]
            {
                let _ = c.kill();
                let _ = c.wait();
            }
        }
    }
}

async fn run_capture(
    mut child: std::process::Child,
    head_limit: usize,
) -> Result<CaptureResult, CaptureError> {
    let mut out_opt: Option<std::process::ChildStdout> = child.stdout.take();

    #[cfg(unix)]
    if let Some(ref o) = out_opt {
        use std::os::unix::io::AsRawFd;
        let fd = o.as_raw_fd();
        unsafe {
            let flags = fcntl(fd, 3, 0);
            if flags != -1 {
                #[cfg(target_os = "linux")]
                let onb: i32 = 0o4000;
                #[cfg(not(target_os = "linux"))]
                let onb: i32 = 4;
                let _ = fcntl(fd, 4, flags | onb);
            }
        }
    }

    let mut guard = Guard(Some(child));
    let mut head: Vec<u8> = Vec::new();
    let mut total: u64 = 0;
    let mut eof = out_opt.is_none();
    let mut buf = [0u8; 8192];

    loop {
        if !eof {
            if let Some(out) = out_opt.as_mut() {
                loop {
                    match out.read(&mut buf) {
                        Ok(0) => {
                            eof = true;
                            break;
                        }
                        Ok(n) => {
                            total += n as u64;
                            if head.len() < head_limit {
                                let need = head_limit - head.len();
                                let take = if need < n { need } else { n };
                                head.extend_from_slice(&buf[..take]);
                            }
                        }
                        Err(e)
                            if e.kind() == std::io::ErrorKind::WouldBlock =>
                        {
                            break;
                        }
                        Err(e)
                            if e.kind() == std::io::ErrorKind::Interrupted =>
                        {
                            continue;
                        }
                        Err(_) => {
                            eof = true;
                            break;
                        }
                    }
                }
            } else {
                eof = true;
            }
        }

        let exited = match guard.0.as_mut().unwrap().try_wait() {
            Ok(Some(_)) => true,
            Ok(None) => false,
            Err(_) => true,
        };

        if eof && exited {
            break;
        }

        lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(5)).await;
    }

    if let Some(mut ch) = guard.0.take() {
        let _ = ch.wait();
    }
    let truncated = total > head_limit as u64;
    Ok(CaptureResult::new(head, total, truncated))
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 {
