struct Shared {
    head: Vec<u8>,
    total: u64,
    done: bool,
}

struct Guard {
    child: Option<std::process::Child>,
    pgid: i32,
    handle: Option<std::thread::JoinHandle<()>>,
}

impl Drop for Guard {
    fn drop(&mut self) {
        #[cfg(unix)]
        {
            if self.pgid > 0 {
                unsafe {
                    let _ = kill(-self.pgid, 9);
                }
            }
        }
        if let Some(c) = self.child.as_mut() {
            let _ = c.kill();
        }
        if let Some(mut c) = self.child.take() {
            let _ = c.wait();
        }
        #[cfg(unix)]
        {
            if self.pgid > 0 {
                unsafe {
                    let _ = kill(-self.pgid, 9);
                }
            }
            self.pgid = 0;
        }
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

fn spawn_child(argv: &[String]) -> std::io::Result<std::process::Child> {
    use std::process::{Command, Stdio};
    let mut cmd = Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::null());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        #[allow(unused_unsafe)]
        unsafe {
            cmd.pre_exec(|| {
                #[allow(unused_unsafe)]
                unsafe {
                    let r = setpgid(0, 0);
                    if r != 0 {
                        return Err(std::io::Error::last_os_error());
                    }
                }
                Ok(())
            });
        }
    }
    cmd.spawn()
}

fn reader_loop(
    pipe: std::process::ChildStdout,
    shared: std::sync::Arc<std::sync::Mutex<Shared>>,
    head_limit: usize,
) {
    use std::io::Read;
    let mut p = pipe;
    let mut buf = [0u8; 8192];
    let limit = head_limit as u64;
    loop {
        match p.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                let take_bytes = &buf[..n];
                let mut g = match shared.lock() {
                    Ok(g) => g,
                    Err(e) => e.into_inner(),
                };
                let before = g.total;
                g.total = g.total.saturating_add(n as u64);
                if before < limit {
                    let remaining = limit - before;
                    let take = (remaining as usize).min(n);
                    g.head.extend_from_slice(&take_bytes[..take]);
                }
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                } else {
                    break;
                }
            }
        }
    }
    match shared.lock() {
        Ok(mut g) => {
            g.done = true;
        }
        Err(e) => {
            let mut g = e.into_inner();
            g.done = true;
        }
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let shared = std::sync::Arc::new(std::sync::Mutex::new(Shared {
        head: Vec::new(),
        total: 0,
        done: false,
    }));
    let mut child = match spawn_child(&argv) {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let pgid = child.id() as i32;
    let stdout_opt = child.stdout.take();
    let handle_opt = match stdout_opt {
        Some(pipe) => {
            let sh = shared.clone();
            Some(std::thread::spawn(move || reader_loop(pipe, sh, head_limit)))
        }
        None => {
            match shared.lock() {
                Ok(mut g) => {
                    g.done = true;
                }
                Err(e) => {
                    let mut g = e.into_inner();
                    g.done = true;
                }
            }
            None
        }
    };
    let mut guard = Guard {
        child: Some(child),
        pgid,
        handle: handle_opt,
    };
    let start = std::time::Instant::now();
    loop {
        let exited = match guard.child.as_mut() {
            Some(c) => match c.try_wait() {
                Ok(Some(_)) => true,
                Ok(None) => false,
                Err(_) => true,
            },
            None => true,
        };
        let done = match shared.lock() {
            Ok(g) => g.done,
            Err(e) => e.into_inner().done,
        };
        if exited && done {
            let (head, total) = match shared.lock() {
                Ok(g) => (g.head.clone(), g.total),
                Err(e) => {
                    let g = e.into_inner();
                    (g.head.clone(), g.total)
                }
            };
            let truncated = total > head_limit as u64;
            // Disarm: child already reaped via try_wait; avoid killing
            // a possibly reused pgid after success.
            if let Some(mut c) = guard.child.take() {
                let _ = c.wait();
            }
            guard.pgid = 0;
            if let Some(h) = guard.handle.take() {
                let _ = h.join();
            }
            return Ok(CaptureResult::new(head, total, truncated));
        }
        if start.elapsed() >= deadline {
            // guard drops here, killing the whole process group and
            // reaping, before the caller observes Deadline.
            return Err(CaptureError::Deadline);
        }
        lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(1)).await;
    }
}

