pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    struct Guard {
        pgid: Option<i32>,
    }
    impl Drop for Guard {
        fn drop(&mut self) {
            if let Some(pgid) = self.pgid {
                unsafe {
                    libc_killpg(pgid, 9);
                }
                unsafe {
                    let mut status = 0;
                    waitpid_wait(pgid, &mut status);
                }
            }
        }
    }

    let mut cmd = std::process::Command::new(&argv[0]);
    cmd.args(&argv[1..]);
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::null());
    unsafe {
        cmd.pre_exec(|| {
            unsafe {
                libc_setpgid(0, 0);
            }
            Ok(())
        });
    }

    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };

    let pgid = child.id() as i32;
    let mut guard = Guard { pgid: Some(pgid) };

    let stdout = child.stdout.take().expect("piped");

    use std::os::unix::io::AsRawFd;
    let fd = stdout.as_raw_fd();
    unsafe { set_nonblocking(fd) };

    let inner = async {
        let mut head: Vec<u8> = Vec::new();
        let mut total: u64 = 0;
        let mut buf = [0u8; 8192];
        let mut done = false;
        loop {
            loop {
                let n = unsafe { libc_read(fd, buf.as_mut_ptr(), buf.len()) };
                if n > 0 {
                    let n = n as usize;
                    total = total.saturating_add(n as u64);
                    if head.len() < head_limit {
                        let want = (head_limit - head.len()).min(n);
                        head.extend_from_slice(&buf[..want]);
                    }
                } else if n == 0 {
                    done = true;
                    break;
                } else {
                    let e = unsafe { errno() };
                    if e == 11 || e == 35 {
                        break;
                    } else if e == 4 {
                        continue;
                    } else {
                        break;
                    }
                }
            }
            if done {
                unsafe {
                    let mut status = 0;
                    let r = waitpid_nohang(pgid, &mut status);
                    if r == pgid {
                        guard.pgid = None;
                        let truncated = total > head_limit as u64;
                        return Ok::<CaptureResult, CaptureError>(CaptureResult::new(head, total, truncated));
                    } else if r == 0 {
                    } else {
                        guard.pgid = None;
                        let truncated = total > head_limit as u64;
                        return Ok::<CaptureResult, CaptureError>(CaptureResult::new(head, total, truncated));
                    }
                }
                lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(5)).await;
                done = false;
                continue;
            }
            unsafe {
                let mut status = 0;
                let r = waitpid_nohang(pgid, &mut status);
                if r == pgid {
                    guard.pgid = None;
                    let mut extra_done = false;
                    for _ in 0..1000 {
                        let mut any = false;
                        loop {
                            let n2 = libc_read(fd, buf.as_mut_ptr(), buf.len());
                            if n2 > 0 {
                                any = true;
                                let n2 = n2 as usize;
                                total = total.saturating_add(n2 as u64);
                                if head.len() < head_limit {
                                    let want = (head_limit - head.len()).min(n2);
                                    head.extend_from_slice(&buf[..want]);
                                }
                            } else if n2 == 0 {
                                extra_done = true;
                                break;
                            } else {
                                let e2 = errno();
                                if e2 == 11 || e2 == 35 {
                                    break;
                                } else if e2 == 4 {
                                    continue;
                                } else {
                                    break;
                                }
                            }
                        }
                        if extra_done {
                            break;
                        }
                        if !any {
                            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(1)).await;
                        }
                    }
                    let truncated = total > head_limit as u64;
                    return Ok::<CaptureResult, CaptureError>(CaptureResult::new(head, total, truncated));
                }
            }
            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(1)).await;
        }
    };

    let res = lgwks_bot::rt::time::timeout(deadline, inner).await;
    match res {
        Ok(v) => v,
        Err(_) => {
            unsafe { libc_killpg(pgid, 9); }
            unsafe {
                let mut status = 0;
                waitpid_wait(pgid, &mut status);
            }
            guard.pgid = None;
            Err(CaptureError::Deadline)
        }
    }
}

// ---- minimal libc bindings via std only (no libc crate) ----
unsafe extern "C" {
    fn killpg(pgid: i32, sig: i32) -> i32;
    fn setpgid(pid: i32, pgid: i32) -> i32;
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
    fn fcntl(fd: i32, cmd: i32, arg: i32) -> i32;
    fn __error() -> *mut i32;
    fn __errno_location() -> *mut i32;
    fn waitpid(pid: i32, status: *mut i32, options: i32) -> i32;
}

unsafe fn libc_killpg(pgid: i32, sig: i32) {
    killpg(pgid, sig);
}
unsafe fn libc_setpgid(pid: i32, pgid: i32) -> i32 {
    setpgid(pid, pgid)
}
unsafe fn libc_read(fd: i32, buf: *mut u8, count: usize) -> isize {
    read(fd, buf, count)
}
unsafe fn errno() -> i32 {
    #[cfg(target_os = "macos")]
    unsafe { *__error() }
    #[cfg(target_os = "linux")]
    unsafe { *__errno_location() }
    #[cfg(not(any(target_os = "macos", target_os = "linux")))]
    { 11 }
}
unsafe fn set_nonblocking(fd: i32) {
    const F_GETFL: i32 = 3;
    const F_SETFL: i32 = 4;
    #[cfg(target_os = "macos")]
    const O_NONBLOCK: i32 = 0x0004;
    #[cfg(target_os = "linux")]
    const O_NONBLOCK: i32 = 0o2000;
    #[cfg(not(any(target_os = "macos", target_os = "linux")))]
    const O_NONBLOCK: i32 = 0x800;
    let flags = fcntl(fd, F_GETFL, 0);
    fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}
unsafe fn waitpid_nohang(pid: i32, status: *mut i32) -> i32 {
    const WNOHANG: i32 = 1;
    waitpid(pid, status, WNOHANG)
}
unsafe fn waitpid_wait(pid: i32, status: *mut i32) {
    loop {
        let r = waitpid(pid, status, 0);
        if r == pid {
            break;
        }
        if r < 0 {
            let e = errno();
            if e == 4 {
                continue;
            }
            break;
        }
        break;
    }
}

