const SIGKILL_: i32 = 9;
const F_GETFL_: i32 = 3;
const F_SETFL_: i32 = 4;
#[cfg(target_os = "linux")]
const O_NONBLOCK_: i32 = 0o4000;
#[cfg(not(target_os = "linux"))]
const O_NONBLOCK_: i32 = 0x4;

fn set_nonblocking_(fd: i32) -> std::io::Result<()> {
    unsafe {
        let flags = fcntl(fd, F_GETFL_, 0);
        if flags < 0 {
            return Err(std::io::Error::last_os_error());
        }
        if fcntl(fd, F_SETFL_, flags | O_NONBLOCK_) < 0 {
            return Err(std::io::Error::last_os_error());
        }
    }
    Ok(())
}

struct Guard_ {
    pid: i32,
    child: Option<std::process::Child>,
}

impl Drop for Guard_ {
    fn drop(&mut self) {
        unsafe {
            let _ = kill(-self.pid, SIGKILL_);
            let _ = kill(self.pid, SIGKILL_);
        }
        if let Some(c) = self.child.as_mut() {
            let still_running = match c.try_wait() {
                Ok(Some(_)) => false,
                Ok(None) => true,
                Err(_) => true,
            };
            if still_running {
                let _ = c.wait();
            }
        }
    }
}

