    cmd.stderr(std::process::Stdio::null());
    unsafe {
        cmd.pre_exec(|| {
            let r = unsafe { setsid() };
            if r < 0 {
                return Err(std::io::Error::last_os_error());
            }
            Ok(())
        });
    }
    let child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let mut guard = Guard_ {
        pid: child.id() as i32,
        child: Some(child),
    };
    let pid_num = guard.pid;
    let mut out = match guard.child.as_mut().unwrap().stdout.take() {
        Some(o) => o,
        None => {
            return Err(CaptureError::Cancelled);
        }
    };
    {
        let fd = out.as_raw_fd();
        if set_nonblocking_(fd).is_err() {
            return Err(CaptureError::Cancelled);
        }
    }

    let start = std::time::Instant::now();
    let mut head_vec: Vec<u8> = Vec::new();
    if head_limit > 0 {
        let cap = if head_limit < 8192 { head_limit } else { 8192 };
        head_vec.reserve(cap);
    }
    let mut total: u64 = 0;
    let mut buf = [0u8; 8192];
    let mut eof = false;
    let mut done = false;

    loop {
        let mut got_data = false;
        let mut would_block = false;
        if !eof {
            match out.read(&mut buf) {
                Ok(0) => {
                    eof = true;
                }
                Ok(n) => {
                    total += n as u64;
                    if head_vec.len() < head_limit {
                        let rem = head_limit - head_vec.len();
                        let take = if n < rem { n } else { rem };
                        head_vec.extend_from_slice(&buf[..take]);
                    }
                    got_data = true;
                }
                Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                    would_block = true;
                }
                Err(e) if e.kind() == std::io::ErrorKind::Interrupted => {
                    continue;
                }
                Err(_) => {
                    return Err(CaptureError::Cancelled);
                }
            }
        }

        let exited = match guard.child.as_mut().unwrap().try_wait() {
            Ok(Some(_)) => true,
            Ok(None) => false,
            Err(_) => {
                return Err(CaptureError::Cancelled);
            }
        };
        if exited {
            done = true;
        }

        if done {
            if eof {
                break;
            }
            if would_block {
                break;
            }
            if got_data {
                continue;
            }
            continue;
        } else {
            if start.elapsed() >= deadline {
                unsafe {
                    let _ = kill(-pid_num, SIGKILL_);
                    let _ = kill(pid_num, SIGKILL_);
                }
                let _ = guard.child.as_mut().unwrap().wait();
                return Err(CaptureError::Deadline);
            }
            if got_data {
                continue;
            }
            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(1)).await;
        }
    }

    let truncated = total > head_limit as u64;
    Ok(CaptureResult::new(head_vec, total, truncated))
}

