    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    static LOCK: std::sync::OnceLock<std::sync::Mutex<()>> =
        std::sync::OnceLock::new();

    let did_append: bool = {
        let lock = LOCK.get_or_init(|| std::sync::Mutex::new(()));
        let _guard = lock.lock().unwrap_or_else(|e| e.into_inner());

        let _ = std::fs::create_dir_all(&effect_dir);
        let log_path = effect_dir.join("applied.log");
        let target = format!("applied:{}", key);
        let already: bool = match std::fs::read_to_string(&log_path) {
            Ok(content) => content.lines().any(|line| line == target),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
            Err(_) => false,
        };
        if already {
            false
        } else {
            let mut opts = std::fs::OpenOptions::new();
            opts.create(true).append(true).write(true);
            let data = format!("{}\n", target);
            match opts.open(&log_path) {
                Ok(mut f) => {
                    use std::io::Write as _;
                    let _ = f.write_all(data.as_bytes());
                    let _ = f.sync_all();
                }
                Err(_) => {
                    let _ = std::fs::create_dir_all(&effect_dir);
                    if let Ok(mut f) = opts.open(&log_path) {
                        use std::io::Write as _;
                        let _ = f.write_all(data.as_bytes());
                        let _ = f.sync_all();
                    }
                }
            }
            if let Ok(d) = std::fs::File::open(&effect_dir) {
                let _ = d.sync_all();
            }
            true
        }
    };

    let release_path = effect_dir.join("release");
    let start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            if did_append {
                return Ok(format!("applied:{}", key));
            } else {
                return Ok(format!("recovered:{}", key));
            }
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let elapsed = start.elapsed();
        let remaining = deadline
            .checked_sub(elapsed)
            .unwrap_or(std::time::Duration::ZERO);
        let step = std::cmp::min(remaining, std::time::Duration::from_millis(5));
        if step.is_zero() {
            return Err(RecoverError::Deadline);
        }
        lgwks_bot::rt::time::sleep(step).await;
    }
}

