) -> Result<String, RecoverError> {
    use std::io::Write;

    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");

    match std::fs::create_dir_all(&effect_dir) {
        Ok(()) => {},
        Err(_) => {
            return Err(RecoverError::Deadline);
        }
    }

    let target_line = format!("applied:{key}");

    let already_applied: bool = match std::fs::read_to_string(&applied_path) {
        Ok(content) => {
            let mut found = false;
            for line in content.lines() {
                if line == target_line {
                    found = true;
                    break;
                }
            }
            found
        }
        Err(e) => match e.kind() {
            std::io::ErrorKind::NotFound => false,
            _ => {
                return Err(RecoverError::Deadline);
            }
        },
    };

    let did_append: bool = if already_applied {
        false
    } else {
        let mut open_opts = std::fs::OpenOptions::new();
        open_opts.create(true).append(true).write(true);
        let mut file = match open_opts.open(&applied_path) {
            Ok(f) => f,
            Err(_) => {
                return Err(RecoverError::Deadline);
            }
        };
        let line_text = format!("applied:{key}\n");
        let bytes = line_text.as_bytes();
        match file.write_all(bytes) {
            Ok(()) => {},
            Err(_) => {
                drop(file);
                return Err(RecoverError::Deadline);
            }
        }
        match file.flush() {
            Ok(()) => {},
            Err(_) => {
                drop(file);
                return Err(RecoverError::Deadline);
            }
        }
        {
            let _ = file.sync_all();
        }
        drop(file);
        match std::fs::File::open(&effect_dir) {
            Ok(d) => {
                let _ = d.sync_all();
                drop(d);
            }
            Err(_) => {}
        }
        true
    };

    let start = std::time::Instant::now();
    loop {
        let release_exists: bool = match std::fs::metadata(&release_path) {
            Ok(_) => true,
            Err(_) => {
                if release_path.exists() {
                    true
                } else {
                    false
                }
            }
        };
        if release_exists {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        std::thread::sleep(std::time::Duration::from_millis(1));
        {
            let mut yielded = false;
            std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
                if yielded {
                    std::task::Poll::Ready(())
                } else {
                    yielded = true;
                    cx.waker().wake_by_ref();
                    std::task::Poll::Pending
                }
            })
            .await;
        }
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

