    Deadline,
}

struct SleepState {
    deadline: std::time::Instant,
    started: bool,
    shared: std::sync::Arc<std::sync::Mutex<Option<std::task::Waker>>>,
}

impl std::future::Future for SleepState {
    type Output = ();
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<()> {
        let this = self.get_mut();
        if std::time::Instant::now() >= this.deadline {
            return std::task::Poll::Ready(());
        }
        match this.shared.lock() {
            Ok(mut g) => {
                *g = Some(cx.waker().clone());
            }
            Err(poison) => {
                *poison.into_inner() = Some(cx.waker().clone());
            }
        }
        if !this.started {
            this.started = true;
            let shared = this.shared.clone();
            let deadline = this.deadline;
            std::thread::spawn(move || {
                let now = std::time::Instant::now();
                if deadline > now {
                    std::thread::sleep(deadline - now);
                }
                let waker_opt = match shared.lock() {
                    Ok(mut g) => g.take(),
                    Err(poison) => poison.into_inner().take(),
                };
                if let Some(w) = waker_opt {
                    w.wake();
                }
            });
        }
        std::task::Poll::Pending
    }
}

fn sleep_async(dur: std::time::Duration) -> SleepState {
    SleepState {
        deadline: std::time::Instant::now() + dur,
        started: false,
        shared: std::sync::Arc::new(std::sync::Mutex::new(None)),
    }
}

