pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let target = format!("applied:{key}");

    if std::fs::create_dir_all(&effect_dir).is_err() {
        return Err(RecoverError::Deadline);
    }

    let already_present: bool = match std::fs::read_to_string(&log_path) {
        Ok(content) => content.lines().any(|l| l == target),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => return Err(RecoverError::Deadline),
    };

    let did_append: bool = if already_present {
        false
    } else {
        use std::io::Write as _;
        match std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)
        {
            Ok(mut f) => {
                let line = format!("{target}\n");
                if f.write_all(line.as_bytes()).is_err() {
                    return Err(RecoverError::Deadline);
                }
                let _ = f.sync_all();
                if let Ok(df) = std::fs::File::open(&effect_dir) {
                    let _ = df.sync_all();
                }
                true
            }
            Err(_) => return Err(RecoverError::Deadline),
        }
    };

    let start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            if did_append {
                return Ok(format!("applied:{key}"));
            } else {
                return Ok(format!("recovered:{key}"));
            }
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.saturating_sub(start.elapsed());
        let step = std::time::Duration::from_millis(10).min(remaining);
        if step.is_zero() {
            return Err(RecoverError::Deadline);
        }
        async_sleep(step).await;
    }
}

async fn async_sleep(dur: std::time::Duration) {
    if dur.is_zero() {
        return;
    }
    let start = std::time::Instant::now();
    std::future::poll_fn(move |cx: &mut std::task::Context<'_>| {
        if start.elapsed() >= dur {
            std::task::Poll::Ready(())
        } else {
            let waker = cx.waker().clone();
            let rem = dur.saturating_sub(start.elapsed());
            std::thread::spawn(move || {
                std::thread::sleep(rem);
                waker.wake();
            });
            std::task::Poll::Pending
        }
    })
    .await
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let a_stage = stage.clone();
    let b_stage = stage.clone();
    let c_stage = stage.clone();
    let p_stage = stage;
    let work = async move {
        let (a_art, b_art) = futures::future::try_join(
            async move {
                a_stage
                    .run(ai_task_support::StageName::FetchA)
                    .await
                    .map_err(|_| PipelineError::Stage {
                        name: ai_task_support::StageName::FetchA,
                    })
            },
            async move {
                b_stage
                    .run(ai_task_support::StageName::FetchB)
                    .await
                    .map_err(|_| PipelineError::Stage {
                        name: ai_task_support::StageName::FetchB,
                    })
            },
        )
        .await?;
        let _ = (a_art, b_art);
        let c_art = c_stage
            .run(ai_task_support::StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Combine,
            })?;
        let _ = c_art;
        let p_art = p_stage
            .run(ai_task_support::StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Publish,
            })?;
        Ok::<ai_task_support::Published, PipelineError>(ai_task_support::Published::from(p_art))
    };
    match lgwks_bot::rt::time::timeout(deadline, work).await {
        Ok(inner) => inner,
        Err(_) => Err(PipelineError::Deadline),
    }
}

