}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let inner = async move {
        let fetch_a = stage
            .run(ai_task_support::StageName::FetchA)
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::FetchA,
            });
        let fetch_b = stage
            .run(ai_task_support::StageName::FetchB)
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::FetchB,
            });
        let fetch_result = futures::future::try_join(fetch_a, fetch_b).await;
        let (artifact_a, artifact_b) = match fetch_result {
            Ok(pair) => pair,
            Err(e) => return Err(e),
        };
        drop(artifact_a);
        drop(artifact_b);
        let combine_result = stage.run(ai_task_support::StageName::Combine).await;
        let artifact_c = match combine_result {
            Ok(v) => v,
            Err(_) => {
                return Err(PipelineError::Stage {
                    name: ai_task_support::StageName::Combine,
                });
            }
        };
        drop(artifact_c);
        let publish_result = stage.run(ai_task_support::StageName::Publish).await;
        let artifact_p = match publish_result {
            Ok(v) => v,
            Err(_) => {
                return Err(PipelineError::Stage {
                    name: ai_task_support::StageName::Publish,
                });
            }
        };
        let published = ai_task_support::Published::from(artifact_p);
        drop(stage);
        Ok(published)
    };
    let timed = lgwks_bot::rt::time::timeout(deadline, inner).await;
    match timed {
        Ok(v) => v,
        Err(_) => Err(PipelineError::Deadline),
    }
}

