#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let instant = std::time::Instant::now() + deadline;
    let mut pending: std::collections::VecDeque<u32> = ids.into();
    let mut in_flight: Vec<
        std::pin::Pin<Box<dyn std::future::Future<Output = Result<u64, u32>> + Send>>,
    > = Vec::new();
    let mut sum: u64 = 0;
    let slot: std::sync::Arc<std::sync::Mutex<Option<std::task::Waker>>> =
        std::sync::Arc::new(std::sync::Mutex::new(None));
    let mut timer_started = false;
    std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
        loop {
            let mut idx = 0usize;
            while idx < in_flight.len() {
                match in_flight[idx].as_mut().poll(cx) {
                    std::task::Poll::Ready(Ok(v)) => {
                        sum = sum.wrapping_add(v);
                        in_flight.swap_remove(idx);
                    }
                    std::task::Poll::Ready(Err(fid)) => {
                        return std::task::Poll::Ready(Err(SolveError::Fetch { id: fid }));
                    }
                    std::task::Poll::Pending => {
                        idx += 1;
                    }
                }
            }
            if pending.is_empty() && in_flight.is_empty() {
                return std::task::Poll::Ready(Ok(sum));
            }
            if std::time::Instant::now() >= instant {
                return std::task::Poll::Ready(Err(SolveError::Deadline));
            }
            let mut started = false;
            while in_flight.len() < 4 {
                if let Some(id) = pending.pop_front() {
                    let fc = fetch.clone();
                    let fut: std::pin::Pin<
                        Box<dyn std::future::Future<Output = Result<u64, u32>> + Send>,
                    > = Box::pin(async move {
                        match fc.fetch(id).await {
                            Ok(v) => Ok(v),
                            Err(_) => Err(id),
                        }
                    });
                    in_flight.push(fut);
                    started = true;
                } else {
                    break;
                }
            }
            if started {
                continue;
            }
            if let Ok(mut g) = slot.lock() {
                *g = Some(cx.waker().clone());
            }
            if !timer_started {
                timer_started = true;
                let s = slot.clone();
                let dl = instant;
                std::thread::spawn(move || {
                    let now = std::time::Instant::now();
                    if dl > now {
                        std::thread::sleep(dl - now);
                    }
                    let w = match s.lock() {
                        Ok(g) => g.clone(),
                        Err(_) => None,
                    };
                    if let Some(w) = w {
                        w.wake();
                    }
                });
            }
            return std::task::Poll::Pending;
        }
    })
    .await
}

use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::sync::Arc;
use std::sync::Mutex;
use std::sync::atomic::AtomicBool;
use std::sync::atomic::Ordering;
use std::task::Context;
use std::task::Poll;
use std::task::Waker;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

struct TimerShared {
    done: AtomicBool,
    waker: Mutex<Option<Waker>>,
    thread_handle: Mutex<Option<std::thread::Thread>>,
}

struct TimerFut {
    deadline: Option<std::time::Instant>,
    shared: Arc<TimerShared>,
    spawned: bool,
}

type FetchBoxFut = Pin<Box<dyn Future<Output = (u32, Result<u64, ai_task_support::FetchError>)> + Send>>;

struct Slot {
    fut: FetchBoxFut,
}

struct AggFuture {
    pending: VecDeque<u32>,
    in_flight: Vec<Slot>,
    sum: u64,
    fetcher: ai_task_support::Fetcher,
    timer: TimerFut,
}

fn timer_thread_main(shared: Arc<TimerShared>, deadline: std::time::Instant) {
    let cur = std::thread::current();
    match shared.thread_handle.lock() {
        Ok(mut g) => {
            *g = Some(cur);
        }
        Err(p) => {
            let mut g = p.into_inner();
            *g = Some(cur);
        }
    }
    loop {
        if shared.done.load(Ordering::SeqCst) {
            break;
        }
        let now = std::time::Instant::now();
        if now >= deadline {
            let wopt: Option<Waker> = match shared.waker.lock() {
                Ok(mut g) => g.take(),
                Err(p) => {
                    let mut g = p.into_inner();
                    g.take()
                }
            };
            match wopt {
                Some(w) => {
                    w.wake();
                }
                None => {}
            }
            break;
        } else {
            let remaining = deadline.saturating_duration_since(now);
            std::thread::park_timeout(remaining);
        }
    }
}

impl Future for TimerFut {
    type Output = ();
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        let dl = match this.deadline {
            Some(t) => t,
            None => {
                return Poll::Pending;
            }
        };
        let now = std::time::Instant::now();
        if now >= dl {
            return Poll::Ready(());
        }
        match this.shared.waker.lock() {
            Ok(mut g) => {
                *g = Some(cx.waker().clone());
            }
            Err(p) => {
                let mut g = p.into_inner();
                *g = Some(cx.waker().clone());
            }
        }
        let now2 = std::time::Instant::now();
        if now2 >= dl {
            return Poll::Ready(());
        }
        if this.spawned == false {
            let sc = Arc::clone(&this.shared);
            let spawn_res = std::thread::Builder::new()
                .name(String::from("solve-deadline"))
                .spawn(move || {
                    timer_thread_main(sc, dl);
                });
            match spawn_res {
                Ok(h) => {
                    std::mem::drop(h);
                    this.spawned = true;
                }
                Err(_) => {}
            }
        }
        Poll::Pending
    }
}

impl Drop for TimerFut {
    fn drop(&mut self) {
        self.shared.done.store(true, Ordering::SeqCst);
        let hopt: Option<std::thread::Thread> = match self.shared.thread_handle.lock() {
            Ok(g) => (*g).clone(),
            Err(p) => {
                let g = p.into_inner();
                (*g).clone()
            }
        };
        match hopt {
            Some(h) => {
                h.unpark();
            }
            None => {}
        }
        match self.shared.waker.lock() {
            Ok(mut g) => {
                *g = None;
            }
            Err(p) => {
                let mut g = p.into_inner();
                *g = None;
            }
        }
    }
}

impl Future for AggFuture {
    type Output = Result<u64, SolveError>;
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        loop {
            if this.pending.is_empty() {
                if this.in_flight.is_empty() {
                    return Poll::Ready(Ok(this.sum));
                }
            }
            let timer_is_ready = match Pin::new(&mut this.timer).poll(cx) {
                Poll::Ready(()) => true,
                Poll::Pending => false,
            };
            if timer_is_ready {
                this.in_flight.clear();
                this.pending.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }
            while this.in_flight.len() < 4 {
                let next_id_opt = this.pending.pop_front();
                let next_id = match next_id_opt {
                    Some(v) => v,
                    None => break,
                };
                let expired = match this.timer.deadline {
                    Some(dl) => {
                        let now = std::time::Instant::now();
                        if now >= dl {
                            true
                        } else {
                            false
                        }
                    }
                    None => false,
                };
                if expired {
                    this.in_flight.clear();
                    this.pending.clear();
                    return Poll::Ready(Err(SolveError::Deadline));
                }
                let fc = this.fetcher.clone();
                let fut: FetchBoxFut = Box::pin(async move {
                    let r = fc.fetch(next_id).await;
                    (next_id, r)
                });
                this.in_flight.push(Slot { fut });
            }
            if this.in_flight.is_empty() {
                return Poll::Ready(Ok(this.sum));
            }
            let mut fail_opt: Option<u32> = None;
            let mut idx: usize = 0;
            let mut progressed: bool = false;
            while idx < this.in_flight.len() {
                let pr = this.in_flight[idx].fut.as_mut().poll(cx);
                match pr {
                    Poll::Ready((fid, res)) => match res {
                        Ok(v) => {
                            this.in_flight.swap_remove(idx);
                            this.sum = this.sum.wrapping_add(v);
                            progressed = true;
                        }
                        Err(_) => {
                            fail_opt = Some(fid);
                            break;
                        }
                    },
                    Poll::Pending => {
                        idx += 1;
                    }
                }
            }
            match fail_opt {
                Some(fid) => {
                    this.in_flight.clear();
                    this.pending.clear();
                    return Poll::Ready(Err(SolveError::Fetch { id: fid }));
                }
                None => {}
            }
            if progressed {
                continue;
            }
            return Poll::Pending;
        }
    }
}

impl Drop for AggFuture {
    fn drop(&mut self) {
        self.in_flight.clear();
        self.pending.clear();
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let start = std::time::Instant::now();
    let deadline_opt: Option<std::time::Instant> = match start.checked_add(deadline) {
        Some(t) => Some(t),
        None => None,
    };
    let mut pending: VecDeque<u32> = VecDeque::new();
    for id in ids {
        pending.push_back(id);
    }
    let shared = Arc::new(TimerShared {
        done: AtomicBool::new(false),
        waker: Mutex::new(None),
        thread_handle: Mutex::new(None),
    });
    let timer = TimerFut {
        deadline: deadline_opt,
        shared,
        spawned: false,
    };
    let agg = AggFuture {
        pending,
        in_flight: Vec::new(),
        sum: 0,
        fetcher: fetch,
        timer,
    };
    let out = agg.await;
    out
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let dl = std::time::Instant::now() + deadline;
    let mut next = 0usize;
    let mut in_flight = Vec::new();
    let mut sum = 0u64;
    let mut done = 0usize;
    let mut timer_spawned = false;
    std::future::poll_fn(move |cx| {
        if std::time::Instant::now() >= dl {
            return std::task::Poll::Ready(Err(SolveError::Deadline));
        }
        loop {
            if std::time::Instant::now() >= dl {
                return std::task::Poll::Ready(Err(SolveError::Deadline));
            }
            while in_flight.len() < 4 && next < ids.len() {
                let id = ids[next];
                next += 1;
                let f = fetch.clone();
                in_flight.push(std::boxed::Box::pin(async move {
                    let r = f.fetch(id).await;
                    (id, r)
                }));
            }
            let mut idx = 0usize;
            let mut progressed = false;
            while idx < in_flight.len() {
                match std::future::Future::poll(in_flight[idx].as_mut(), cx) {
                    std::task::Poll::Ready((id, res)) => {
                        in_flight.swap_remove(idx);
                        match res {
                            Ok(v) => {
                                sum = sum.wrapping_add(v);
                                done += 1;
                                progressed = true;
                            }
                            Err(_) => {
                                return std::task::Poll::Ready(Err(
                                    SolveError::Fetch { id },
                                ));
                            }
                        }
                    }
                    std::task::Poll::Pending => {
                        idx += 1;
                    }
                }
            }
            if done == ids.len() {
                return std::task::Poll::Ready(Ok(sum));
            }
            if progressed {
                continue;
            }
            if !timer_spawned {
                timer_spawned = true;
                let w = cx.waker().clone();
                let rem =
                    dl.saturating_duration_since(std::time::Instant::now());
                std::thread::spawn(move || {
                    std::thread::sleep(rem);
                    w.wake();
                });
            }
            return std::task::Poll::Pending;
        }
    })
    .await
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let deadline_instant = std::time::Instant::now() + deadline;
    let deadline_for_thread = deadline_instant.clone();
    let waker_slot: std::sync::Arc<std::sync::Mutex<Option<std::task::Waker>>> =
        std::sync::Arc::new(std::sync::Mutex::new(None));
    let waker_slot_thread = waker_slot.clone();
    let done_flag = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let done_flag_thread = done_flag.clone();
    let _ = std::thread::spawn(move || {
        let now = std::time::Instant::now();
        if deadline_for_thread > now {
            std::thread::sleep(deadline_for_thread.duration_since(now));
        }
        if done_flag_thread.load(std::sync::atomic::Ordering::SeqCst) {
            return;
        }
        let waker_opt = match waker_slot_thread.lock() {
            Ok(mut g) => g.take(),
            Err(_) => None,
        };
        if let Some(w) = waker_opt {
            w.wake();
        }
    });
    let mut next_idx: usize = 0;
    let total = ids.len();
    let mut sum: u64 = 0;
    let mut in_flight: Vec<(
        u32,
        std::pin::Pin<
            Box<dyn std::future::Future<Output = Result<u64, ai_task_support::FetchError>> + Send>,
        >,
    )> = Vec::new();
    let res: Result<u64, SolveError> = std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
        loop {
            if std::time::Instant::now() >= deadline_instant {
                return std::task::Poll::Ready(Err(SolveError::Deadline));
            }
            while in_flight.len() < 4 && next_idx < total {
                if std::time::Instant::now() >= deadline_instant {
                    return std::task::Poll::Ready(Err(SolveError::Deadline));
                }
                let id = ids[next_idx];
                next_idx += 1;
                let fc = fetch.clone();
                let fut: std::pin::Pin<
                    Box<dyn std::future::Future<Output = Result<u64, ai_task_support::FetchError>> + Send>,
                > = Box::pin(async move { fc.fetch(id).await });
                in_flight.push((id, fut));
            }
            if in_flight.is_empty() {
                if next_idx >= total {
                    return std::task::Poll::Ready(Ok(sum));
                } else {
                    continue;
                }
            }
            let mut err_id: Option<u32> = None;
            let mut made_progress = false;
            let mut i: usize = 0;
            while i < in_flight.len() {
                let poll_res = {
                    let (_fid, f) = &mut in_flight[i];
                    std::future::Future::poll(f.as_mut(), &mut *cx)
                };
                match poll_res {
                    std::task::Poll::Ready(Ok(v)) => {
                        sum = sum.wrapping_add(v);
                        in_flight.swap_remove(i);
                        made_progress = true;
                    }
                    std::task::Poll::Ready(Err(_)) => {
                        err_id = Some(in_flight[i].0);
                        break;
                    }
                    std::task::Poll::Pending => {
                        i += 1;
                    }
                }
            }
            if let Some(failed_id) = err_id {
                return std::task::Poll::Ready(Err(SolveError::Fetch { id: failed_id }));
            }
            if in_flight.is_empty() && next_idx >= total {
                return std::task::Poll::Ready(Ok(sum));
            }
            if made_progress {
                continue;
            }
            match waker_slot.lock() {
                Ok(mut g) => {
                    *g = Some(cx.waker().clone());
                }
                Err(_) => {}
            }
            if std::time::Instant::now() >= deadline_instant {
                return std::task::Poll::Ready(Err(SolveError::Deadline));
            }
            return std::task::Poll::Pending;
        }
    })
    .await;
    done_flag.store(true, std::sync::atomic::Ordering::SeqCst);
    res
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

struct TimerGuard {
    thread: Option<std::thread::Thread>,
}

impl Drop for TimerGuard {
    fn drop(&mut self) {
        if let Some(t) = self.thread.take() {
            t.unpark();
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    use std::future::Future as _;
    if ids.is_empty() {
        return Ok(0);
    }
    let deadline_instant = std::time::Instant::now() + deadline;
    let mut pending: std::collections::VecDeque<u32> = ids.into_iter().collect();
    let mut active = Vec::new();
    let mut sum: u64 = 0;
    let mut timer_guard = TimerGuard { thread: None };
    loop {
        if std::time::Instant::now() >= deadline_instant {
            return Err(SolveError::Deadline);
        }
        while active.len() < 4 && !pending.is_empty() {
            let id = pending.pop_front().unwrap();
            let f = fetch.clone();
            active.push(Box::pin(async move {
                let r = f.fetch(id).await;
                (id, r)
            }));
        }
        if active.is_empty() {
            return Ok(sum);
        }
        let res = std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
            if std::time::Instant::now() >= deadline_instant {
                return std::task::Poll::Ready(None);
            }
            let len = active.len();
            for idx in 0..len {
                match active[idx].as_mut().poll(cx) {
                    std::task::Poll::Ready(v) => {
                        active.swap_remove(idx);
                        return std::task::Poll::Ready(Some(v));
                    }
                    std::task::Poll::Pending => {}
                }
            }
            if timer_guard.thread.is_none() {
                let w = cx.waker().clone();
                let dl = deadline_instant;
                let h = std::thread::spawn(move || {
                    let now = std::time::Instant::now();
                    if dl > now {
                        std::thread::park_timeout(dl - now);
                    }
                    if std::time::Instant::now() >= dl {
                        w.wake();
                    }
                });
                timer_guard.thread = Some(h.thread().clone());
            }
            std::task::Poll::Pending
        })
        .await;
        match res {
            None => return Err(SolveError::Deadline),
            Some((id, r)) => match r {
                Ok(v) => {
                    sum = sum.wrapping_add(v);
                }
                Err(_) => {
                    return Err(SolveError::Fetch { id });
                }
            },
        }
    }
}

