pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let start = Instant::now();
    let end = start
        .checked_add(deadline)
        .unwrap_or(start + Duration::from_secs(60 * 60 * 24 * 365 * 10));
    let mut cmd = Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::null());
    #[cfg(unix)]
    unsafe {
        cmd.pre_exec(|| unsafe {
            if setsid() == -1 {
                Err(std::io::Error::last_os_error())
            } else {
                Ok(())
            }
        });
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    #[cfg(unix)]
    let pgid: i32 = child.id() as i32;
    #[cfg(not(unix))]
    let pgid: i32 = child.id() as i32;
    let stdout = match child.stdout.take() {
        Some(s) => s,
        None => {
            let _ = child.wait();
            return Ok(CaptureResult::new(Vec::new(), 0, false));
        }
    };
    let (tx, rx) = sync_channel::<Vec<u8>>(32);
    let handle = std::thread::spawn(move || {
        let mut out = stdout;
        let mut buf = [0u8; 8192];
        loop {
            match out.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    let chunk = buf[..n].to_vec();
                    if tx.send(chunk).is_err() {
                        break;
                    }
                }
                Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                Err(_) => break,
            }
        }
    });
    let mut guard = Guard {
        pgid,
        child: Some(child),
        rx: Some(rx),
        handle: Some(handle),
    };
    let mut head: Vec<u8> = Vec::new();
    let mut total: u64 = 0;
    loop {
        loop {
            let r = match guard.rx.as_ref() {
                Some(v) => v.try_recv(),
                None => break,
            };
            match r {
                Ok(chunk) => {
                    total = total.wrapping_add(chunk.len() as u64);
                    if head.len() < head_limit {
                        let rem = head_limit - head.len();
                        let take = std::cmp::min(rem, chunk.len());
                        head.extend_from_slice(&chunk[..take]);
                    }
                }
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => break,
            }
        }
        let exited = match guard.child.as_mut() {
            Some(c) => match c.try_wait() {
                Ok(Some(_)) => true,
                Ok(None) => false,
                Err(_) => true,
            },
            None => true,
        };
        if exited {
            #[cfg(unix)]
            unsafe {
                let _ = kill(-pgid, 9);
            }
            #[cfg(not(unix))]
            {
                if let Some(c) = guard.child.as_mut() {
                    let _ = c.kill();
                }
            }
            if let Some(mut c) = guard.child.take() {
                let _ = c.wait();
            }
            let mut empty_retries: u32 = 0;
            loop {
                match guard.rx.as_ref().unwrap().try_recv() {
                    Ok(chunk) => {
                        empty_retries = 0;
                        total = total.wrapping_add(chunk.len() as u64);
                        if head.len() < head_limit {
                            let rem = head_limit - head.len();
                            let take = std::cmp::min(rem, chunk.len());
                            head.extend_from_slice(&chunk[..take]);
                        }
                    }
                    Err(TryRecvError::Empty) => {
                        empty_retries += 1;
                        if empty_retries > 200 {
                            break;
                        }
                        sleep_async(Duration::from_millis(5)).await;
                    }
                    Err(TryRecvError::Disconnected) => break,
                }
            }
            drop(guard.rx.take());
            for _ in 0..100 {
                let done = match guard.handle.as_ref() {
                    Some(h) => h.is_finished(),
                    None => true,
                };
                if done {
                    break;
                }
                sleep_async(Duration::from_millis(5)).await;
            }
            if let Some(h) = guard.handle.take() {
                if h.is_finished() {
                    let _ = h.join();
                }
            }
            let truncated = total > head_limit as u64;
            return Ok(CaptureResult::new(head, total, truncated));
        }
        if Instant::now() >= end {
            #[cfg(unix)]
            unsafe {
                let _ = kill(-pgid, 9);
            }
            #[cfg(not(unix))]
            {
                if let Some(c) = guard.child.as_mut() {
                    let _ = c.kill();
                }
            }
            if let Some(mut c) = guard.child.take() {
                let _ = c.wait();
            }
            drop(guard.rx.take());
            #[cfg(unix)]
            {
                for _ in 0..100 {
                    let alive = unsafe { kill(-pgid, 0) == 0 };
                    if !alive {
                        break;
                    }
                    unsafe {
                        let _ = kill(-pgid, 9);
                    }
                    sleep_async(Duration::from_millis(10)).await;
                }
            }
            for _ in 0..100 {
                let done = match guard.handle.as_ref() {
                    Some(h) => h.is_finished(),
                    None => true,
                };
                if done {
                    break;
                }
                sleep_async(Duration::from_millis(5)).await;
            }
            if let Some(h) = guard.handle.take() {
                if h.is_finished() {
                    let _ = h.join();
                }
            }
            return Err(CaptureError::Deadline);
        }
        sleep_async(Duration::from_millis(5)).await;
    }
}

struct Guard {
    pgid: i32,
    child: Option<Child>,
    rx: Option<Receiver<Vec<u8>>>,
    handle: Option<std::thread::JoinHandle<()>>,
}

impl Drop for Guard {
    fn drop(&mut self) {
        #[cfg(unix)]
        unsafe {
            let _ = kill(-self.pgid, 9);
        }
        #[cfg(not(unix))]
        {
            if let Some(c) = self.child.as_mut() {
                let _ = c.kill();
            }
        }
        if let Some(mut c) = self.child.take() {
            let _ = c.wait();
        }
        drop(self.rx.take());
        for _ in 0..50 {
            #[cfg(unix)]
            let group_dead = unsafe { kill(-self.pgid, 0) != 0 };
            #[cfg(not(unix))]
            let group_dead = true;
            let thread_done = match self.handle.as_ref() {
                Some(h) => h.is_finished(),
                None => true,
            };
            if group_dead && thread_done {
                break;
            }
            #[cfg(unix)]
            if !group_dead {
                unsafe {
                    let _ = kill(-self.pgid, 9);
                }
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        if let Some(h) = self.handle.take() {
            if h.is_finished() {
                let _ = h.join();
            }
        }
    }
}

struct SleepFuture {
    deadline: Instant,
    spawned: bool,
}

impl Future for SleepFuture {
    type Output = ();
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let me = self.get_mut();
        if Instant::now() >= me.deadline {
            return Poll::Ready(());
        }
        if !me.spawned {
            me.spawned = true;
            let w = cx.waker().clone();
            let dl = me.deadline;
            std::thread::spawn(move || {
                let now = Instant::now();
                if dl > now {
                    std::thread::sleep(dl - now);
                }
                w.wake();
            });
        }
        Poll::Pending
    }
}

fn sleep_async(d: Duration) -> SleepFuture {
    SleepFuture {
        deadline: Instant::now()
            .checked_add(d)
            .unwrap_or(Instant::now() + Duration::from_secs(3600)),
        spawned: false,
    }
}

