struct Shared {
    cancel: std::sync::atomic::AtomicBool,
    waker: std::sync::Mutex<Option<std::task::Waker>>,
    pgid: std::sync::atomic::AtomicI64,
    root: std::sync::atomic::AtomicU32,
}

struct Accum {
    head: Vec<u8>,
    total: u64,
}

struct Guard {
    handle: Option<std::thread::JoinHandle<()>>,
    shared: std::sync::Arc<Shared>,
    finished: bool,
}

impl Drop for Guard {
    fn drop(&mut self) {
        if self.finished {
            match self.handle.take() {
                Some(h) => {
                    let _ = h.join();
                }
                None => {}
            }
            return;
        }
        self.shared
            .cancel
            .store(true, std::sync::atomic::Ordering::SeqCst);
        let pg = self
            .shared
            .pgid
            .load(std::sync::atomic::Ordering::SeqCst);
        let rp = self
            .shared
            .root
            .load(std::sync::atomic::Ordering::SeqCst);
        if rp != 0 && pg >= 0 {
            let pgi: i32 = if pg > i32::MAX as i64 {
                -1
            } else {
                pg as i32
            };
            if pgi >= 0 {
                kill_tree(rp, pgi);
            }
        }
        match self.handle.take() {
            Some(h) => {
                let _ = h.join();
            }
            None => {}
        }
    }
}

fn store_waker(shared: &std::sync::Arc<Shared>, w: std::task::Waker) {
    match shared.waker.lock() {
        Ok(mut g) => {
            *g = Some(w);
        }
        Err(e) => {
            let mut g = e.into_inner();
            *g = Some(w);
        }
    }
}

fn take_and_wake(shared: &std::sync::Arc<Shared>) {
    let opt: Option<std::task::Waker> = match shared.waker.lock() {
        Ok(mut g) => g.take(),
        Err(e) => {
            let mut g = e.into_inner();
            g.take()
        }
    };
    match opt {
        Some(w) => {
            w.wake();
        }
        None => {}
    }
}

fn run_kill_binary(path: &str, target: &str) {
    let mut cmd = std::process::Command::new(path);
    cmd.arg("-KILL");
    cmd.arg(target);
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::null());
    cmd.stderr(std::process::Stdio::null());
    let _ = cmd.status();
}

fn kill_single(pid: u32) {
    let s = format!("{}", pid);
    let sref: &str = s.as_str();
    run_kill_binary("/bin/kill", sref);
    run_kill_binary("/usr/bin/kill", sref);
}

fn kill_group(pgid: i32) {
    if pgid < 0 {
        return;
    }
    let s = format!("-{}", pgid);
    let sref: &str = s.as_str();
    run_kill_binary("/bin/kill", sref);
    run_kill_binary("/usr/bin/kill", sref);
}

fn descendants_via_ps(root: u32) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let mut cmd = std::process::Command::new("ps");
    cmd.arg("-ax");
    cmd.arg("-o");
    cmd.arg("pid=,ppid=,pgid=");
    cmd.stdin(std::process::Stdio::null());
    cmd.stderr(std::process::Stdio::null());
    let res = cmd.output();
    let output = match res {
        Ok(o) => o,
        Err(_) => {
            return out;
        }
    };
    if !output.status.success() {
        return out;
    }
    let text: String = match String::from_utf8(output.stdout) {
        Ok(s) => s,
        Err(_) => {
            return out;
        }
    };
    let mut pairs: Vec<(u32, u32)> = Vec::new();
    for line in text.lines() {
        let mut it = line.split_whitespace();
        let a = match it.next() {
            Some(v) => v,
            None => continue,
        };
        let b = match it.next() {
            Some(v) => v,
            None => continue,
        };
        let pid: u32 = match a.parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let ppid: u32 = match b.parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        pairs.push((pid, ppid));
    }
    let mut seen: std::collections::HashSet<u32> = std::collections::HashSet::new();
    seen.insert(root);
    let mut stack: Vec<u32> = Vec::new();
    stack.push(root);
    let mut idx: usize = 0;
    while idx < stack.len() {
        let cur: u32 = match stack.get(idx) {
            Some(v) => *v,
            None => break,
        };
        idx = idx.saturating_add(1);
        for pr in pairs.iter() {
            let (pid, ppid) = *pr;
            if ppid == cur && !seen.contains(&pid) {
                seen.insert(pid);
                stack.push(pid);
                out.push(pid);
            }
        }
        if stack.len() > 65536 {
            break;
        }
    }
    out
}

fn descendants_via_proc(root: u32) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    let rd = match std::fs::read_dir("/proc") {
        Ok(v) => v,
        Err(_) => {
            return out;
        }
    };
    let mut pairs: Vec<(u32, u32)> = Vec::new();
    for ent in rd {
        let ent = match ent {
            Ok(v) => v,
            Err(_) => continue,
        };
        let name = ent.file_name();
        let ns: String = match name.into_string() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let pid: u32 = match ns.parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let p = format!("/proc/{}/stat", pid);
        let content: String = match std::fs::read_to_string(p.as_str()) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let rp: usize = match content.rfind(')') {
            Some(v) => v,
            None => continue,
        };
        let after: &str = match content.get(rp.saturating_add(1)..) {
            Some(v) => v,
            None => continue,
        };
        let mut it = after.split_whitespace();
        let _ = it.next();
        let ppid_s = match it.next() {
            Some(v) => v,
            None => continue,
        };
        let ppid: u32 = match ppid_s.parse::<i64>() {
            Ok(v) => {
                if v < 0 {
                    continue;
                } else {
                    v as u32
                }
            }
            Err(_) => continue,
        };
        pairs.push((pid, ppid));
    }
    let mut seen: std::collections::HashSet<u32> = std::collections::HashSet::new();
    seen.insert(root);
    let mut stack: Vec<u32> = Vec::new();
    stack.push(root);
    let mut idx: usize = 0;
    while idx < stack.len() {
        let cur: u32 = match stack.get(idx) {
            Some(v) => *v,
            None => break,
        };
        idx = idx.saturating_add(1);
        for pr in pairs.iter() {
            let (pid, ppid) = *pr;
            if ppid == cur && !seen.contains(&pid) {
                seen.insert(pid);
                stack.push(pid);
                out.push(pid);
            }
        }
        if stack.len() > 65536 {
            break;
        }
    }
    out
}

fn all_descendants(root: u32) -> Vec<u32> {
    let mut acc: Vec<u32> = Vec::new();
    let mut seen: std::collections::HashSet<u32> = std::collections::HashSet::new();
    let a = descendants_via_ps(root);
    for pid in a.iter() {
        if !seen.contains(pid) {
            seen.insert(*pid);
            acc.push(*pid);
        }
    }
    let b = descendants_via_proc(root);
    for pid in b.iter() {
        if !seen.contains(pid) {
            seen.insert(*pid);
            acc.push(*pid);
        }
    }
    acc
}

fn kill_tree(root: u32, pgid: i32) {
    kill_group(pgid);
    kill_single(root);
    let mut round: u32 = 0;
    while round < 4 {
        let ds = all_descendants(root);
        if ds.is_empty() {
            break;
        }
        for pid in ds.iter() {
            kill_single(*pid);
        }
        kill_group(pgid);
        std::thread::sleep(std::time::Duration::from_millis(10));
        round = round.saturating_add(1);
    }
    kill_group(pgid);
    let ds2 = all_descendants(root);
    for pid in ds2.iter() {
        kill_single(*pid);
    }
}

fn send_outcome(
    tx: &std::sync::mpsc::Sender<Result<CaptureResult, CaptureError>>,
    shared: &std::sync::Arc<Shared>,
    v: Result<CaptureResult, CaptureError>,
) {
    let _ = tx.send(v);
    take_and_wake(shared);
}

fn reader_main(
    mut stdout: std::process::ChildStdout,
    head_limit: usize,
    tx_acc: std::sync::mpsc::Sender<Accum>,
) {
    use std::io::Read as _Read;
    let mut head: Vec<u8> = Vec::new();
    let mut total: u64 = 0;
    let mut buf: [u8; 8192] = [0; 8192];
    loop {
        let nres = stdout.read(&mut buf);
        let n: usize = match nres {
            Ok(v) => v,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                } else {
                    break;
                }
            }
        };
        if n == 0 {
            break;
        }
        total = total.saturating_add(n as u64);
        if head.len() < head_limit {
            let room: usize = head_limit.saturating_sub(head.len());
            let take: usize = if n < room { n } else { room };
            let mut i: usize = 0;
            while i < take {
                let b: u8 = match buf.get(i) {
                    Some(v) => *v,
                    None => break,
                };
                head.push(b);
                i = i.saturating_add(1);
            }
        }
    }
    let a = Accum { head, total };
    let _ = tx_acc.send(a);
}

fn worker_main(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
    shared: std::sync::Arc<Shared>,
    tx: std::sync::mpsc::Sender<Result<CaptureResult, CaptureError>>,
) {
    if shared
        .cancel
        .load(std::sync::atomic::Ordering::SeqCst)
    {
        send_outcome(&tx, &shared, Err(CaptureError::Cancelled));
        return;
    }
    let prog: String = match argv.get(0) {
        Some(v) => v.clone(),
        None => {
            send_outcome(
                &tx,
                &shared,
                Err(CaptureError::Spawn("empty argv".to_string())),
            );
            return;
        }
    };
    let mut cmd = std::process::Command::new(prog.as_str());
    let mut idx: usize = 1;
    while idx < argv.len() {
        let a: &String = match argv.get(idx) {
            Some(v) => v,
            None => break,
        };
        cmd.arg(a.as_str());
        idx = idx.saturating_add(1);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt as _Ext;
        cmd.process_group(0);
    }
    let mut child: std::process::Child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => {
            let msg = format!("failed to spawn '{}': {}", prog, e);
            send_outcome(&tx, &shared, Err(CaptureError::Spawn(msg)));
            return;
        }
    };
    let root_pid: u32 = child.id();
    shared
        .root
        .store(root_pid, std::sync::atomic::Ordering::SeqCst);
    let pgid_i: i64 = root_pid as i64;
    shared
        .pgid
        .store(pgid_i, std::sync::atomic::Ordering::SeqCst);
    let pgid: i32 = if pgid_i > i32::MAX as i64 {
        -1
    } else if pgid_i < 0 {
        -1
    } else {
        pgid_i as i32
    };
    let stdout_taken: Option<std::process::ChildStdout> = child.stdout.take();
    let stdout_handle: std::process::ChildStdout = match stdout_taken {
        Some(v) => v,
        None => {
            if pgid >= 0 {
                kill_tree(root_pid, pgid);
            } else {
                let _ = child.kill();
            }
            let _ = child.wait();
            shared
                .pgid
                .store(-1, std::sync::atomic::Ordering::SeqCst);
            send_outcome(&tx, &shared, Err(CaptureError::Cancelled));
            return;
        }
    };
    let (tx_acc, rx_acc) = std::sync::mpsc::channel::<Accum>();
    let reader_handle_res = std::thread::Builder::new()
        .name("capture-reader".to_string())
        .spawn(move || {
            reader_main(stdout_handle, head_limit, tx_acc);
        });
    let reader_handle: std::thread::JoinHandle<()> = match reader_handle_res {
        Ok(h) => h,
        Err(_) => {
            if pgid >= 0 {
                kill_tree(root_pid, pgid);
            } else {
                let _ = child.kill();
            }
            let _ = child.wait();
            shared
                .pgid
                .store(-1, std::sync::atomic::Ordering::SeqCst);
            send_outcome(&tx, &shared, Err(CaptureError::Cancelled));
            return;
        }
    };
    let mut reader_opt: Option<std::thread::JoinHandle<()>> = Some(reader_handle);
    let join_reader = |opt: &mut Option<std::thread::JoinHandle<()>>| {
        match opt.take() {
            Some(h) => {
                let _ = h.join();
            }
            None => {}
        }
    };
    let start = std::time::Instant::now();
    loop {
        if shared
            .cancel
            .load(std::sync::atomic::Ordering::SeqCst)
        {
            if pgid >= 0 {
                kill_tree(root_pid, pgid);
            } else {
                let _ = child.kill();
            }
            let _ = child.wait();
            let _ = rx_acc.recv();
            join_reader(&mut reader_opt);
            shared
                .pgid
                .store(-1, std::sync::atomic::Ordering::SeqCst);
            send_outcome(&tx, &shared, Err(CaptureError::Cancelled));
            return;
        }
        let waited: Option<std::process::ExitStatus> = match child.try_wait() {
            Ok(v) => v,
            Err(_) => {
                if pgid >= 0 {
                    kill_tree(root_pid, pgid);
                } else {
                    let _ = child.kill();
                }
                let _ = child.wait();
                let _ = rx_acc.recv();
                join_reader(&mut reader_opt);
                shared
                    .pgid
                    .store(-1, std::sync::atomic::Ordering::SeqCst);
                send_outcome(&tx, &shared, Err(CaptureError::Cancelled));
                return;
            }
        };
        match waited {
            Some(_) => {
                let elapsed = start.elapsed();
                if elapsed >= deadline {
                    if pgid >= 0 {
                        kill_tree(root_pid, pgid);
                    } else {
                        let _ = child.kill();
                    }
                    let _ = child.wait();
                    let _ = rx_acc.recv();
                    join_reader(&mut reader_opt);
                    shared
                        .pgid
                        .store(-1, std::sync::atomic::Ordering::SeqCst);
                    send_outcome(&tx, &shared, Err(CaptureError::Deadline));
                    return;
                } else {
                    let remaining: std::time::Duration =
                        deadline.saturating_sub(elapsed);
                    match rx_acc.recv_timeout(remaining) {
                        Ok(a) => {
                            join_reader(&mut reader_opt);
                            let lim: u64 = head_limit as u64;
                            let trunc: bool = a.total > lim;
                            let res = CaptureResult::new(a.head, a.total, trunc);
                            shared.pgid.store(
                                -1,
                                std::sync::atomic::Ordering::SeqCst,
                            );
                            send_outcome(&tx, &shared, Ok(res));
                            return;
                        }
                        Err(e) => match e {
                            std::sync::mpsc::RecvTimeoutError::Timeout => {
                                if pgid >= 0 {
                                    kill_tree(root_pid, pgid);
                                } else {
                                    let _ = child.kill();
                                }
                                let _ = child.wait();
                                let _ = rx_acc.recv();
                                join_reader(&mut reader_opt);
                                shared.pgid.store(
                                    -1,
                                    std::sync::atomic::Ordering::SeqCst,
                                );
                                send_outcome(
                                    &tx,
                                    &shared,
                                    Err(CaptureError::Deadline),
                                );
                                return;
                            }
                            std::sync::mpsc::RecvTimeoutError::Disconnected => {
                                join_reader(&mut reader_opt);
                                shared.pgid.store(
                                    -1,
                                    std::sync::atomic::Ordering::SeqCst,
                                );
                                send_outcome(
                                    &tx,
                                    &shared,
                                    Err(CaptureError::Cancelled),
                                );
                                return;
                            }
                        },
                    }
                }
            }
            None => {}
        }
        if start.elapsed() >= deadline {
            if pgid >= 0 {
                kill_tree(root_pid, pgid);
            } else {
                let _ = child.kill();
            }
            let _ = child.wait();
            let _ = rx_acc.recv();
            join_reader(&mut reader_opt);
            shared
                .pgid
                .store(-1, std::sync::atomic::Ordering::SeqCst);
            send_outcome(&tx, &shared, Err(CaptureError::Deadline));
            return;
        }
        std::thread::sleep(std::time::Duration::from_millis(5));
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let shared = std::sync::Arc::new(Shared {
        cancel: std::sync::atomic::AtomicBool::new(false),
        waker: std::sync::Mutex::new(None),
        pgid: std::sync::atomic::AtomicI64::new(-1),
        root: std::sync::atomic::AtomicU32::new(0),
    });
    let (tx, rx) = std::sync::mpsc::channel::<Result<CaptureResult, CaptureError>>();
    let argv_c = argv;
    let shared_c = shared.clone();
    let spawn_res = std::thread::Builder::new()
        .name("capture-worker".to_string())
        .spawn(move || {
            worker_main(argv_c, head_limit, deadline, shared_c, tx);
        });
    let worker_handle: std::thread::JoinHandle<()> = match spawn_res {
        Ok(h) => h,
        Err(e) => {
            let msg = format!("failed to spawn worker thread: {}", e);
            return Err(CaptureError::Spawn(msg));
        }
    };
    let mut guard = Guard {
        handle: Some(worker_handle),
        shared: shared.clone(),
        finished: false,
    };
    let outcome: Result<CaptureResult, CaptureError> =
        std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
            match rx.try_recv() {
                Ok(v) => std::task::Poll::Ready(v),
                Err(e) => match e {
                    std::sync::mpsc::TryRecvError::Disconnected => {
                        std::task::Poll::Ready(Err(CaptureError::Cancelled))
                    }
                    std::sync::mpsc::TryRecvError::Empty => {
                        let w: std::task::Waker = cx.waker().clone();
                        store_waker(&shared, w);
                        match rx.try_recv() {
                            Ok(v2) => std::task::Poll::Ready(v2),
                            Err(e2) => match e2 {
                                std::sync::mpsc::TryRecvError::Disconnected => {
                                    std::task::Poll::Ready(Err(
                                        CaptureError::Cancelled,
                                    ))
                                }
                                std::sync::mpsc::TryRecvError::Empty => {
                                    std::task::Poll::Pending
                                }
                            },
                        }
                    }
                },
            }
        })
        .await;
    guard.finished = true;
    match guard.handle.take() {
        Some(h) => {
            let _ = h.join();
        }
        None => {}
    }
    outcome
}

