struct Guard {
    child: Option<std::process::Child>,
    pgid: i32,
}

impl Drop for Guard {
    fn drop(&mut self) {
        if let Some(mut child) = self.child.take() {
            unsafe {
                kill(-self.pgid, 9);
            }
            let _ = child.wait();
            for _ in 0..200 {
                let alive = unsafe { kill(-self.pgid, 0) } == 0;
                if !alive {
                    break;
                }
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
        }
    }
}

async fn yield_once() {
    let mut first = true;
    std::future::poll_fn(|cx| {
        if first {
            first = false;
            cx.waker().wake_by_ref();
            std::task::Poll::Pending
        } else {
            std::task::Poll::Ready(())
        }
    })
    .await
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    {
        use std::os::unix::process::CommandExt;
        unsafe {
            cmd.pre_exec(|| {
                unsafe {
                    setsid();
                }
                Ok(())
            });
        }
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let pgid = child.id() as i32;
    let stdout = child.stdout.take();
    let mut guard = Guard {
        child: Some(child),
        pgid,
    };
    let limit = head_limit;
    let (tx, rx) = std::sync::mpsc::channel::<(Vec<u8>, u64)>();
    std::thread::spawn(move || {
        let mut head: Vec<u8> = Vec::new();
        let mut total: u64 = 0;
        if let Some(mut out) = stdout {
            use std::io::Read;
            let mut buf = [0u8; 8192];
            loop {
                match out.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        total += n as u64;
                        if head.len() < limit {
                            let need = limit - head.len();
                            let take = if n < need { n } else { need };
                            head.extend_from_slice(&buf[..take]);
                        }
                    }
                    Err(_) => break,
                }
            }
        }
        let _ = tx.send((head, total));
    });
    let start = std::time::Instant::now();
    let mut reader_res: Option<(Vec<u8>, u64)> = None;
    loop {
        if reader_res.is_none() {
            match rx.try_recv() {
                Ok(v) => {
                    reader_res = Some(v);
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    reader_res = Some((Vec::new(), 0));
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
            }
        }
        let exited = match guard.child.as_mut().unwrap().try_wait() {
            Ok(Some(_)) => true,
            Ok(None) => false,
            Err(_) => true,
        };
        if exited && reader_res.is_some() {
            let (head, total) = reader_res.take().unwrap();
            let truncated = total > head_limit as u64;
            return Ok(CaptureResult::new(head, total, truncated));
        }
        if start.elapsed() >= deadline {
            unsafe {
                kill(-pgid, 9);
            }
            return Err(CaptureError::Deadline);
        }
        std::thread::sleep(std::time::Duration::from_millis(1));
        yield_once().await;
    }
}

