async fn nap(dur: std::time::Duration) {
    let st = std::time::Instant::now();
    std::future::poll_fn(move |cx: &mut std::task::Context<'_>| {
        if st.elapsed() >= dur {
            std::task::Poll::Ready(())
        } else {
            let w = cx.waker().clone();
            let rem = dur.saturating_sub(st.elapsed());
            std::thread::spawn(move || {
                std::thread::sleep(rem);
                w.wake();
            });
            std::task::Poll::Pending
        }
    })
    .await
}

fn worker_main(
    mut child: std::process::Child,
    mut out: std::process::ChildStdout,
    head_limit: usize,
    shared: std::sync::Arc<Shared>,
) {
    use std::io::Read as _;
    let mut head: Vec<u8> = Vec::new();
    let mut total: u64 = 0;
    let mut buf = [0u8; 8192];
    loop {
        match out.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                total += n as u64;
                if head.len() < head_limit {
                    let remaining = head_limit - head.len();
                    let take = std::cmp::min(remaining, n);
                    head.extend_from_slice(&buf[..take]);
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(_) => break,
        }
    }
    let _ = child.wait();
    let truncated = total > head_limit as u64;
    let done = WorkerDone {
        head,
        total,
        truncated,
    };
    *shared.result.lock().unwrap() = Some(done);
    if let Some(w) = shared.waker.lock().unwrap().take() {
        w.wake();
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    {
        use std::os::unix::process::CommandExt as _;
        unsafe {
            cmd.pre_exec(|| {
                let r = unsafe { setpgid(0, 0) };
                if r != 0 {
                    Err(std::io::Error::last_os_error())
                } else {
                    Ok(())
                }
            });
        }
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let pid = child.id() as i32;
    let pgid = pid;
    let out = match child.stdout.take() {
        Some(o) => o,
        None => {
            unsafe {
                kill(-pgid, 9);
            }
            let _ = child.wait();
            return Ok(CaptureResult::new(Vec::new(), 0, false));
        }
    };
    let shared = std::sync::Arc::new(Shared {
        result: std::sync::Mutex::new(None),
        waker: std::sync::Mutex::new(None),
    });
    let shared2 = shared.clone();
    let handle = std::thread::spawn(move || {
        worker_main(child, out, head_limit, shared2);
    });
    let mut guard = Guard {
        pgid,
        handle: Some(handle),
    };
    let start = std::time::Instant::now();
    let shared_c = shared.clone();
    let opt: Option<WorkerDone> = std::future::poll_fn(move |cx: &mut std::task::Context<'_>| {
        if let Some(done) = shared_c.result.lock().unwrap().take() {
            return std::task::Poll::Ready(Some(done));
        }
        if start.elapsed() >= deadline {
            return std::task::Poll::Ready(None);
        }
        *shared_c.waker.lock().unwrap() = Some(cx.waker().clone());
        if let Some(done) = shared_c.result.lock().unwrap().take() {
            return std::task::Poll::Ready(Some(done));
        }
        if start.elapsed() >= deadline {
            return std::task::Poll::Ready(None);
        }
        let w = cx.waker().clone();
        let remaining = deadline.saturating_sub(start.elapsed());
        let d = std::cmp::min(remaining, std::time::Duration::from_millis(5));
        if d.is_zero() {
            w.wake();
            return std::task::Poll::Pending;
        }
        std::thread::spawn(move || {
            std::thread::sleep(d);
            w.wake();
        });
        std::task::Poll::Pending
    })
    .await;
    match opt {
        Some(done) => {
            if let Some(h) = guard.handle.take() {
                let _ = h.join();
            }
            Ok(CaptureResult::new(done.head, done.total, done.truncated))
        }
        None => {
            unsafe {
                kill(-pgid, 9);
            }
            for _ in 0..1000 {
                let finished = guard
                    .handle
                    .as_ref()
                    .map(|h| h.is_finished())
                    .unwrap_or(true);
                if finished {
                    break;
                }
                nap(std::time::Duration::from_millis(5)).await;
            }
            if let Some(h) = guard.handle.take() {
                let _ = h.join();
            }
            Err(CaptureError::Deadline)
        }
    }
}

