async fn sleep_for(dur: std::time::Duration) {
    use std::task::Poll;
    if dur.is_zero() {
        return;
    }
    let end = std::time::Instant::now() + dur;
    std::future::poll_fn(move |cx| {
        if std::time::Instant::now() >= end {
            return Poll::Ready(());
        }
        let waker = cx.waker().clone();
        let now = std::time::Instant::now();
        let rem = if end > now {
            end - now
        } else {
            std::time::Duration::from_secs(0)
        };
        std::thread::spawn(move || {
            std::thread::sleep(rem);
            waker.wake();
        });
        Poll::Pending
    })
    .await
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let expected = format!("applied:{key}");
    let line_with_nl = format!("applied:{key}\n");
    let _ = std::fs::create_dir_all(&effect_dir);
    let already_present: bool = match std::fs::read(&log_path) {
        Ok(bytes) => {
            let s = String::from_utf8_lossy(&bytes);
            s.lines().any(|l| l == expected)
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => false,
    };
    let did_append = !already_present;
    if did_append {
        let _ = std::fs::create_dir_all(&effect_dir);
        if let Ok(mut f) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)
        {
            use std::io::Write as _;
            let _ = f.write_all(line_with_nl.as_bytes());
            let _ = f.flush();
            let _ = f.sync_all();
        }
    }
    let wait_start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            break;
        }
        if wait_start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline
            .checked_sub(wait_start.elapsed())
            .unwrap_or(std::time::Duration::from_secs(0));
        if remaining.is_zero() {
            return Err(RecoverError::Deadline);
        }
        let step = std::time::Duration::from_millis(5);
        let wait_dur = if remaining < step { remaining } else { step };
        sleep_for(wait_dur).await;
    }
    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

