                return Ok(format!("applied:{key}"));
            } else {
                return Ok(format!("recovered:{key}"));
            }
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.checked_sub(start.elapsed()).unwrap_or_default();
        let step = if remaining > std::time::Duration::from_millis(5) {
            std::time::Duration::from_millis(5)
        } else {
            remaining
        };
        sleep_for(step).await;
    }
}

async fn sleep_for(dur: std::time::Duration) {
    if dur.is_zero() {
        return;
    }
    let deadline = std::time::Instant::now() + dur;
    std::future::poll_fn(|cx| {
        if std::time::Instant::now() >= deadline {
            return std::task::Poll::Ready(());
        }
        let w = cx.waker().clone();
        let rem = deadline.saturating_duration_since(std::time::Instant::now());
        std::thread::spawn(move || {
            std::thread::sleep(rem);
            w.wake();
        });
        std::task::Poll::Pending
    })
    .await
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

async fn sleep_async(dur: std::time::Duration) {
    use std::future::poll_fn;
    use std::task::Poll;
    if dur.is_zero() {
        return;
    }
    let deadline = std::time::Instant::now() + dur;
    poll_fn(|cx| {
        if std::time::Instant::now() >= deadline {
            Poll::Ready(())
        } else {
            let waker = cx.waker().clone();
            let remaining = deadline.saturating_duration_since(std::time::Instant::now());
            std::thread::spawn(move || {
                std::thread::sleep(remaining);
                waker.wake();
            });
            Poll::Pending
        }
    })
    .await
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let target_line = format!("applied:{key}");
    let target_with_nl = format!("applied:{key}\n");

    let _ = std::fs::create_dir_all(&effect_dir);

    // Synchronous check-and-append: no await point in here, so async
    // cancellation cannot interleave between check and append.
    let mut existing: Vec<u8> = std::fs::read(&log_path).unwrap_or_default();

    // Repair a torn tail left by SIGKILL mid-append. Valid states are
    // empty or end with '\n'; anything else ends with an incomplete line.
    if !existing.is_empty() && *existing.last().unwrap() != b'\n' {
        let trunc_len = existing
            .iter()
            .rposition(|&b| b == b'\n')
            .map(|i| i + 1)
            .unwrap_or(0);
        if let Ok(f) = std::fs::OpenOptions::new().write(true).open(&log_path) {
            let _ = f.set_len(trunc_len as u64);
        }
        existing.truncate(trunc_len);
    }

    let already: bool = if existing.is_empty() {
        false
    } else {
        existing
            .split(|&b| b == b'\n')
            .any(|line| line == target_line.as_bytes())
    };

    let did_append: bool = if already {
        false
    } else {
        if let Ok(mut f) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)
        {
            use std::io::Write as _;
            let _ = f.write_all(target_with_nl.as_bytes());
            let _ = f.sync_all();
        }
        true
    };

    // Wait for `release` with bounded polling. No further append happens here.
    let start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.checked_sub(start.elapsed()).unwrap_or_default();
        let interval = std::cmp::min(remaining, std::time::Duration::from_millis(5));
        if interval.is_zero() {
            return Err(RecoverError::Deadline);
        }
        sleep_async(interval).await;
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");

    // --- Synchronous, atomic-before-first-await section ---
    // Create dir (with parents) when missing.
    if std::fs::create_dir_all(&effect_dir).is_err() {
        return Err(RecoverError::Deadline);
    }

    let needle = format!("applied:{key}");
    let already: bool = match std::fs::read_to_string(&log_path) {
        Ok(content) => content.lines().any(|l| l == needle),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => return Err(RecoverError::Deadline),
    };

    let appended: bool = if already {
        false
    } else {
        let mut opts = std::fs::OpenOptions::new();
        opts.create(true).append(true).write(true);
        let mut f = match opts.open(&log_path) {
            Ok(f) => f,
            Err(_) => return Err(RecoverError::Deadline),
        };
        {
            use std::io::Write as _;
            let line = format!("applied:{key}\n");
            if f.write_all(line.as_bytes()).is_err() {
                return Err(RecoverError::Deadline);
            }
            let _ = f.flush();
            let _ = f.sync_all();
        }
        true
    };

    // --- Async bounded wait for `release`, never appending further ---
    let start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.saturating_sub(start.elapsed());
        let mut step = std::cmp::min(
            remaining,
            std::time::Duration::from_millis(10),
        );
        if step.is_zero() {
            // Remaining was tiny but not yet timed out; avoid busy loop.
            // Next iteration will observe the timeout.
            step = std::time::Duration::from_millis(1);
        }
        async_sleep(step).await;
    }

    if appended {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

fn async_sleep(dur: std::time::Duration) -> Sleep {
    Sleep {
        dur,
        start: None,
        slot: None,
    }
}

struct Sleep {
    dur: std::time::Duration,
    start: Option<std::time::Instant>,
    slot: Option<
        std::sync::Arc<std::sync::Mutex<Option<std::task::Waker>>>,
    >,
}

impl std::future::Future for Sleep {
    type Output = ();
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<()> {
        let me = self.get_mut();
        let now = std::time::Instant::now();
        let start = *me.start.get_or_insert(now);
        if start.elapsed() >= me.dur {
            return std::task::Poll::Ready(());
        }

        let need_spawn = match &me.slot {
            None => true,
            Some(slot) => match slot.lock() {
                Ok(mut g) => {
                    if g.is_none() {
                        // Previous timer already fired but we are still
                        // pending (spurious wake); need a fresh timer.
                        true
                    } else {
                        *g = Some(cx.waker().clone());
                        false
                    }
                }
                Err(_) => true,
            },
        };

        if need_spawn {
            let remaining = me.dur.saturating_sub(start.elapsed());
            if remaining.is_zero() {
                return std::task::Poll::Ready(());
            }
            let slot: std::sync::Arc<
                std::sync::Mutex<Option<std::task::Waker>>,
            > = std::sync::Arc::new(std::sync::Mutex::new(Some(
                cx.waker().clone(),
            )));
            let slot2 = slot.clone();
            std::thread::spawn(move || {
                std::thread::sleep(remaining);
                let w = slot2
                    .lock()
                    .ok()
                    .and_then(|mut g| g.take());
                if let Some(w) = w {
                    w.wake();
                }
            });
            me.slot = Some(slot);
        }

        std::task::Poll::Pending
    }
}

use std::future::{poll_fn, Future};
use std::task::{Context, Poll};
use std::time::Instant;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

async fn fetch_both(
    stage: ai_task_support::Stage,
    deadline: Instant,
) -> Result<(ai_task_support::Artifact, ai_task_support::Artifact), PipelineError> {
    let s1 = stage.clone();
    let s2 = stage;
    let mut fut_a = Box::pin(async move {
        s1.run(ai_task_support::StageName::FetchA).await
    });
    let mut fut_b = Box::pin(async move {
        s2.run(ai_task_support::StageName::FetchB).await
    });
    let mut res_a: Option<ai_task_support::Artifact> = None;
    let mut res_b: Option<ai_task_support::Artifact> = None;
    let mut timer_started = false;
    poll_fn(move |cx: &mut Context<'_>| {
        if Instant::now() >= deadline {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if res_a.is_none() {
            match fut_a.as_mut().poll(cx) {
                Poll::Ready(Ok(v)) => {
                    res_a = Some(v);
                }
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: ai_task_support::StageName::FetchA,
                    }));
                }
                Poll::Pending => {}
            }
        }
        if res_b.is_none() {
            match fut_b.as_mut().poll(cx) {
                Poll::Ready(Ok(v)) => {
                    res_b = Some(v);
                }
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: ai_task_support::StageName::FetchB,
                    }));
                }
                Poll::Pending => {}
            }
        }
        if res_a.is_some() && res_b.is_some() {
            let a = res_a.take().unwrap();
            let b = res_b.take().unwrap();
            return Poll::Ready(Ok((a, b)));
        }
        if !timer_started {
            timer_started = true;
            let w = cx.waker().clone();
            let rem = deadline.saturating_duration_since(Instant::now());
            std::thread::spawn(move || {
                std::thread::sleep(rem);
                w.wake();
            });
        }
        Poll::Pending
    })
    .await
}

async fn run_combine(
    stage: ai_task_support::Stage,
    deadline: Instant,
) -> Result<ai_task_support::Artifact, PipelineError> {
    let mut inner = Box::pin(async move {
        stage.run(ai_task_support::StageName::Combine).await
    });
    let mut timer_started = false;
    poll_fn(move |cx: &mut Context<'_>| {
        if Instant::now() >= deadline {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match inner.as_mut().poll(cx) {
            Poll::Ready(Ok(v)) => Poll::Ready(Ok(v)),
            Poll::Ready(Err(_)) => Poll::Ready(Err(PipelineError::Stage {
                name: ai_task_support::StageName::Combine,
            })),
            Poll::Pending => {
                if !timer_started {
                    timer_started = true;
                    let w = cx.waker().clone();
                    let rem = deadline.saturating_duration_since(Instant::now());
                    std::thread::spawn(move || {
                        std::thread::sleep(rem);
                        w.wake();
                    });
                }
                Poll::Pending
            }
        }
    })
    .await
}

async fn run_publish(
    stage: ai_task_support::Stage,
    deadline: Instant,
) -> Result<ai_task_support::Artifact, PipelineError> {
    let mut inner = Box::pin(async move {
        stage.run(ai_task_support::StageName::Publish).await
    });
    let mut timer_started = false;
    poll_fn(move |cx: &mut Context<'_>| {
        if Instant::now() >= deadline {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match inner.as_mut().poll(cx) {
            Poll::Ready(Ok(v)) => Poll::Ready(Ok(v)),
            Poll::Ready(Err(_)) => Poll::Ready(Err(PipelineError::Stage {
                name: ai_task_support::StageName::Publish,
            })),
            Poll::Pending => {
                if !timer_started {
                    timer_started = true;
                    let w = cx.waker().clone();
                    let rem = deadline.saturating_duration_since(Instant::now());
                    std::thread::spawn(move || {
                        std::thread::sleep(rem);
                        w.wake();
                    });
                }
                Poll::Pending
