pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let dl = Instant::now() + deadline;
    let _ = fetch_both(stage.clone(), dl).await?;
    let c = run_combine(stage.clone(), dl).await?;
    drop(c);
    let p = run_publish(stage, dl).await?;
    Ok(ai_task_support::Published::from(p))
}

