pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let dl = std::time::Instant::now()
        .checked_add(deadline)
        .unwrap_or_else(|| std::time::Instant::now() + std::time::Duration::from_secs(3600 * 24 * 365 * 30));
    if std::time::Instant::now() >= dl {
        return Err(PipelineError::Deadline);
    }
    let sa = stage.clone();
    let sb = stage.clone();
    let sc = stage.clone();
    let sp = stage;
    pipeline_inner(sa, sb, sc, sp, dl).await
}

use std::future::Future;
use std::pin::Pin;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::task::{Context, Poll, Waker};
use std::time::Instant;

struct DeadlineGuard {
    done: Arc<AtomicBool>,
    handle: Option<std::thread::JoinHandle<()>>,
}

impl DeadlineGuard {
    fn arm(deadline: Instant, waker: Waker) -> Self {
        let done = Arc::new(AtomicBool::new(false));
        let done2 = done.clone();
        let handle = std::thread::spawn(move || loop {
            if done2.load(Ordering::SeqCst) {
                break;
            }
            let now = Instant::now();
            if now >= deadline {
                if !done2.load(Ordering::SeqCst) {
                    waker.wake_by_ref();
                }
                break;
            }
            let remaining = deadline.saturating_duration_since(now);
            let quantum = std::time::Duration::from_millis(1);
            std::thread::sleep(remaining.min(quantum));
        });
        DeadlineGuard {
            done,
            handle: Some(handle),
        }
    }
    fn disarm(&mut self) {
        self.done.store(true, Ordering::SeqCst);
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

impl Drop for DeadlineGuard {
    fn drop(&mut self) {
        self.disarm();
    }
}

fn owned_run(
    stage: ai_task_support::Stage,
    name: ai_task_support::StageName,
) -> impl Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>> + Send + 'static
{
    async move { stage.run(name).await }
}

struct Race {
    inner: Pin<Box<dyn Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>> + Send>>,
    name: ai_task_support::StageName,
    deadline: Instant,
    guard: Option<DeadlineGuard>,
}

impl Future for Race {
    type Output = Result<ai_task_support::Artifact, PipelineError>;
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };
        if Instant::now() >= this.deadline {
            this.guard.take();
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if this.guard.is_none() {
            this.guard = Some(DeadlineGuard::arm(this.deadline, cx.waker().clone()));
        }
        match this.inner.as_mut().poll(cx) {
            Poll::Ready(Ok(a)) => {
                this.guard.take();
                if Instant::now() >= this.deadline {
                    return Poll::Ready(Err(PipelineError::Deadline));
                }
                Poll::Ready(Ok(a))
            }
            Poll::Ready(Err(_)) => {
                let name = this.name.clone();
                this.guard.take();
                if Instant::now() >= this.deadline {
                    return Poll::Ready(Err(PipelineError::Deadline));
                }
                Poll::Ready(Err(PipelineError::Stage { name }))
            }
            Poll::Pending => {
                if Instant::now() >= this.deadline {
                    this.guard.take();
                    return Poll::Ready(Err(PipelineError::Deadline));
                }
                Poll::Pending
            }
        }
    }
}

fn race_stage(
    stage: ai_task_support::Stage,
    name: ai_task_support::StageName,
    deadline: Instant,
) -> Race {
    let inner: Pin<Box<dyn Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>> + Send>> =
        Box::pin(owned_run(stage, name));
    Race {
        inner,
        name,
        deadline,
        guard: None,
    }
}

struct JoinFetch {
    a: Option<Pin<Box<dyn Future<Output = Result<ai_task_support::Artifact, PipelineError>> + Send>>>,
    b: Option<Pin<Box<dyn Future<Output = Result<ai_task_support::Artifact, PipelineError>> + Send>>>,
    a_done: Option<Result<ai_task_support::Artifact, PipelineError>>,
    b_done: Option<Result<ai_task_support::Artifact, PipelineError>>,
    guard: Option<DeadlineGuard>,
    deadline: Instant,
}

impl Future for JoinFetch {
    type Output = Result<(ai_task_support::Artifact, ai_task_support::Artifact), PipelineError>;
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };
        if Instant::now() >= this.deadline {
            this.a.take();
            this.b.take();
            this.guard.take();
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if this.guard.is_none() {
            this.guard = Some(DeadlineGuard::arm(this.deadline, cx.waker().clone()));
        }
        if this.a_done.is_none() {
            if let Some(mut f) = this.a.take() {
                match f.as_mut().poll(cx) {
                    Poll::Ready(r) => {
                        this.a_done = Some(r);
                    }
                    Poll::Pending => {
                        this.a = Some(f);
                    }
                }
            }
        }
        if Instant::now() >= this.deadline {
            this.a.take();
            this.b.take();
            this.guard.take();
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if this.b_done.is_none() {
            if let Some(mut f) = this.b.take() {
                match f.as_mut().poll(cx) {
                    Poll::Ready(r) => {
                        this.b_done = Some(r);
                    }
                    Poll::Pending => {
                        this.b = Some(f);
                    }
                }
            }
        }
        if Instant::now() >= this.deadline {
            this.a.take();
            this.b.take();
            this.guard.take();
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if matches!(this.a_done, Some(Err(_))) {
            let e = this.a_done.take().unwrap().unwrap_err();
            this.a.take();
            this.b.take();
            this.guard.take();
            if Instant::now() >= this.deadline {
                return Poll::Ready(Err(PipelineError::Deadline));
            }
            return Poll::Ready(Err(e));
        }
        if matches!(this.b_done, Some(Err(_))) {
            let e = this.b_done.take().unwrap().unwrap_err();
            this.a.take();
            this.b.take();
            this.guard.take();
            if Instant::now() >= this.deadline {
                return Poll::Ready(Err(PipelineError::Deadline));
            }
            return Poll::Ready(Err(e));
        }
        match (this.a_done.take(), this.b_done.take()) {
            (Some(Ok(a)), Some(Ok(b))) => {
                this.a.take();
                this.b.take();
                this.guard.take();
                if Instant::now() >= this.deadline {
                    return Poll::Ready(Err(PipelineError::Deadline));
                }
                Poll::Ready(Ok((a, b)))
            }
            (a_opt, b_opt) => {
                this.a_done = a_opt;
                this.b_done = b_opt;
                if Instant::now() >= this.deadline {
                    this.a.take();
                    this.b.take();
                    this.guard.take();
                    return Poll::Ready(Err(PipelineError::Deadline));
                }
                Poll::Pending
            }
        }
    }
}

async fn pipeline_inner(
    stage_a: ai_task_support::Stage,
    stage_b: ai_task_support::Stage,
    stage_c: ai_task_support::Stage,
    stage_p: ai_task_support::Stage,
    deadline: Instant,
) -> Result<ai_task_support::Published, PipelineError> {
    use ai_task_support::StageName;
    if Instant::now() >= deadline {
        return Err(PipelineError::Deadline);
    }
    let fa: Pin<Box<dyn Future<Output = Result<ai_task_support::Artifact, PipelineError>> + Send>> =
        Box::pin(race_stage(stage_a, StageName::FetchA, deadline));
    let fb: Pin<Box<dyn Future<Output = Result<ai_task_support::Artifact, PipelineError>> + Send>> =
        Box::pin(race_stage(stage_b, StageName::FetchB, deadline));
    let join = JoinFetch {
        a: Some(fa),
        b: Some(fb),
        a_done: None,
        b_done: None,
        guard: None,
        deadline,
    };
    let (_a, _b) = match join.await {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    if Instant::now() >= deadline {
        return Err(PipelineError::Deadline);
    }
    let _combined = match race_stage(stage_c, StageName::Combine, deadline).await {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    if Instant::now() >= deadline {
        return Err(PipelineError::Deadline);
    }
    let published_artifact = match race_stage(stage_p, StageName::Publish, deadline).await {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    if Instant::now() >= deadline {
        return Err(PipelineError::Deadline);
    }
    Ok(ai_task_support::Published::from(published_artifact))
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let end = std::time::Instant::now() + deadline;
    if std::time::Instant::now() >= end {
        return Err(PipelineError::Deadline);
    }

    let (a, b): (
        ai_task_support::Artifact,
        ai_task_support::Artifact,
    ) = {
        let mut fa = Box::pin(stage.run(ai_task_support::StageName::FetchA));
        let mut fb = Box::pin(stage.run(ai_task_support::StageName::FetchB));
        let mut ra: Option<
            Result<ai_task_support::Artifact, ai_task_support::StageError>,
        > = None;
        let mut rb: Option<
            Result<ai_task_support::Artifact, ai_task_support::StageError>,
        > = None;
        let mut timer = false;
        let r: Result<
            (
                ai_task_support::Artifact,
                ai_task_support::Artifact,
            ),
            PipelineError,
        > = std::future::poll_fn(|cx| {
            if ra.is_none() {
                if let std::task::Poll::Ready(v) = fa.as_mut().poll(cx) {
                    ra = Some(v);
                }
            }
            if rb.is_none() {
                if let std::task::Poll::Ready(v) = fb.as_mut().poll(cx) {
                    rb = Some(v);
                }
            }
            if let Some(Err(_)) = &ra {
                return std::task::Poll::Ready(Err(PipelineError::Stage {
                    name: ai_task_support::StageName::FetchA,
                }));
            }
            if let Some(Err(_)) = &rb {
                return std::task::Poll::Ready(Err(PipelineError::Stage {
                    name: ai_task_support::StageName::FetchB,
                }));
            }
            if let (Some(Ok(_)), Some(Ok(_))) = (&ra, &rb) {
                let av = ra.take().unwrap().unwrap();
                let bv = rb.take().unwrap().unwrap();
                return std::task::Poll::Ready(Ok((av, bv)));
            }
            if std::time::Instant::now() >= end {
                return std::task::Poll::Ready(Err(PipelineError::Deadline));
            }
            if !timer {
                timer = true;
                let w = cx.waker().clone();
                let d = end.saturating_duration_since(std::time::Instant::now());
                std::thread::spawn(move || {
                    std::thread::sleep(d);
                    w.wake();
                });
            }
            std::task::Poll::Pending
        })
        .await;
        r?
    };
    let _ = (a, b);

    if std::time::Instant::now() >= end {
        return Err(PipelineError::Deadline);
    }
    let _c: ai_task_support::Artifact = {
        let mut f = Box::pin(stage.run(ai_task_support::StageName::Combine));
        let mut timer = false;
        let r: Result<ai_task_support::Artifact, PipelineError> =
            std::future::poll_fn(|cx| {
                if let std::task::Poll::Ready(v) = f.as_mut().poll(cx) {
                    match v {
                        Ok(v) => std::task::Poll::Ready(Ok(v)),
                        Err(_) => std::task::Poll::Ready(Err(PipelineError::Stage {
                            name: ai_task_support::StageName::Combine,
                        })),
                    }
                } else if std::time::Instant::now() >= end {
                    std::task::Poll::Ready(Err(PipelineError::Deadline))
                } else {
                    if !timer {
                        timer = true;
                        let w = cx.waker().clone();
                        let d =
                            end.saturating_duration_since(std::time::Instant::now());
                        std::thread::spawn(move || {
                            std::thread::sleep(d);
                            w.wake();
                        });
                    }
                    std::task::Poll::Pending
                }
            })
            .await;
        r?
    };

    if std::time::Instant::now() >= end {
        return Err(PipelineError::Deadline);
    }
    let p: ai_task_support::Artifact = {
        let mut f = Box::pin(stage.run(ai_task_support::StageName::Publish));
        let mut timer = false;
        let r: Result<ai_task_support::Artifact, PipelineError> =
            std::future::poll_fn(|cx| {
                if let std::task::Poll::Ready(v) = f.as_mut().poll(cx) {
                    match v {
                        Ok(v) => std::task::Poll::Ready(Ok(v)),
                        Err(_) => std::task::Poll::Ready(Err(PipelineError::Stage {
                            name: ai_task_support::StageName::Publish,
                        })),
                    }
                } else if std::time::Instant::now() >= end {
                    std::task::Poll::Ready(Err(PipelineError::Deadline))
                } else {
                    if !timer {
                        timer = true;
                        let w = cx.waker().clone();
                        let d =
                            end.saturating_duration_since(std::time::Instant::now());
                        std::thread::spawn(move || {
                            std::thread::sleep(d);
                            w.wake();
                        });
                    }
                    std::task::Poll::Pending
                }
            })
            .await;
        r?
    };
    Ok(p.into())
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

struct Timeout<F> {
    inner: F,
    start: std::time::Instant,
    dur: std::time::Duration,
    timer_started: bool,
    cancel: std::sync::Arc<std::sync::atomic::AtomicBool>,
}

impl<F> Drop for Timeout<F> {
    fn drop(&mut self) {
        self.cancel
            .store(true, std::sync::atomic::Ordering::SeqCst);
    }
}

impl<F> std::future::Future for Timeout<F>
where
    F: std::future::Future<Output = Result<ai_task_support::Artifact, PipelineError>>,
{
    type Output = Result<ai_task_support::Artifact, PipelineError>;
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };
        if this.start.elapsed() >= this.dur {
            return std::task::Poll::Ready(Err(PipelineError::Deadline));
        }
        let inner =
            unsafe { std::pin::Pin::new_unchecked(&mut this.inner).poll(cx) };
        match inner {
            std::task::Poll::Ready(v) => {
                if this.start.elapsed() >= this.dur {
                    return std::task::Poll::Ready(Err(PipelineError::Deadline));
                }
                std::task::Poll::Ready(v)
            }
            std::task::Poll::Pending => {
                if !this.timer_started {
                    this.timer_started = true;
                    let w = cx.waker().clone();
                    let s = this.start;
                    let d = this.dur;
                    let c = this.cancel.clone();
                    std::thread::spawn(move || loop {
                        if c.load(std::sync::atomic::Ordering::SeqCst) {
                            break;
                        }
                        let e = s.elapsed();
                        if e >= d {
                            w.wake();
                            break;
                        }
                        let rem = d.checked_sub(e).unwrap_or(std::time::Duration::ZERO);
                        let step = rem.min(std::time::Duration::from_millis(1));
                        if step.is_zero() {
                            w.wake();
                            break;
                        }
                        std::thread::sleep(step);
                    });
                }
                std::task::Poll::Pending
            }
        }
    }
}

struct JoinFetch<A, B> {
    a: Option<A>,
    b: Option<B>,
    a_ok: Option<ai_task_support::Artifact>,
    b_ok: Option<ai_task_support::Artifact>,
}

impl<A, B> std::future::Future for JoinFetch<A, B>
where
    A: std::future::Future<Output = Result<ai_task_support::Artifact, PipelineError>>,
    B: std::future::Future<Output = Result<ai_task_support::Artifact, PipelineError>>,
{
    type Output =
        Result<(ai_task_support::Artifact, ai_task_support::Artifact), PipelineError>;
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };
        if this.a_ok.is_none() {
            if let Some(f) = this.a.as_mut() {
                match unsafe { std::pin::Pin::new_unchecked(f).poll(cx) } {
                    std::task::Poll::Ready(Ok(v)) => {
                        this.a.take();
                        this.a_ok = Some(v);
                    }
                    std::task::Poll::Ready(Err(e)) => {
                        return std::task::Poll::Ready(Err(e));
                    }
                    std::task::Poll::Pending => {}
                }
            }
        }
        if this.b_ok.is_none() {
            if let Some(f) = this.b.as_mut() {
                match unsafe { std::pin::Pin::new_unchecked(f).poll(cx) } {
                    std::task::Poll::Ready(Ok(v)) => {
                        this.b.take();
                        this.b_ok = Some(v);
                    }
                    std::task::Poll::Ready(Err(e)) => {
                        return std::task::Poll::Ready(Err(e));
                    }
                    std::task::Poll::Pending => {}
                }
            }
        }
        if this.a_ok.is_some() && this.b_ok.is_some() {
            let a = this.a_ok.take().unwrap();
            let b = this.b_ok.take().unwrap();
            std::task::Poll::Ready(Ok((a, b)))
        } else {
            std::task::Poll::Pending
        }
    }
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let start = std::time::Instant::now();
    let dur = deadline;
    {
        let s1 = stage.clone();
        let s2 = stage.clone();
        let fut_a = async move {
            match s1.run(ai_task_support::StageName::FetchA).await {
                Ok(a) => Ok(a),
                Err(_) => Err(PipelineError::Stage {
                    name: ai_task_support::StageName::FetchA,
                }),
            }
        };
        let fut_b = async move {
            match s2.run(ai_task_support::StageName::FetchB).await {
                Ok(b) => Ok(b),
                Err(_) => Err(PipelineError::Stage {
                    name: ai_task_support::StageName::FetchB,
                }),
            }
        };
        let ta = Timeout {
            inner: fut_a,
            start,
            dur,
            timer_started: false,
            cancel: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
        };
        let tb = Timeout {
            inner: fut_b,
            start,
            dur,
            timer_started: false,
            cancel: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
        };
        let j = JoinFetch {
            a: Some(ta),
            b: Some(tb),
            a_ok: None,
            b_ok: None,
        };
        j.await?;
    }
    {
        let s = stage.clone();
        let fut = async move {
            match s.run(ai_task_support::StageName::Combine).await {
                Ok(c) => Ok(c),
                Err(_) => Err(PipelineError::Stage {
                    name: ai_task_support::StageName::Combine,
                }),
            }
        };
        Timeout {
            inner: fut,
            start,
            dur,
            timer_started: false,
            cancel: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
        }
        .await?;
    }
    {
        let s = stage.clone();
        let fut = async move {
            match s.run(ai_task_support::StageName::Publish).await {
                Ok(v) => Ok(v),
                Err(_) => Err(PipelineError::Stage {
                    name: ai_task_support::StageName::Publish,
                }),
            }
        };
        let p = Timeout {
            inner: fut,
            start,
            dur,
            timer_started: false,
            cancel: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
        }
        .await?;
        Ok(p.into())
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::Instant;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

fn ensure_timer(
    deadline: Option<Instant>,
    slot: &Arc<Mutex<Option<Waker>>>,
    started: &mut bool,
    cx: &mut Context<'_>,
) {
    if let Some(dl) = deadline {
        if let Ok(mut g) = slot.lock() {
            *g = Some(cx.waker().clone());
        }
        if !*started {
            *started = true;
            let s = Arc::clone(slot);
            std::thread::spawn(move || {
                let now = Instant::now();
                if dl > now {
                    std::thread::sleep(dl - now);
                }
                let w = s.lock().ok().and_then(|mut g| g.take());
                if let Some(w) = w {
                    w.wake();
                }
            });
        }
    }
}

struct One<F> {
    inner: Pin<Box<F>>,
    name: Option<ai_task_support::StageName>,
    deadline: Option<Instant>,
    started: bool,
    slot: Arc<Mutex<Option<Waker>>>,
}

impl<F> Future for One<F>
where
    F: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
{
    type Output = Result<ai_task_support::Artifact, PipelineError>;
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };
        match this.inner.as_mut().poll(cx) {
            Poll::Ready(Ok(a)) => Poll::Ready(Ok(a)),
            Poll::Ready(Err(_)) => {
                let n = this.name.take().expect("polled after completion");
                Poll::Ready(Err(PipelineError::Stage { name: n }))
            }
            Poll::Pending => {
                if let Some(dl) = this.deadline {
                    if Instant::now() >= dl {
                        return Poll::Ready(Err(PipelineError::Deadline));
                    }
                }
                ensure_timer(this.deadline, &this.slot, &mut this.started, cx);
                Poll::Pending
            }
        }
    }
}

struct Two<F1, F2> {
    inner1: Pin<Box<F1>>,
    inner2: Pin<Box<F2>>,
    name1: Option<ai_task_support::StageName>,
    name2: Option<ai_task_support::StageName>,
    val1: Option<ai_task_support::Artifact>,
    val2: Option<ai_task_support::Artifact>,
    deadline: Option<Instant>,
    started: bool,
    slot: Arc<Mutex<Option<Waker>>>,
}

impl<F1, F2> Future for Two<F1, F2>
where
    F1: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
    F2: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
{
    type Output = Result<
        (
            ai_task_support::Artifact,
            ai_task_support::Artifact,
        ),
        PipelineError,
    >;
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };
        if this.val1.is_none() {
            match this.inner1.as_mut().poll(cx) {
                Poll::Ready(Ok(a)) => {
                    this.val1 = Some(a);
                }
                Poll::Ready(Err(_)) => {
                    let n = this.name1.take().expect("polled after completion");
                    return Poll::Ready(Err(PipelineError::Stage { name: n }));
                }
                Poll::Pending => {}
            }
        }
        if this.val2.is_none() {
            match this.inner2.as_mut().poll(cx) {
                Poll::Ready(Ok(b)) => {
                    this.val2 = Some(b);
                }
                Poll::Ready(Err(_)) => {
                    let n = this.name2.take().expect("polled after completion");
                    return Poll::Ready(Err(PipelineError::Stage { name: n }));
                }
                Poll::Pending => {}
            }
        }
        if this.val1.is_some() && this.val2.is_some() {
            let a = this.val1.take().unwrap();
            let b = this.val2.take().unwrap();
            return Poll::Ready(Ok((a, b)));
        }
        if let Some(dl) = this.deadline {
            if Instant::now() >= dl {
                return Poll::Ready(Err(PipelineError::Deadline));
            }
        }
        ensure_timer(this.deadline, &this.slot, &mut this.started, cx);
        Poll::Pending
    }
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let start = Instant::now();
    let dl: Option<Instant> = start.checked_add(deadline);
    let expired = || match dl {
        Some(t) => Instant::now() >= t,
        None => false,
    };
    if expired() {
        return Err(PipelineError::Deadline);
    }
    let (_a, _b) = {
        let fut_a = stage.run(ai_task_support::StageName::FetchA);
        let fut_b = stage.run(ai_task_support::StageName::FetchB);
        Two {
            inner1: Box::pin(fut_a),
            inner2: Box::pin(fut_b),
            name1: Some(ai_task_support::StageName::FetchA),
            name2: Some(ai_task_support::StageName::FetchB),
            val1: None,
            val2: None,
            deadline: dl,
            started: false,
            slot: Arc::new(Mutex::new(None)),
        }
        .await?
    };
    if expired() {
        return Err(PipelineError::Deadline);
    }
    let _c = {
        let fut_c = stage.run(ai_task_support::StageName::Combine);
        One {
            inner: Box::pin(fut_c),
            name: Some(ai_task_support::StageName::Combine),
            deadline: dl,
            started: false,
            slot: Arc::new(Mutex::new(None)),
        }
        .await?
    };
    if expired() {
        return Err(PipelineError::Deadline);
    }
    let p = {
        let fut_p = stage.run(ai_task_support::StageName::Publish);
        One {
            inner: Box::pin(fut_p),
            name: Some(ai_task_support::StageName::Publish),
            deadline: dl,
            started: false,
            slot: Arc::new(Mutex::new(None)),
        }
        .await?
    };
    Ok(p.into())
}

