use std::collections::HashMap;
use std::future::Future;
use std::pin::Pin;
use std::sync::{Mutex, OnceLock};
use std::task::{Context, Poll};

#[derive(Debug, PartialEq, Eq)]
pub enum CacheError {
    Refused,
}

struct YieldOnce {
    yielded: bool,
}

impl Future for YieldOnce {
    type Output = ();
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        if self.yielded {
            Poll::Ready(())
        } else {
            self.yielded = true;
            cx.waker().wake_by_ref();
            Poll::Pending
        }
    }
}

static CACHE: OnceLock<Mutex<HashMap<(String, String), Vec<u8>>>> = OnceLock::new();

fn cache() -> &'static Mutex<HashMap<(String, String), Vec<u8>>> {
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

pub async fn solve(tenant: &str, resource: &str, token: &str) -> Result<Vec<u8>, CacheError> {
    let expected = format!("token-for-{}", tenant);
    if token != expected {
        return Err(CacheError::Refused);
    }

    let key = (tenant.to_owned(), resource.to_owned());

    {
        let guard = cache().lock().unwrap_or_else(|p| p.into_inner());
        if let Some(hit) = guard.get(&key) {
            return Ok(hit.clone());
        }
    }

    // Async suspension point held without any shared lock, so dropping
    // the future here poisons nothing shared with other calls.
    YieldOnce { yielded: false }.await;

    let value = format!("value-of-{}-{}", key.0, key.1).into_bytes();

    {
        let mut guard = cache().lock().unwrap_or_else(|p| p.into_inner());
        if let Some(hit) = guard.get(&key) {
            return Ok(hit.clone());
        }
        guard.insert(key, value.clone());
    }

    Ok(value)
}

use lgwks_bot::script::{FlowError, Scope, Tenant, each, within};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let tenant = match Tenant::new("aggregate") {
        Ok(t) => t,
        Err(e) => {
            if e.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            if matches!(&e, FlowError::TimedOut { .. }) {
                return Err(SolveError::Deadline);
            }
            return Err(SolveError::Cancelled);
        }
    };
    let scope = Scope::root(tenant);
    let limit = std::num::NonZeroUsize::new(4).expect("4 is non-zero");
    let failing: std::sync::Arc<std::sync::Mutex<Option<u32>>> =
        std::sync::Arc::new(std::sync::Mutex::new(None));
    let fetch_owned = fetch;
    let failing_owned = failing.clone();
    let res: Result<u64, FlowError> = within(
        &scope,
        "deadline",
        deadline,
        async {
            let vals: Vec<u64> = each(
                &scope,
                "fetch",
                Some(limit),
                ids,
                move |item_scope: Scope, id: u32| {
                    let f = fetch_owned.clone();
                    let fl = failing_owned.clone();
                    async move {
                        let _keep_scope = item_scope;
                        match f.fetch(id).await {
                            Ok(v) => Ok(v),
                            Err(_) => {
                                if let Ok(mut g) = fl.lock() {
                                    if g.is_none() {
                                        *g = Some(id);
                                    }
                                }
                                Err(FlowError::failed(format!("fetch {}", id)))
                            }
                        }
                    }
                },
            )
            .await?;
            Ok(vals.into_iter().fold(0u64, |a, b| a.wrapping_add(b)))
        },
    )
    .await;
    match res {
        Ok(s) => Ok(s),
        Err(e) => {
            if e.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            if matches!(&e, FlowError::TimedOut { .. }) {
                return Err(SolveError::Deadline);
            }
            if let Ok(g) = failing.lock() {
                if let Some(id) = *g {
                    return Err(SolveError::Fetch { id });
                }
            }
            Err(SolveError::Cancelled)
        }
    }
}

use lgwks_bot::script::{FlowError, ResultExt, Scope, Tenant, each, within};
use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let tenant: Tenant = match Tenant::new("demo") {
        Ok(t) => t,
        Err(_) => {
            return Err(SolveError::Cancelled);
        }
    };
    let scope: Scope = Scope::root(tenant);
    let flag: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let limit: NonZeroUsize = match NonZeroUsize::new(4) {
        Some(n) => n,
        None => {
            scope.cancel();
            return Err(SolveError::Cancelled);
        }
    };
    let flag_for_body: Arc<Mutex<Option<u32>>> = Arc::clone(&flag);
    let each_future = each(
        &scope,
        "fetch",
        Some(limit),
        ids,
        move |_s: Scope, id: u32| {
            let fc: ai_task_support::Fetcher = fetch.clone();
            let fl: Arc<Mutex<Option<u32>>> = Arc::clone(&flag_for_body);
            async move {
                match fc.fetch(id).await {
                    Ok(v) => Ok(v),
                    Err(_) => {
                        match fl.lock() {
                            Ok(mut g) => {
                                if g.is_none() {
                                    *g = Some(id);
                                }
                            }
                            Err(p) => {
                                let mut g = p.into_inner();
                                if g.is_none() {
                                    *g = Some(id);
                                }
                            }
                        }
                        let conv: Result<u64, FlowError> =
                            Err::<u64, String>(format!("fetch {}", id)).or_fail();
                        match conv {
                            Ok(v) => Ok(v),
                            Err(fe) => Err(fe),
                        }
                    }
                }
            }
        },
    );
    let outcome: Result<Vec<u64>, FlowError> =
        within(&scope, "deadline", deadline, each_future).await;
    match outcome {
        Ok(vals) => {
            let mut acc: u64 = 0;
            for v in vals {
                acc = acc.wrapping_add(v);
            }
            scope.cancel();
            Ok(acc)
        }
        Err(fe) => {
            scope.cancel();
            if fe.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            let recorded: Option<u32> = match flag.lock() {
                Ok(g) => *g,
                Err(p) => {
                    let g = p.into_inner();
                    *g
                }
            };
            match recorded {
                Some(fid) => Err(SolveError::Fetch { id: fid }),
                None => Err(SolveError::Deadline),
            }
        }
    }
}

