    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let tenant = match Tenant::new("aggregate") {
        Ok(t) => t,
        Err(_) => return Err(SolveError::Deadline),
    };
    let scope = Scope::root(tenant);
    let limit = NonZeroUsize::new(4).unwrap();
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let f2 = fetch;
    let fail2 = failed.clone();
    let r = within(&scope, "w", deadline, async {
        let v = each(&scope, "f", Some(limit), ids, move |_, id: u32| {
            let f = f2.clone();
            let fl = fail2.clone();
            async move {
                match f.fetch(id).await {
                    Ok(x) => Ok(x),
                    Err(e) => {
                        {
                            let mut g = fl.lock().unwrap();
                            if g.is_none() {
                                *g = Some(id);
                            }
                        }
                        Err(Result::<u64, _>::Err(e).or_fail().unwrap_err())
                    }
                }
            }
        })
        .await?;
        Ok::<u64, _>(v.into_iter().sum())
    })
    .await;
    match r {
        Ok(s) => Ok(s),
        Err(e) => {
            if e.is_cancelled() {
                Err(SolveError::Cancelled)
            } else if let Some(id) = *failed.lock().unwrap() {
                Err(SolveError::Fetch { id })
            } else {
                Err(SolveError::Deadline)
            }
        }
