#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let tenant = match Tenant::new("demo") {
        Ok(t) => t,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let scope_ref: &Scope = &scope;
    let first: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let first_outer = first.clone();
    let limit = NonZeroUsize::new(4).unwrap();
    let res: Result<u64, FlowError> = within(&scope, "solve", deadline, async move {
        let vals: Vec<u64> = each(
            scope_ref,
            "fetch",
            Some(limit),
            ids,
            move |_, id: u32| {
                let f = fetch.clone();
                let fc = first.clone();
                async move {
                    let v = f.fetch(id).await.or_fail().map_err(|e| {
                        if let Ok(mut g) = fc.lock() {
                            if g.is_none() {
                                *g = Some(id);
                            }
                        }
                        e
                    })?;
                    Ok::<u64, FlowError>(v)
                }
            },
        )
        .await?;
        Ok::<u64, FlowError>(vals.into_iter().sum())
    })
    .await;
    match res {
        Ok(s) => Ok(s),
        Err(e) => match e {
            FlowError::TimedOut { .. } => Err(SolveError::Deadline),
            FlowError::Cancelled { .. } => Err(SolveError::Cancelled),
            e => {
                if e.is_cancelled() {
                    return Err(SolveError::Cancelled);
                }
                if let Ok(g) = first_outer.lock() {
                    if let Some(id) = *g {
                        return Err(SolveError::Fetch { id });
                    }
                }
                Err(SolveError::Cancelled)
            }
        },
    }
}

use lgwks_bot::script::{FlowError, ResultExt, Scope, Tenant, each, within};
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let tenant = match Tenant::new("solve") {
        Ok(t) => t,
        Err(_) => panic!("valid tenant"),
    };
    let scope = Scope::root(tenant);
    let limit = match std::num::NonZeroUsize::new(4) {
        Some(n) => n,
        None => panic!("non-zero"),
    };
    let failed = Arc::new(AtomicU64::new(u64::MAX));
    let fut = each(&scope, "fetch", Some(limit), ids, |_child: Scope, id: u32| {
        let f = fetch.clone();
        let slot = Arc::clone(&failed);
        async move {
            let r = f.fetch(id).await;
            if r.is_err() {
                slot.store(id as u64, Ordering::Relaxed);
            }
            r.or_fail()
        }
    });
    let res: Result<Vec<u64>, FlowError> = within(&scope, "solve", deadline, fut).await;
    match res {
        Ok(vals) => Ok(vals.into_iter().sum()),
        Err(e) => {
            if e.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            if matches!(e, FlowError::TimedOut { .. }) {
                return Err(SolveError::Deadline);
            }
            let v = failed.load(Ordering::Relaxed);
            if v != u64::MAX {
                return Err(SolveError::Fetch { id: v as u32 });
            }
            Err(SolveError::Deadline)
        }
    }
}

#[derive(Debug)]
pub enum CaptureError {
    Spawn(String),
    Deadline,
    Cancelled,
}

#[derive(Debug, PartialEq, Eq)]
pub struct CaptureResult {
    head: Vec<u8>,
    total_bytes: u64,
    truncated: bool,
}

impl CaptureResult {
    pub fn new(head: Vec<u8>, total_bytes: u64, truncated: bool) -> Self {
        Self {
            head,
            total_bytes,
            truncated,
        }
    }
    pub fn head(&self) -> &[u8] {
        &self.head
    }
    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }
    pub fn truncated(&self) -> bool {
        self.truncated
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut spec = lgwks_bot::rt::process::ProcessSpec::new(&argv[0]);
    for a in &argv[1..] {
        spec.arg(a);
    }
    let limit = std::num::NonZeroUsize::new(head_limit)
        .unwrap_or_else(|| std::num::NonZeroUsize::new(1).unwrap());
    spec.capture_stdout(limit);
    spec.deadline(deadline);
    let mut sup: lgwks_bot::rt::supervise::Supervisor = Default::default();
    let start = std::time::Instant::now();
    match sup.run_process(&spec).await {
        Ok(run) => {
            if run.deadline_fired() {
                return Err(CaptureError::Deadline);
            }
            let total = run.stdout().total_bytes();
            let bytes = run.stdout().bytes();
            let take = std::cmp::min(bytes.len(), head_limit);
            let head = bytes[..take].to_vec();
            let truncated = total > head_limit as u64;
            Ok(CaptureResult::new(head, total, truncated))
        }
        Err(e) => {
            let dbg = format!("{:?}", e);
            if dbg.contains("NotStarted") {
                return Err(CaptureError::Spawn(dbg));
            }
            if dbg.contains("Refused") {
                return Err(CaptureError::Cancelled);
            }
            if dbg.contains("AfterStart") {
                let low = dbg.to_lowercase();
                if low.contains("deadline")
                    || low.contains("timed out")
                    || low.contains("timeout")
                    || low.contains("expired")
                {
                    return Err(CaptureError::Deadline);
                }
                if start.elapsed() >= deadline {
                    return Err(CaptureError::Deadline);
                }
                return Err(CaptureError::Cancelled);
            }
            if start.elapsed() >= deadline {
                return Err(CaptureError::Deadline);
            }
            Err(CaptureError::Cancelled)
        }
    }
}

