    }
    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }
    pub fn truncated(&self) -> bool {
        self.truncated
    }
}

struct Guard {
    pid: u32,
    child: Option<std::process::Child>,
    reader: Option<std::thread::JoinHandle<(Vec<u8>, u64)>>,
}

fn kill_group(pid: u32) {
    #[cfg(unix)]
    unsafe {
        const SIGKILL: i32 = 9;
        let id = pid as i32;
        let _ = killpg(id, SIGKILL);
        let _ = kill(id, SIGKILL);
    }
    #[cfg(not(unix))]
    {
        let _ = pid;
    }
}

impl Drop for Guard {
    fn drop(&mut self) {
        kill_group(self.pid);
        if let Some(mut c) = self.child.take() {
            let _ = c.kill();
            let _ = c.wait();
        }
        kill_group(self.pid);
        if let Some(h) = self.reader.take() {
            let _ = h.join();
        }
        kill_group(self.pid);
    }
}

fn read_stdout(out: Option<std::process::ChildStdout>, limit: usize) -> (Vec<u8>, u64) {
    let mut s = match out {
        Some(v) => v,
        None => return (Vec::new(), 0),
    };
    let mut head: Vec<u8> = Vec::new();
    let mut total: u64 = 0;
    let mut buf = [0u8; 8192];
    loop {
        let n = match std::io::Read::read(&mut s, &mut buf) {
            Ok(0) => break,
            Ok(n) => n,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                } else {
                    break;
                }
            }
        };
        total = total.saturating_add(n as u64);
        if head.len() < limit {
            let rem = limit - head.len();
            let take = if n < rem { n } else { rem };
            head.extend_from_slice(&buf[..take]);
        }
    }
    (head, total)
}

async fn yield_point() {
    std::future::poll_fn(|cx| {
        cx.waker().wake_by_ref();
        std::task::Poll::<()>::Pending
    })
    .await
}

#[allow(unused_unsafe)]
pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn(
            "empty argv: no program to run".to_string(),
        ));
    }
    let program = argv[0].clone();
    let prog_args = argv[1..].to_vec();
    let mut cmd = std::process::Command::new(&program);
    cmd.args(&prog_args);
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    #[cfg(unix)]
    unsafe {
        use std::os::unix::process::CommandExt as _;
        cmd.pre_exec(|| {
            unsafe {
                let _ = setsid();
            }
            Ok(())
        });
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => {
            return Err(CaptureError::Spawn(format!("spawn {}: {}", program, e)));
        }
    };
    let pid = child.id();
    let out = child.stdout.take();
    let reader = std::thread::spawn(move || read_stdout(out, head_limit));
    let mut guard = Guard {
        pid,
        child: Some(child),
        reader: Some(reader),
    };
    let start = std::time::Instant::now();
    let mut exited = false;
    loop {
        if !exited {
            if let Some(c) = guard.child.as_mut() {
                match c.try_wait() {
                    Ok(Some(_)) => {
                        exited = true;
                    }
                    Ok(None) => {}
                    Err(_) => {}
                }
            } else {
                exited = true;
            }
        }
        if exited {
            break;
        }
        if start.elapsed() >= deadline {
            drop(guard);
            return Err(CaptureError::Deadline);
        }
        std::thread::sleep(std::time::Duration::from_millis(1));
        yield_point().await;
    }
    kill_group(pid);
    loop {
        let done = match guard.reader.as_ref() {
            Some(h) => h.is_finished(),
            None => true,
        };
        if done {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(1));
        yield_point().await;
        kill_group(pid);
    }
    let (head, total) = match guard.reader.take() {
        Some(h) => match h.join() {
            Ok(v) => v,
            Err(_) => (Vec::new(), 0),
        },
        None => (Vec::new(), 0),
    };
    kill_group(pid);
    if let Some(mut c) = guard.child.take() {
        let _ = c.wait();
    }
    kill_group(pid);
    let truncated = total > head_limit as u64;
    let mut h = head;
    if h.len() > head_limit {
        h.truncate(head_limit);
    }
    Ok(CaptureResult::new(h, total, truncated))
}

