                        let _ = f.sync_all();
                    }
                    true
                }
            }
        }
    };

    let start = Instant::now();
    loop {
        if release_path.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let elapsed = start.elapsed();
        let remaining = deadline
            .checked_sub(elapsed)
            .unwrap_or(Duration::from_secs(0));
        if remaining.is_zero() {
            return Err(RecoverError::Deadline);
        }
        let step = if remaining < Duration::from_millis(10) {
            remaining
        } else {
            Duration::from_millis(10)
        };
        sleep_async(step).await;
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

async fn sleep_async(dur: Duration) {
    if dur.is_zero() {
        return;
    }
    let deadline = Instant::now() + dur;
    std::future::poll_fn(|cx| {
        let now = Instant::now();
        if now >= deadline {
            std::task::Poll::Ready(())
        } else {
            let waker = cx.waker().clone();
            let remaining = deadline - now;
            std::thread::spawn(move || {
                std::thread::sleep(remaining);
                waker.wake();
            });
            std::task::Poll::Pending
        }
    })
    .await
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

struct Sleep {
    wake_at: std::time::Instant,
    started: bool,
}

impl std::future::Future for Sleep {
    type Output = ();
    fn poll(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<()> {
        if std::time::Instant::now() >= self.wake_at {
            return std::task::Poll::Ready(());
        }
        if !self.started {
            self.started = true;
            let waker = cx.waker().clone();
            let dur = self
                .wake_at
                .saturating_duration_since(std::time::Instant::now());
            std::thread::spawn(move || {
                std::thread::sleep(dur);
                waker.wake();
            });
        }
        std::task::Poll::Pending
    }
}

fn sleep_async(dur: std::time::Duration) -> Sleep {
    Sleep {
        wake_at: std::time::Instant::now() + dur,
        started: false,
    }
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let start = std::time::Instant::now();
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let target_line = format!("applied:{key}");
    let target_bytes = format!("applied:{key}\n");

    let _ = std::fs::create_dir_all(&effect_dir);

    // Check-then-append runs synchronously before the first await, so a
    // drop can only land during the release wait below, after the record
    // is already durable.
    let already_applied: bool = match std::fs::read_to_string(&applied_path) {
        Ok(content) => content.lines().any(|l| l == target_line),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => false,
    };

    let did_append: bool = if already_applied {
        false
    } else {
        let mut file = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&applied_path)
            .or_else(|_| {
                let _ = std::fs::create_dir_all(&effect_dir);
                std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .open(&applied_path)
            });
        if let Ok(f) = file.as_mut() {
            use std::io::Write;
            let _ = f.write_all(target_bytes.as_bytes());
            let _ = f.flush();
            let _ = f.sync_all();
        }
        true
    };

    loop {
        if std::fs::metadata(&release_path).is_ok() {
            break;
        }
        let elapsed = start.elapsed();
        if elapsed >= deadline {
            if std::fs::metadata(&release_path).is_ok() {
                break;
            }
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline - elapsed;
        let step = std::cmp::min(remaining, std::time::Duration::from_millis(5));
        if step.is_zero() {
            if std::fs::metadata(&release_path).is_ok() {
                break;
            }
            return Err(RecoverError::Deadline);
        }
        sleep_async(step).await;
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

use lgwks_bot::script::{FlowError, Scope, Tenant, each, within};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let tenant = match Tenant::new("pipeline") {
        Ok(t) => t,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let s_fetch = stage.clone();
    let s_rest = stage.clone();

    let res: Result<ai_task_support::Published, FlowError> =
        within(&scope, "run", deadline, async {
            let arts: Vec<ai_task_support::Artifact> = each(
                &scope,
                "fetch",
                None,
                [
                    ai_task_support::StageName::FetchA,
                    ai_task_support::StageName::FetchB,
                ],
                |_child, name| {
                    let st = s_fetch.clone();
                    let tag = match &name {
                        ai_task_support::StageName::FetchA => "FetchA",
                        ai_task_support::StageName::FetchB => "FetchB",
                        ai_task_support::StageName::Combine => "Combine",
                        ai_task_support::StageName::Publish => "Publish",
                    }
                    .to_string();
                    async move {
                        match st.run(name).await {
                            Ok(a) => Ok(a),
                            Err(_) => Err(FlowError::failed(tag)),
                        }
                    }
                },
            )
            .await?;
            drop(arts);
            let _c = s_rest
                .run(ai_task_support::StageName::Combine)
                .await
                .map_err(|_| FlowError::failed("Combine".to_string()))?;
            let p = s_rest
                .run(ai_task_support::StageName::Publish)
                .await
                .map_err(|_| FlowError::failed("Publish".to_string()))?;
            Ok(ai_task_support::Published::from(p))
        })
        .await;

    match res {
        Ok(v) => Ok(v),
        Err(e) => {
            if e.is_cancelled() {
                return Err(PipelineError::Cancelled);
            }
            match e {
                FlowError::TimedOut { .. } => Err(PipelineError::Deadline),
                FlowError::Cancelled { .. } => Err(PipelineError::Cancelled),
                FlowError::Failed { reason, .. } => {
                    let s: &str = &reason;
                    match s {
                        "FetchA" => Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchA,
                        }),
                        "FetchB" => Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchB,
                        }),
                        "Combine" => Err(PipelineError::Stage {
                            name: ai_task_support::StageName::Combine,
                        }),
                        "Publish" => Err(PipelineError::Stage {
                            name: ai_task_support::StageName::Publish,
                        }),
                        _ => Err(PipelineError::Cancelled),
                    }
                }
                _ => Err(PipelineError::Cancelled),
            }
        }
    }
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    use lgwks_bot::script::{FlowError, each, within};

    let tenant = match lgwks_bot::script::Tenant::new("pipeline") {
        Ok(t) => t,
        Err(_) => panic!("valid tenant"),
    };
    let scope = lgwks_bot::script::Scope::root(tenant);

    let out: Result<ai_task_support::Published, FlowError> = within(
        &scope,
        "deadline",
        deadline,
        async {
            let fetch_stage = stage.clone();
            let _fetched = each(
                &scope,
                "fetch",
                Some(std::num::NonZeroUsize::new(2).unwrap()),
                [
                    ai_task_support::StageName::FetchA,
                    ai_task_support::StageName::FetchB,
                ],
                move |_: lgwks_bot::script::Scope, name: ai_task_support::StageName| {
                    let fetch_stage = fetch_stage.clone();
                    async move {
                        let is_b = matches!(&name, ai_task_support::StageName::FetchB);
                        let tag = if is_b { "FETCH_B_TAG" } else { "FETCH_A_TAG" };
                        match fetch_stage.run(name).await {
                            Ok(a) => Ok(a),
                            Err(_) => Err(FlowError::failed(tag.to_string())),
                        }
                    }
                },
            )
            .await?;

            let combine_stage = stage.clone();
            let _ = match combine_stage.run(ai_task_support::StageName::Combine).await {
                Ok(a) => a,
                Err(_) => return Err(FlowError::failed("COMBINE_TAG".to_string())),
            };

            let publish_stage = stage.clone();
            let part = match publish_stage.run(ai_task_support::StageName::Publish).await {
                Ok(a) => a,
                Err(_) => return Err(FlowError::failed("PUBLISH_TAG".to_string())),
            };

            Ok(ai_task_support::Published::from(part))
        },
    )
    .await;

    match out {
        Ok(p) => Ok(p),
        Err(e) => {
            if e.is_cancelled() {
                return Err(PipelineError::Cancelled);
            }
            match e {
                FlowError::Cancelled { .. } => Err(PipelineError::Cancelled),
                FlowError::TimedOut { .. } => Err(PipelineError::Deadline),
                FlowError::Failed { reason, .. } => {
                    if reason.contains("FETCH_A_TAG") {
                        Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchA,
                        })
                    } else if reason.contains("FETCH_B_TAG") {
                        Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchB,
                        })
                    } else if reason.contains("COMBINE_TAG") {
                        Err(PipelineError::Stage {
                            name: ai_task_support::StageName::Combine,
                        })
                    } else if reason.contains("PUBLISH_TAG") {
                        Err(PipelineError::Stage {
                            name: ai_task_support::StageName::Publish,
                        })
                    } else {
                        Err(PipelineError::Cancelled)
                    }
                }
                FlowError::Transient { reason, .. } => {
                    if reason.contains("FETCH_A_TAG") {
                        Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchA,
                        })
                    } else if reason.contains("FETCH_B_TAG") {
                        Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchB,
                        })
                    } else if reason.contains("COMBINE_TAG") {
                        Err(PipelineError::Stage {
                            name: ai_task_support::StageName::Combine,
                        })
                    } else if reason.contains("PUBLISH_TAG") {
                        Err(PipelineError::Stage {
                            name: ai_task_support::StageName::Publish,
                        })
                    } else {
                        Err(PipelineError::Cancelled)
                    }
                }
                _ => Err(PipelineError::Cancelled),
            }
        }
    }
}

use std::num::NonZeroUsize;

use lgwks_bot::script::{FlowError, Scope, Tenant, each, within};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let tenant = match Tenant::new("pipeline") {
        Ok(t) => t,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let res: Result<ai_task_support::Published, FlowError> = within(
        &scope,
        "pipeline",
        deadline,
        async {
            let limit = NonZeroUsize::new(2).unwrap();
            let items = [
                ai_task_support::StageName::FetchA,
                ai_task_support::StageName::FetchB,
            ];
            each(&scope, "fetch", Some(limit), items, |_child, name| {
                let s = stage.clone();
                async move {
                    match s.run(name).await {
                        Ok(_) => Ok::<(), FlowError>(()),
                        Err(_) => {
                            let msg = match name {
                                ai_task_support::StageName::FetchA => "FetchA",
                                ai_task_support::StageName::FetchB => "FetchB",
                                ai_task_support::StageName::Combine => "Combine",
                                ai_task_support::StageName::Publish => "Publish",
                            };
                            Err(FlowError::failed(msg))
                        }
                    }
                }
            })
            .await?;
            let _c = match stage.run(ai_task_support::StageName::Combine).await {
                Ok(a) => a,
                Err(_) => return Err(FlowError::failed("Combine")),
            };
            let p = match stage.run(ai_task_support::StageName::Publish).await {
                Ok(a) => a,
                Err(_) => return Err(FlowError::failed("Publish")),
            };
            Ok(ai_task_support::Published::from(p))
        },
    )
    .await;
    match res {
        Ok(v) => Ok(v),
        Err(e) => Err(map_flow_error(e)),
    }
}

fn map_flow_error(e: FlowError) -> PipelineError {
    if e.is_cancelled() {
        return PipelineError::Cancelled;
    }
    match e {
        FlowError::TimedOut { .. } => PipelineError::Deadline,
        FlowError::Cancelled { .. } => PipelineError::Cancelled,
        FlowError::Failed { reason, .. } => decode_reason(&reason),
        FlowError::Transient { reason, .. } => decode_reason(&reason),
        _ => PipelineError::Cancelled,
    }
}

fn decode_reason(s: &str) -> PipelineError {
    if s.contains("FetchA") {
        PipelineError::Stage {
            name: ai_task_support::StageName::FetchA,
        }
    } else if s.contains("FetchB") {
        PipelineError::Stage {
            name: ai_task_support::StageName::FetchB,
        }
    } else if s.contains("Combine") {
        PipelineError::Stage {
            name: ai_task_support::StageName::Combine,
        }
    } else if s.contains("Publish") {
        PipelineError::Stage {
            name: ai_task_support::StageName::Publish,
        }
    } else {
        PipelineError::Cancelled
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};

use lgwks_bot::script::ResultExt;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let tenant = lgwks_bot::script::Tenant::new("pipeline").expect("valid tenant");
    let scope = lgwks_bot::script::Scope::root(tenant);

    let failed: Arc<Mutex<Option<ai_task_support::StageName>>> =
        Arc::new(Mutex::new(None));
    let failed_for_body = failed.clone();
    let stage_for_body = stage;

    let within_result: Result<
        Result<ai_task_support::Published, PipelineError>,
        lgwks_bot::script::FlowError,
    > = lgwks_bot::script::within(&scope, "pipeline", deadline, async {
        let failed_each = failed_for_body.clone();
        let stage_each = stage_for_body.clone();

        let fetch_outcome: Result<Vec<()>, lgwks_bot::script::FlowError> =
            lgwks_bot::script::each(
                &scope,
                "fetch",
                Some(NonZeroUsize::new(2).unwrap()),
                [
                    ai_task_support::StageName::FetchA,
                    ai_task_support::StageName::FetchB,
                ],
                move |_item_scope, name| {
                    let st = stage_each.clone();
                    let fl = failed_each.clone();
                    async move {
                        match st.run(name.clone()).await {
                            Ok(_) => Ok(()),
                            Err(stage_err) => {
                                if let Ok(mut g) = fl.lock() {
                                    if g.is_none() {
                                        *g = Some(name);
                                    }
                                }
                                Err(Err::<(), _>(stage_err).or_fail().unwrap_err())
                            }
                        }
                    }
                },
            )
            .await;

        match fetch_outcome {
            Ok(_) => {}
            Err(e) => {
                if let Ok(mut g) = failed_for_body.lock() {
                    if let Some(n) = (*g).take() {
                        return Ok(Err(PipelineError::Stage { name: n }));
                    }
                }
                return Err(e);
            }
        }

        if stage_for_body
            .run(ai_task_support::StageName::Combine)
            .await
            .is_err()
        {
            return Ok(Err(PipelineError::Stage {
                name: ai_task_support::StageName::Combine,
            }));
        }

        match stage_for_body
            .run(ai_task_support::StageName::Publish)
            .await
        {
            Ok(art) => {
                let p: ai_task_support::Published = art.into();
                Ok(Ok(p))
            }
            Err(_) => Ok(Err(PipelineError::Stage {
                name: ai_task_support::StageName::Publish,
            })),
        }
    })
    .await;

    match within_result {
        Ok(inner) => inner,
        Err(e) => {
            if e.is_cancelled() {
                Err(PipelineError::Cancelled)
            } else {
                Err(PipelineError::Deadline)
            }
        }
    }
}

use std::sync::{Arc, Mutex};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

async fn collect_total(
    scope: &lgwks_bot::script::Scope,
    world: ai_task_support::recovery::World,
    fail: Arc<Mutex<Option<u32>>>,
) -> Result<u64, lgwks_bot::script::FlowError> {
    let w = world.width();
    let items: Vec<u32> = (0..w).collect();
    let vals = lgwks_bot::script::each(scope, "units", None, items, |s, idx: u32| {
        let world = world.clone();
        let fail = fail.clone();
        async move {
            match world.unit(&s, idx).await {
                Ok(v) => Ok::<u64, lgwks_bot::script::FlowError>(v),
                Err(_) => {
                    if let Ok(mut g) = fail.lock() {
                        *g = Some(idx);
                    }
                    Err(lgwks_bot::script::FlowError::failed(format!("unit:{idx}")))
                }
            }
        }
    })
    .await?;
    Ok(vals.into_iter().sum())
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let host = lgwks_bot::task::Host::builder("recover")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .grants(
            lgwks_bot::gate::GrantSet::empty()
                .grant(lgwks_bot::cap::Cap::new(lgwks_bot::cap::Cap::NET))
                .grant(lgwks_bot::cap::Cap::new(lgwks_bot::cap::Cap::FS))
                .grant(lgwks_bot::cap::Cap::new(lgwks_bot::cap::Cap::SYS))
                .grant(lgwks_bot::cap::Cap::new(lgwks_bot::cap::Cap::NOTIFY)),
        )
        .build()
        .map_err(|_| RecoveryError::NoStore)?;
    let run = lgwks_bot::effect::RunId::from_hex("1234567890abcdef1234567890abcdef")
        .map_err(|_| RecoveryError::NoStore)?;
    let fail: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let wf = world.clone();
    let ff = fail.clone();
    let t = lgwks_bot::task::task("recover", move |scope: lgwks_bot::script::Scope, _input: ()| {
        let w = wf.clone();
        let f = ff.clone();
        async move { collect_total(&scope, w, f).await }
    })
    .map_err(|_| RecoveryError::NoLedger)?;
    let rep = host.resume(run, &t, ()).await;
    match rep.disposition() {
        lgwks_bot::task::Disposition::Succeeded => {
            let total = *rep.output().ok_or(RecoveryError::NoLedger)?;
            let led = world.ledger();
            if !led.applied("recover") {
                led.apply("recover");
            }
            Ok(total)
        }
        lgwks_bot::task::Disposition::DeadlineExceeded | lgwks_bot::task::Disposition::Cancelled => {
            Err(RecoveryError::Deadline)
        }
        lgwks_bot::task::Disposition::Refused => Err(RecoveryError::NoStore),
        lgwks_bot::task::Disposition::Failed => {
            if let Ok(g) = fail.lock() {
                if let Some(idx) = *g {
                    return Err(RecoveryError::Unit { index: idx });
                }
            }
            if let Some(e) = rep.error() {
                if e.is_cancelled() {
                    return Err(RecoveryError::Deadline);
                }
                let dbg = format!("{e:?}");
                if dbg.contains("TimedOut") || dbg.contains("Deadline") || dbg.contains("Cancelled") {
                    return Err(RecoveryError::Deadline);
                }
                if let Some(p) = dbg.find("unit:") {
                    let rest = &dbg[p + 5..];
                    let num: String = rest.chars().take_while(|c| c.is_ascii_digit()).collect();
                    if let Ok(v) = num.parse::<u32>() {
                        return Err(RecoveryError::Unit { index: v });
                    }
                }
            }
            Err(RecoveryError::NoLedger)
        }
        _ => Err(RecoveryError::Deadline),
    }
}

use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, each};
use lgwks_bot::script::ResultExt;
use lgwks_bot::task::Host;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let run_id = RunId::from_hex("11111111111111111111111111111111")
        .map_err(|_| RecoveryError::NoStore)?;

    let host = Host::builder("recovery")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let world_for_task = world.clone();
    let body = move |scope: Scope, _input: ()| {
        let world = world_for_task.clone();
        async move {
            let width = world.width();
            let limit = std::num::NonZeroUsize::new(8).unwrap();
            let world_clone = world.clone();
            let values = each(
                &scope,
                "units",
                Some(limit),
                0..width,
                move |item_scope: Scope, index: u32| {
                    let w = world_clone.clone();
                    async move {
                        match w.unit(&item_scope, index).await {
                            Ok(v) => Ok(v),
                            Err(e) => {
                                let ei = match e {
                                    ai_task_support::recovery::UnitError::Unit { index } => index,
                                    _ => index,
                                };
                                let msg = format!("unit:{ei}");
                                Result::<u64, String>::Err(msg).or_fail()
                            }
                        }
                    }
                },
            )
            .await?;
            let mut total: u64 = 0;
            for v in values {
                total = total.wrapping_add(v);
            }
            Ok(total)
        }
    };

    let task = lgwks_bot::task::task("recover", body).map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run_id, &task, ()).await;

    if report.disposition().is_success() {
        let total = match report.output() {
            Some(v) => *v,
            None => return Err(RecoveryError::NoLedger),
        };
        let ledger = world.ledger();
        if !ledger.applied("recover") {
            ledger.apply("recover");
        }
        Ok(total)
    } else {
        if let Some(e) = report.error() {
            match e {
                FlowError::Failed { reason, .. } => {
                    let s = format!("{reason}");
                    if let Some(pos) = s.find("unit:") {
                        let rest = &s[pos + 5..];
                        let digits: String =
                            rest.chars().take_while(|c| c.is_ascii_digit()).collect();
                        if !digits.is_empty() {
                            if let Ok(idx) = digits.parse::<u32>() {
                                return Err(RecoveryError::Unit { index: idx });
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        Err(RecoveryError::Deadline)
    }
}

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    use std::num::NonZeroUsize;
    use lgwks_bot::effect::RunId;
    use lgwks_bot::script::{FlowError, Scope, Tenant, each, within};
    use lgwks_bot::task::task;

    fn parse_unit_index(msg: &str) -> Option<u32> {
        let pos = msg.find("unit ")?;
        let rest = &msg[pos + 5..];
        let mut num = String::new();
        for c in rest.chars() {
            if c.is_ascii_digit() {
                num.push(c);
            } else {
                break;
            }
        }
        num.parse::<u32>().ok()
    }

    const RUN_HEX: &str = "0123456789abcdef0123456789abcdef";
    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;

    let host = lgwks_bot::task::Host::builder("recovery")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let w0 = world.clone();
    let t = task("recover", move |scope: Scope, _input: ()| {
        let w = w0.clone();
        async move {
            let limit: Option<NonZeroUsize> = NonZeroUsize::new(8);
            let width = w.width();
            let indices: Vec<u32> = (0..width).collect();
            let values: Vec<u64> = each(
                &scope,
                "units",
                limit,
                indices,
                {
                    let w = w.clone();
                    move |step: Scope, index: u32| {
                        let w = w.clone();
                        async move {
                            match w.unit(&step, index).await {
                                Ok(v) => Ok(v),
                                Err(ai_task_support::recovery::UnitError::Unit { index }) => {
                                    Err(FlowError::failed(format!("unit {index}")))
                                }
                                Err(_) => Err(FlowError::failed(format!("unit {index}"))),
                            }
                        }
                    }
                },
            )
            .await?;
            let total: u64 = values.into_iter().sum();
            let ledger = w.ledger();
            let _: String =
                lgwks_bot::script::remember(&scope, "recover-effect", || async move {
                    if !ledger.applied("recover") {
                        ledger.apply("recover");
                    }
                    Ok::<String, FlowError>("done".to_string())
                })
                .await?;
            Ok(total)
        }
    })
    .map_err(|_| RecoveryError::NoLedger)?;

    let scope = Scope::root(Tenant::new("recovery").map_err(|_| RecoveryError::NoStore)?);

    let res: Result<u64, FlowError> = within(&scope, "deadline", deadline, async move {
        let report = host.resume(run, &t, ()).await;
        if report.disposition().is_success() {
            match report.output() {
                Some(v) => Ok(*v),
                None => Err(FlowError::failed("__noledger__")),
            }
        } else if let Some(e) = report.error() {
            let dbg = format!("{e:?}");
            if let Some(idx) = parse_unit_index(&dbg) {
                return Err(FlowError::failed(format!("unit {idx}")));
            }
            if e.is_cancelled() {
                return Err(FlowError::failed("__deadline__"));
            }
            if dbg.contains("TimedOut")
                || dbg.contains("DeadlineExceeded")
                || dbg.contains("Deadline")
                || dbg.contains("Cancelled")
            {
                return Err(FlowError::failed("__deadline__"));
            }
            return Err(FlowError::failed(format!("inner:{dbg}")));
        } else {
            Err(FlowError::failed("__deadline__"))
        }
    })
    .await;

    match res {
        Ok(v) => Ok(v),
        Err(e) => {
            let dbg = format!("{e:?}");
            if dbg.contains("__deadline__") {
                return Err(RecoveryError::Deadline);
            }
            if dbg.contains("__nostore__") {
                return Err(RecoveryError::NoStore);
            }
            if dbg.contains("__noledger__") {
                return Err(RecoveryError::NoLedger);
            }
            if e.is_cancelled() {
                return Err(RecoveryError::Deadline);
            }
            if dbg.contains("TimedOut") || dbg.contains("DeadlineExceeded") {
                return Err(RecoveryError::Deadline);
            }
            if dbg.contains("Cancelled") {
                return Err(RecoveryError::Deadline);
            }
            if let Some(idx) = parse_unit_index(&dbg) {
                return Err(RecoveryError::Unit { index: idx });
            }
            Err(RecoveryError::Deadline)
        }
    }
}

