#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    match lgwks_bot::rt::time::timeout(deadline, run(ids, fetch)).await {
        Ok(r) => r,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: ai_task_support::Fetcher) -> Result<u64, SolveError> {
    let mut it = ids.into_iter();
    let mut set: lgwks_bot::rt::task::JoinSet<(u32, Result<u64, ()>)> =
        lgwks_bot::rt::task::JoinSet::new();
    for _ in 0..4 {
        if let Some(id) = it.next() {
            let f = fetch.clone();
            let _ = set.spawn(async move {
                match f.fetch(id).await {
                    Ok(v) => (id, Ok(v)),
                    Err(_) => (id, Err(())),
                }
            });
        } else {
            break;
        }
    }
    let mut sum: u64 = 0;
    while let Some(res) = set.join_next().await {
        match res {
            Ok((_, Ok(v))) => {
                sum = sum.wrapping_add(v);
                if let Some(nid) = it.next() {
                    let f = fetch.clone();
                    let _ = set.spawn(async move {
                        match f.fetch(nid).await {
                            Ok(v) => (nid, Ok(v)),
                            Err(_) => (nid, Err(())),
                        }
                    });
                }
            }
            Ok((id, Err(()))) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Err(_) => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
        }
    }
    Ok(sum)
}

use lgwks_bot::rt::task::JoinSet;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let inner = async move {
        let mut pending = ids.into_iter();
        let total = pending.len();

        let mut set: JoinSet<Result<u64, u32>> = JoinSet::new();

        for _ in 0..4 {
            match pending.next() {
                Some(id) => {
                    let f = fetch.clone();
                    set.spawn(async move {
                        match f.fetch(id).await {
                            Ok(v) => Ok(v),
                            Err(_) => Err(id),
                        }
                    });
                }
                None => break,
            }
        }

        let mut sum: u64 = 0;
        let mut done: usize = 0;

        while done < total {
            match set.join_next().await {
                None => {
                    set.abort_all();
                    return Err(SolveError::Cancelled);
                }
                Some(Ok(Ok(v))) => {
                    sum = sum.wrapping_add(v);
                    done += 1;
                    match pending.next() {
                        Some(nid) => {
                            let f = fetch.clone();
                            set.spawn(async move {
                                match f.fetch(nid).await {
                                    Ok(v) => Ok(v),
                                    Err(_) => Err(nid),
                                }
                            });
                        }
                        None => {}
                    }
                }
                Some(Ok(Err(fid))) => {
                    set.abort_all();
                    return Err(SolveError::Fetch { id: fid });
                }
                Some(Err(_)) => {
                    set.abort_all();
                    return Err(SolveError::Cancelled);
                }
            }
        }

        Ok(sum)
    };

    match lgwks_bot::rt::time::timeout(deadline, inner).await {
        Ok(r) => r,
        Err(_) => Err(SolveError::Deadline),
    }
}

use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let work = async {
        let mut sum: u64 = 0;
        for chunk in ids.chunks(4) {
            let futs = chunk.iter().copied().map(|id| {
                let f = fetch.clone();
                async move {
                    match f.fetch(id).await {
                        Ok(v) => Ok(v),
                        Err(_) => Err(id),
                    }
                }
            });
            let results: Vec<Result<u64, u32>> = join_all_bounded(4, futs).await;
            for r in results {
                match r {
                    Ok(v) => sum = sum.wrapping_add(v),
                    Err(id) => return Err(SolveError::Fetch { id }),
                }
            }
        }
        Ok(sum)
    };
    match timeout(deadline, work).await {
        Ok(r) => r,
        Err(_) => Err(SolveError::Deadline),
    }
}

