    }
}

async fn run_inner(ids: Vec<u32>, fetch: ai_task_support::Fetcher) -> Result<u64, SolveError> {
    let mut set: JoinSet<Result<u64, u32>> = JoinSet::new();
    let mut iter = ids.into_iter();
    let mut in_flight: usize = 0;
    for _ in 0..4 {
        if let Some(id) = iter.next() {
            let f = fetch.clone();
            set.spawn(async move {
                match f.fetch(id).await {
                    Ok(v) => Ok(v),
                    Err(_) => Err(id),
                }
            });
            in_flight += 1;
        } else {
            break;
        }
    }
    let mut sum: u64 = 0;
    while in_flight > 0 {
        match set.join_next().await {
            None => break,
            Some(Ok(Ok(v))) => {
                sum = sum.wrapping_add(v);
                in_flight -= 1;
                if let Some(id) = iter.next() {
                    let f = fetch.clone();
                    set.spawn(async move {
                        match f.fetch(id).await {
                            Ok(v) => Ok(v),
                            Err(_) => Err(id),
                        }
                    });
                    in_flight += 1;
                }
            }
            Some(Ok(Err(fid))) => {
                set.abort_all();
                return Err(SolveError::Fetch { id: fid });
            }
            Some(Err(_)) => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
        }
    }
    Ok(sum)
}

