#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let target = format!("applied:{key}");
    let line = format!("{target}\n");
    let line_bytes = line.as_bytes().to_vec();
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");

    let did_append: bool = {
        let _ = std::fs::create_dir_all(&effect_dir);
        let cur: Vec<u8> = std::fs::read(&log_path).unwrap_or_default();

        let mut present = false;
        if cur.len() >= line_bytes.len() {
            let mut i = 0usize;
            while i + line_bytes.len() <= cur.len() {
                if &cur[i..i + line_bytes.len()] == &line_bytes[..] {
                    if i == 0 || cur[i - 1] == b'\n' {
                        present = true;
                        break;
                    }
                }
                i += 1;
            }
        }

        if present {
            false
        } else {
            let append_slice: Vec<u8> = if cur.is_empty() || cur.ends_with(b"\n") {
                line_bytes.clone()
            } else {
                let max_k = std::cmp::min(
                    cur.len(),
                    line_bytes.len().saturating_sub(1),
                );
                let mut k: usize = 0;
                let mut cand: usize = 1;
                while cand <= max_k {
                    if &cur[cur.len() - cand..] == &line_bytes[..cand] {
                        k = cand;
                    }
                    cand += 1;
                }
                line_bytes[k..].to_vec()
            };

            if !append_slice.is_empty() {
                let open_res = std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .open(&log_path);
                match open_res {
                    Ok(mut f) => {
                        use std::io::Write as _;
                        let _ = f.write_all(&append_slice);
                        let _ = f.sync_all();
                    }
                    Err(_) => {
                        let _ = std::fs::create_dir_all(&effect_dir);
                        if let Ok(mut f) = std::fs::OpenOptions::new()
                            .create(true)
                            .append(true)
                            .open(&log_path)
                        {
                            use std::io::Write as _;
                            let _ = f.write_all(&append_slice);
                            let _ = f.sync_all();
                        }
                    }
                }
            }
            true
        }
    };

    let wait_res = lgwks_bot::rt::time::timeout(deadline, async {
        loop {
            if release_path.exists() {
                break;
            }
            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(5)).await;
        }
    })
    .await;

    match wait_res {
        Ok(()) => {
            if did_append {
                Ok(format!("applied:{key}"))
            } else {
                Ok(format!("recovered:{key}"))
            }
        }
        Err(_) => Err(RecoverError::Deadline),
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

async fn async_sleep(dur: std::time::Duration) {
    if dur.is_zero() {
        let mut yielded = false;
        std::future::poll_fn(|cx| {
            if yielded {
                std::task::Poll::Ready(())
            } else {
                yielded = true;
                cx.waker().wake_by_ref();
                std::task::Poll::Pending
            }
        })
        .await;
        return;
    }
    let start = std::time::Instant::now();
    let mut spawned = false;
    std::future::poll_fn(|cx| {
        if start.elapsed() >= dur {
            std::task::Poll::Ready(())
        } else {
            if !spawned {
                spawned = true;
                let waker = cx.waker().clone();
                let elapsed = start.elapsed();
                let rem = if elapsed >= dur {
                    std::time::Duration::from_millis(0)
                } else {
                    dur - elapsed
                };
                std::thread::spawn(move || {
                    std::thread::sleep(rem);
                    waker.wake();
                });
            }
            std::task::Poll::Pending
        }
    })
    .await;
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let start = std::time::Instant::now();
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let target_line = format!("applied:{key}");
    let target_bytes = format!("applied:{key}\n");

    loop {
        match std::fs::create_dir_all(&effect_dir) {
            Ok(()) => break,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::AlreadyExists {
                    break;
                }
                if start.elapsed() >= deadline {
                    return Err(RecoverError::Deadline);
                }
                let elapsed = start.elapsed();
                if elapsed >= deadline {
                    return Err(RecoverError::Deadline);
                }
                let remaining = deadline - elapsed;
                let cap = std::time::Duration::from_millis(5);
                let interval = if remaining < cap { remaining } else { cap };
                if interval.is_zero() {
                    return Err(RecoverError::Deadline);
                }
                async_sleep(interval).await;
            }
        }
    }

    let did_append: bool = loop {
        let content_opt: Option<Vec<u8>> = match std::fs::read(&applied_path) {
            Ok(b) => Some(b),
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    None
                } else {
                    if start.elapsed() >= deadline {
                        return Err(RecoverError::Deadline);
                    }
                    let elapsed = start.elapsed();
                    if elapsed >= deadline {
                        return Err(RecoverError::Deadline);
                    }
                    let remaining = deadline - elapsed;
                    let cap = std::time::Duration::from_millis(5);
                    let interval = if remaining < cap { remaining } else { cap };
                    if interval.is_zero() {
                        return Err(RecoverError::Deadline);
                    }
                    async_sleep(interval).await;
                    continue;
                }
            }
        };

        let already: bool = match &content_opt {
            None => false,
            Some(bytes) => {
                let target = target_line.as_bytes();
                let mut found = false;
                for line in bytes.split(|&b| b == b'\n') {
                    let trimmed: &[u8] = if !line.is_empty()
                        && line[line.len() - 1] == b'\r'
                    {
                        &line[..line.len() - 1]
                    } else {
                        line
                    };
                    if trimmed == target {
                        found = true;
                        break;
                    }
                }
                found
            }
        };

        if already {
            break false;
        } else {
            match std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&applied_path)
            {
                Ok(mut f) => {
                    let write_res = {
                        use std::io::Write;
                        f.write_all(target_bytes.as_bytes())
                    };
                    match write_res {
                        Ok(()) => {
                            {
                                use std::io::Write;
                                let _ = f.flush();
                            }
                            let _ = f.sync_all();
                            drop(f);
                            let dir_sync_res = std::fs::File::open(&effect_dir)
                                .and_then(|df| df.sync_all());
                            let _ = dir_sync_res;
                            break true;
                        }
                        Err(_) => {
                            drop(f);
                            if start.elapsed() >= deadline {
                                return Err(RecoverError::Deadline);
                            }
                            let elapsed = start.elapsed();
                            if elapsed >= deadline {
                                return Err(RecoverError::Deadline);
                            }
                            let remaining = deadline - elapsed;
                            let cap = std::time::Duration::from_millis(5);
                            let interval =
                                if remaining < cap { remaining } else { cap };
                            if interval.is_zero() {
                                return Err(RecoverError::Deadline);
                            }
                            async_sleep(interval).await;
                            continue;
                        }
                    }
                }
                Err(_) => {
                    if start.elapsed() >= deadline {
                        return Err(RecoverError::Deadline);
                    }
                    let elapsed = start.elapsed();
                    if elapsed >= deadline {
                        return Err(RecoverError::Deadline);
                    }
                    let remaining = deadline - elapsed;
                    let cap = std::time::Duration::from_millis(5);
                    let interval = if remaining < cap { remaining } else { cap };
                    if interval.is_zero() {
                        return Err(RecoverError::Deadline);
                    }
                    async_sleep(interval).await;
                    continue;
                }
            }
        }
    };

    loop {
        let exists: bool = match std::fs::metadata(&release_path) {
            Ok(_) => true,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    false
                } else {
                    false
                }
            }
        };
        if exists {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let elapsed = start.elapsed();
        if elapsed >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline - elapsed;
        let cap = std::time::Duration::from_millis(10);
        let interval = if remaining < cap { remaining } else { cap };
        if interval.is_zero() {
            return Err(RecoverError::Deadline);
        }
        async_sleep(interval).await;
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

struct SleepFuture {
    end: std::time::Instant,
}

impl std::future::Future for SleepFuture {
    type Output = ();
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Self::Output> {
        let end = self.get_mut().end;
        if std::time::Instant::now() >= end {
            std::task::Poll::Ready(())
        } else {
            let w = cx.waker().clone();
            std::thread::spawn(move || {
                let now = std::time::Instant::now();
                if end > now {
                    std::thread::sleep(end - now);
                }
                w.wake();
            });
            std::task::Poll::Pending
        }
    }
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let needle = format!("applied:{key}");
    let _ = std::fs::create_dir_all(&effect_dir);
    let already = std::fs::read_to_string(&log_path)
        .map(|c| c.lines().any(|l| l == needle))
        .unwrap_or(false);
    let appended = !already;
    if appended {
        if let Ok(mut f) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)
        {
            use std::io::Write as _;
            let line = format!("{needle}\n");
            let _ = f.write_all(line.as_bytes());
            let _ = f.sync_all();
        }
    }
    let start = std::time::Instant::now();
    loop {
        if std::fs::metadata(&release_path).is_ok() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline
            .checked_sub(start.elapsed())
            .unwrap_or(std::time::Duration::from_millis(0));
        let step = if remaining < std::time::Duration::from_millis(10) {
            remaining
        } else {
            std::time::Duration::from_millis(10)
        };
        SleepFuture {
            end: std::time::Instant::now() + step,
        }
        .await;
    }
    if appended {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let expected_line = format!("applied:{key}");
    let expected_full = format!("applied:{key}\n");
    let expected_line_bytes = expected_line.as_bytes();
    let expected_full_bytes = expected_full.as_bytes();

    let log_path = effect_dir.join("applied.log");

    let _ = std::fs::create_dir_all(&effect_dir);

    let contents: Vec<u8> = match std::fs::read(&log_path) {
        Ok(b) => b,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
        Err(_) => {
            let _ = std::fs::create_dir_all(&effect_dir);
            match std::fs::read(&log_path) {
                Ok(b) => b,
                Err(e2) if e2.kind() == std::io::ErrorKind::NotFound => Vec::new(),
                Err(e2) => panic!("read applied.log failed: {e2}"),
            }
        }
    };

    let mut found = false;
    for chunk in contents.split(|&b| b == b'\n') {
        if chunk == expected_line_bytes {
            found = true;
            break;
        }
    }

    let did_append: bool;
    if found {
        if contents.is_empty() {
            did_append = false;
        } else if contents[contents.len() - 1] == b'\n' {
            did_append = false;
        } else {
            let last_nl = contents.iter().rposition(|&b| b == b'\n');
            let start = last_nl.map(|i| i + 1).unwrap_or(0);
            let last_chunk = &contents[start..];
            if last_chunk == expected_line_bytes {
                {
                    use std::io::Write;
                    let f = std::fs::OpenOptions::new()
                        .create(true)
                        .append(true)
                        .open(&log_path)
                        .expect("open log for newline fix");
                    let mut f = f;
                    f.write_all(b"\n").expect("write newline fix");
                    let _ = f.sync_all();
                }
            } else {
                let trunc_len = last_nl.map(|i| i + 1).unwrap_or(0);
                if let Ok(f) = std::fs::OpenOptions::new().write(true).open(&log_path) {
                    let _ = f.set_len(trunc_len as u64);
                    let _ = f.sync_all();
                }
            }
            did_append = false;
        }
    } else {
        if !contents.is_empty() && contents[contents.len() - 1] != b'\n' {
            let trunc_len = contents
                .iter()
                .rposition(|&b| b == b'\n')
                .map(|i| i + 1)
                .unwrap_or(0);
            if let Ok(f) = std::fs::OpenOptions::new().write(true).open(&log_path) {
                let _ = f.set_len(trunc_len as u64);
                let _ = f.sync_all();
            }
        }
        {
            use std::io::Write;
            let f = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&log_path)
                .expect("open log for append");
            let mut f = f;
            f.write_all(expected_full_bytes).expect("append applied line");
            f.sync_all().expect("sync applied line");
        }
        if let Ok(d) = std::fs::File::open(&effect_dir) {
            let _ = d.sync_all();
        }
        did_append = true;
    }

    let release_path = effect_dir.join("release");
    let start = std::time::Instant::now();
    let poll = std::time::Duration::from_millis(5);
    loop {
        if release_path.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline
            .checked_sub(start.elapsed())
            .unwrap_or(std::time::Duration::from_millis(0));
        if remaining.is_zero() {
            return Err(RecoverError::Deadline);
        }
        let wait = if remaining < poll { remaining } else { poll };
        if wait.is_zero() {
            continue;
        }
        lgwks_bot::rt::time::sleep(wait).await;
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

use std::path::PathBuf;
use std::time::Duration;

use lgwks_bot::rt::time::{sleep, timeout};

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

fn apply_once(dir: &std::path::Path, key: &str) -> Result<bool, RecoverError> {
    let _guard = LOCK.lock().unwrap_or_else(|e| e.into_inner());

    if std::fs::create_dir_all(dir).is_err() {
        return Err(RecoverError::Deadline);
    }

    let log_path = dir.join("applied.log");

    let mut data: Vec<u8> = match std::fs::read(&log_path) {
        Ok(d) => d,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
        Err(_) => return Err(RecoverError::Deadline),
    };

    if !data.is_empty() && *data.last().unwrap() != b'\n' {
        if let Some(pos) = data.iter().rposition(|&b| b == b'\n') {
            let new_len = pos + 1;
            data.truncate(new_len);
            if let Ok(f) = std::fs::OpenOptions::new().write(true).open(&log_path) {
                let _ = f.set_len(new_len as u64);
                let _ = f.sync_all();
            }
        } else {
            data.clear();
            if let Ok(f) = std::fs::OpenOptions::new().write(true).open(&log_path) {
                let _ = f.set_len(0);
                let _ = f.sync_all();
            }
        }
    }

    let target = format!("applied:{key}");
    let target_bytes = target.as_bytes();
    let found = data.split(|&b| b == b'\n').any(|line| line == target_bytes);
    if found {
        return Ok(false);
    }

    let line = format!("applied:{key}\n");
    let open_res = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_path);
    let f = match open_res {
        Ok(f) => f,
        Err(_) => return Err(RecoverError::Deadline),
    };
    {
        use std::io::Write;
        let mut f = f;
        if f.write_all(line.as_bytes()).is_err() {
            return Err(RecoverError::Deadline);
        }
        let _ = f.sync_all();
    }
    if let Ok(d) = std::fs::File::open(dir) {
        let _ = d.sync_all();
    }
    Ok(true)
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let did_append = apply_once(&effect_dir, &key)?;

    let release = effect_dir.join("release");
    if release.exists() {
        if did_append {
            return Ok(format!("applied:{key}"));
        } else {
            return Ok(format!("recovered:{key}"));
        }
    }

    let wait = async {
        loop {
            if release.exists() {
                break;
            }
            sleep(Duration::from_millis(5)).await;
        }
    };

    match timeout(deadline, wait).await {
        Ok(()) => {
            if did_append {
                Ok(format!("applied:{key}"))
            } else {
                Ok(format!("recovered:{key}"))
            }
        }
        Err(_) => Err(RecoverError::Deadline),
    }
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    async fn fetch_both(
        stage: &ai_task_support::Stage,
    ) -> Result<(ai_task_support::Artifact, ai_task_support::Artifact), PipelineError> {
        let mut fut_a = Box::pin(stage.run(ai_task_support::StageName::FetchA));
        let mut fut_b = Box::pin(stage.run(ai_task_support::StageName::FetchB));
        let mut a_val: Option<ai_task_support::Artifact> = None;
        let mut b_val: Option<ai_task_support::Artifact> = None;
        std::future::poll_fn(|cx| {
            if a_val.is_none() {
                match std::future::Future::poll(fut_a.as_mut(), cx) {
                    std::task::Poll::Ready(Ok(v)) => {
                        a_val = Some(v);
                    }
                    std::task::Poll::Ready(Err(_)) => {
                        return std::task::Poll::Ready(Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchA,
                        }));
                    }
                    std::task::Poll::Pending => {}
                }
            }
            if b_val.is_none() {
                match std::future::Future::poll(fut_b.as_mut(), cx) {
                    std::task::Poll::Ready(Ok(v)) => {
                        b_val = Some(v);
                    }
                    std::task::Poll::Ready(Err(_)) => {
                        return std::task::Poll::Ready(Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchB,
                        }));
                    }
                    std::task::Poll::Pending => {}
                }
            }
            if a_val.is_some() && b_val.is_some() {
                let a = a_val.take().expect("checked");
                let b = b_val.take().expect("checked");
                std::task::Poll::Ready(Ok((a, b)))
            } else {
                std::task::Poll::Pending
            }
        })
        .await
    }

    let pipeline = async {
        let (_a, _b) = fetch_both(&stage).await?;
        stage
            .run(ai_task_support::StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Combine,
            })?;
        let art = stage
            .run(ai_task_support::StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Publish,
            })?;
        Ok::<_, PipelineError>(ai_task_support::Published::from(art))
    };

    match lgwks_bot::rt::time::timeout(deadline, pipeline).await {
        Ok(res) => res,
        Err(_) => Err(PipelineError::Deadline),
    }
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

async fn fetch_one(
    stage: ai_task_support::Stage,
    name: ai_task_support::StageName,
) -> Result<ai_task_support::Artifact, ai_task_support::StageError> {
    stage.run(name).await
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let pipeline = async move {
        let fut_a = fetch_one(
            stage.clone(),
            ai_task_support::StageName::FetchA,
        );
        let fut_b = fetch_one(
            stage.clone(),
            ai_task_support::StageName::FetchB,
        );
        let mut results = lgwks_bot::rt::task::join_all_bounded(2, [fut_a, fut_b])
            .await
            .into_iter();
        let a_res = match results.next() {
            Some(r) => r,
            None => return Err(PipelineError::Cancelled),
        };
        let b_res = match results.next() {
            Some(r) => r,
            None => return Err(PipelineError::Cancelled),
        };
        drop(results);
        match a_res {
            Ok(_) => {},
            Err(_) => {
                return Err(PipelineError::Stage {
                    name: ai_task_support::StageName::FetchA,
                })
            },
        }
        match b_res {
            Ok(_) => {},
            Err(_) => {
                return Err(PipelineError::Stage {
                    name: ai_task_support::StageName::FetchB,
                })
            },
        }
        let combine_artifact =
            match stage.run(ai_task_support::StageName::Combine).await {
                Ok(a) => a,
                Err(_) => {
                    return Err(PipelineError::Stage {
                        name: ai_task_support::StageName::Combine,
                    })
                },
            };
        drop(combine_artifact);
        match stage.run(ai_task_support::StageName::Publish).await {
            Ok(a) => Ok(ai_task_support::Published::from(a)),
            Err(_) => {
                Err(PipelineError::Stage {
                    name: ai_task_support::StageName::Publish,
                })
            },
        }
    };
    match lgwks_bot::rt::time::timeout(deadline, pipeline).await {
        Ok(inner) => inner,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let work = async move {
        let mut set = JoinSet::new();
        let a_stage = stage.clone();
        let b_stage = stage.clone();
        set.spawn(async move {
            let r = a_stage.run(ai_task_support::StageName::FetchA).await;
            (ai_task_support::StageName::FetchA, r)
        });
        set.spawn(async move {
            let r = b_stage.run(ai_task_support::StageName::FetchB).await;
            (ai_task_support::StageName::FetchB, r)
        });
        for _ in 0..2 {
            match set.join_next().await {
                Some(Ok((_, Ok(_)))) => {}
                Some(Ok((name, Err(_)))) => return Err(PipelineError::Stage { name }),
                Some(Err(_)) => return Err(PipelineError::Cancelled),
                None => return Err(PipelineError::Cancelled),
            }
        }
        drop(set);
        stage
            .run(ai_task_support::StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Combine,
            })?;
        let p = stage
            .run(ai_task_support::StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Publish,
            })?;
        Ok(ai_task_support::Published::from(p))
    };
    match timeout(deadline, work).await {
        Ok(r) => r,
        Err(_) => Err(PipelineError::Deadline),
    }
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

async fn join_pair<F1, F2>(f1: F1, f2: F2) -> (F1::Output, F2::Output)
where
    F1: std::future::Future,
    F2: std::future::Future,
{
    let mut f1 = Box::pin(f1);
    let mut f2 = Box::pin(f2);
    let mut o1: Option<F1::Output> = None;
    let mut o2: Option<F2::Output> = None;
    std::future::poll_fn(|cx| {
        if o1.is_none() {
            if let std::task::Poll::Ready(v) = f1.as_mut().poll(cx) {
                o1 = Some(v);
            }
        }
        if o2.is_none() {
            if let std::task::Poll::Ready(v) = f2.as_mut().poll(cx) {
                o2 = Some(v);
            }
        }
        if o1.is_some() && o2.is_some() {
            std::task::Poll::Ready((o1.take().unwrap(), o2.take().unwrap()))
        } else {
            std::task::Poll::Pending
        }
    })
    .await
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let pipeline = async move {
        let s1 = stage.clone();
        let s2 = stage.clone();
        let fut_a = async move {
            s1.run(ai_task_support::StageName::FetchA)
                .await
                .map_err(|_| ai_task_support::StageName::FetchA)
        };
        let fut_b = async move {
            s2.run(ai_task_support::StageName::FetchB)
                .await
                .map_err(|_| ai_task_support::StageName::FetchB)
        };
        let (res_a, res_b) = join_pair(fut_a, fut_b).await;
        let art_a = match res_a {
            Ok(v) => v,
            Err(name) => return Err(PipelineError::Stage { name }),
        };
        let art_b = match res_b {
            Ok(v) => v,
            Err(name) => return Err(PipelineError::Stage { name }),
        };
        let _ = (&art_a, &art_b);
        stage
            .run(ai_task_support::StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Combine,
            })?;
        let art_p = stage
            .run(ai_task_support::StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Publish,
            })?;
        Ok(art_p.into())
    };
    match lgwks_bot::rt::time::timeout(deadline, pipeline).await {
        Ok(r) => r,
        Err(_) => Err(PipelineError::Deadline),
    }
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
