        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run_inner(
    stage: ai_task_support::Stage,
) -> Result<ai_task_support::Published, PipelineError> {
    let (_a, _b) = run_fetches(&stage).await?;
    stage
        .run(ai_task_support::StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: ai_task_support::StageName::Combine,
        })?;
    let p = stage
        .run(ai_task_support::StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: ai_task_support::StageName::Publish,
        })?;
    Ok(p.into())
}

async fn run_fetches(
    stage: &ai_task_support::Stage,
) -> Result<
    (ai_task_support::Artifact, ai_task_support::Artifact),
    PipelineError,
> {
    let mut set: lgwks_bot::rt::task::JoinSet<(
        ai_task_support::StageName,
        Result<ai_task_support::Artifact, ai_task_support::StageError>,
    )> = lgwks_bot::rt::task::JoinSet::new();
    let s1 = stage.clone();
    let _ = set.spawn(async move {
        let r = s1.run(ai_task_support::StageName::FetchA).await;
        (ai_task_support::StageName::FetchA, r)
    });
    let s2 = stage.clone();
    let _ = set.spawn(async move {
        let r = s2.run(ai_task_support::StageName::FetchB).await;
        (ai_task_support::StageName::FetchB, r)
    });
    let mut a_opt = None;
    let mut b_opt = None;
    for _ in 0..2 {
        match set.join_next().await {
            Some(Ok((name, Ok(art)))) => match name {
                ai_task_support::StageName::FetchA => {
                    a_opt = Some(art);
                }
                ai_task_support::StageName::FetchB => {
                    b_opt = Some(art);
                }
                _ => {}
            },
            Some(Ok((name, Err(_)))) => {
                set.abort_all();
                while set.join_next().await.is_some() {}
                return Err(PipelineError::Stage { name });
            }
            Some(Err(_)) => {
                set.abort_all();
                while set.join_next().await.is_some() {}
                return Err(PipelineError::Cancelled);
            }
            None => break,
        }
    }
    match (a_opt, b_opt) {
        (Some(a), Some(b)) => Ok((a, b)),
        _ => Err(PipelineError::Cancelled),
    }
}

