use lgwks_bot::script::{FlowError, Scope, Tenant, at_most, each, within};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    if deadline.is_zero() {
        return Err(SolveError::Deadline);
    }
    let tenant = match Tenant::new("aggregate") {
        Ok(t) => t,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let limit = match at_most(4) {
        Ok(l) => l,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let body_scope = match scope.enter("work") {
        Ok(s) => s,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let res: Result<Vec<u64>, FlowError> = within(&scope, "deadline", deadline, async move {
        each(
            &body_scope,
            "items",
            Some(limit),
            ids,
            |_scope: Scope, id: u32| {
                let f = fetch.clone();
                async move {
                    f.fetch(id)
                        .await
                        .map_err(|_| FlowError::failed(format!("fetch:{}", id)))
                }
            },
        )
        .await
    })
    .await;
    match res {
        Ok(vals) => Ok(vals.into_iter().fold(0u64, |a, b| a.wrapping_add(b))),
        Err(e) => match e {
            FlowError::Cancelled { .. } => Err(SolveError::Cancelled),
            FlowError::TimedOut { .. } => Err(SolveError::Deadline),
            FlowError::Failed { reason, .. } => {
                if let Some(s) = reason.strip_prefix("fetch:") {
                    if let Ok(id) = s.parse::<u32>() {
                        return Err(SolveError::Fetch { id });
                    }
                }
                Err(SolveError::Cancelled)
            }
            FlowError::Transient { reason, .. } => {
                if let Some(s) = reason.strip_prefix("fetch:") {
                    if let Ok(id) = s.parse::<u32>() {
                        return Err(SolveError::Fetch { id });
                    }
                }
                Err(SolveError::Cancelled)
            }
            _ => Err(SolveError::Cancelled),
        },
    }
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let start = std::time::Instant::now();
    let deadline_dur = deadline;
    let done_flag = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    struct Guard {
        flag: std::sync::Arc<std::sync::atomic::AtomicBool>,
    }
    impl Drop for Guard {
        fn drop(&mut self) {
            self.flag
                .store(true, std::sync::atomic::Ordering::SeqCst);
        }
    }
    let _guard = Guard {
        flag: done_flag.clone(),
    };
    let mut pending: std::collections::VecDeque<u32> = ids.into_iter().collect();
    let mut active = Vec::new();
    let mut sum: u64 = 0;
    let mut timer_started = false;
    let mut fetch_owned = fetch;
    let done_for_timer = done_flag.clone();
    let out: Result<u64, SolveError> = std::future::poll_fn(
        move |cx: &mut std::task::Context<'_>| -> std::task::Poll<Result<u64, SolveError>> {
            if !timer_started {
                timer_started = true;
                let waker = cx.waker().clone();
                let ts = start.clone();
                let dd = deadline_dur;
                let done_c = done_for_timer.clone();
                std::thread::spawn(move || loop {
                    if done_c.load(std::sync::atomic::Ordering::SeqCst) {
                        break;
                    }
                    if ts.elapsed() >= dd {
                        waker.wake();
                        break;
                    }
                    let elapsed = ts.elapsed();
                    let remaining_opt = dd.checked_sub(elapsed);
                    let remaining = match remaining_opt {
                        Some(r) => r,
                        None => {
                            waker.wake();
                            break;
                        }
                    };
                    if remaining == std::time::Duration::from_secs(0) {
                        waker.wake();
                        break;
                    }
                    let chunk = if remaining > std::time::Duration::from_millis(5) {
                        std::time::Duration::from_millis(5)
                    } else {
                        remaining
                    };
                    std::thread::sleep(chunk);
                });
            }
            loop {
                if start.elapsed() >= deadline_dur {
                    return std::task::Poll::Ready(Err(SolveError::Deadline));
                }
                while active.len() < 4 {
                    let next_id: Option<u32> = pending.pop_front();
                    let nid = match next_id {
                        Some(v) => v,
                        None => break,
                    };
                    if start.elapsed() >= deadline_dur {
                        return std::task::Poll::Ready(Err(SolveError::Deadline));
                    }
                    let fc = fetch_owned.clone();
                    let fut = std::boxed::Box::pin(async move {
                        fc.fetch(nid).await.map_err(|_| nid)
                    });
                    active.push((nid, fut));
                }
                if active.is_empty() {
                    return std::task::Poll::Ready(Ok(sum));
                }
                let mut idx: usize = 0;
                let mut made_progress = false;
                let mut failed_id: Option<u32> = None;
                while idx < active.len() {
                    let poll_res = match active.get_mut(idx) {
                        Some((_id, fut)) => {
                            std::future::Future::poll(fut.as_mut(), cx)
                        }
                        None => break,
                    };
                    match poll_res {
                        std::task::Poll::Ready(Ok(v)) => {
                            sum = sum.wrapping_add(v);
                            if idx < active.len() {
                                active.swap_remove(idx);
                            }
                            made_progress = true;
                        }
                        std::task::Poll::Ready(Err(fid)) => {
                            failed_id = Some(fid);
                            break;
                        }
                        std::task::Poll::Pending => {
                            idx = idx.wrapping_add(1);
                        }
                    }
                }
                if let Some(fid) = failed_id {
                    return std::task::Poll::Ready(Err(SolveError::Fetch { id: fid }));
                }
                if made_progress {
                    if pending.is_empty() {
                        if active.is_empty() {
                            continue;
                        } else {
                            return std::task::Poll::Pending;
                        }
                    } else {
                        continue;
                    }
                } else {
                    return std::task::Poll::Pending;
                }
            }
        },
    )
    .await;
    out
}

use std::sync::{Arc, Mutex};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    if deadline.is_zero() {
        return Err(SolveError::Deadline);
    }
    let tenant = match lgwks_bot::script::Tenant::new("solve") {
        Ok(t) => t,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = lgwks_bot::script::Scope::root(tenant);
    let limit = match lgwks_bot::script::at_most(4) {
        Ok(l) => l,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let bad: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let scope2 = scope.clone();
    let bad2 = bad.clone();
    let r = lgwks_bot::script::within(&scope, "deadline", deadline, async move {
        lgwks_bot::script::each(
            &scope2,
            "fetch",
            Some(limit),
            ids,
            move |_, id: u32| {
                let fetch = fetch.clone();
                let bad = bad2.clone();
                async move {
                    match fetch.fetch(id).await {
                        Ok(v) => Ok(v),
                        Err(_) => {
                            if let Ok(mut g) = bad.lock() {
                                if g.is_none() {
                                    *g = Some(id);
                                }
                            }
                            Err(lgwks_bot::script::FlowError::failed("fetch failed"))
                        }
                    }
                }
            },
        )
        .await
    })
    .await;
    match r {
        Ok(v) => Ok(v.into_iter().sum()),
        Err(e) => {
            if e.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            if matches!(&e, lgwks_bot::script::FlowError::TimedOut { .. }) {
                return Err(SolveError::Deadline);
            }
            if let Ok(g) = bad.lock() {
                if let Some(id) = *g {
                    return Err(SolveError::Fetch { id });
                }
            }
            Err(SolveError::Cancelled)
        }
    }
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let fail_id =
        std::sync::Arc::new(std::sync::atomic::AtomicU64::new(u64::MAX));
    let tenant = match lgwks_bot::script::Tenant::new("solve") {
        Ok(t) => t,
        Err(e) => {
            if e.is_cancelled() {
                return Err(SolveError::Cancelled);
            } else {
                return Err(SolveError::Deadline);
            }
        }
    };
    let scope = lgwks_bot::script::Scope::root(tenant);
    let limit = match std::num::NonZeroUsize::new(4) {
        Some(n) => n,
        None => return Err(SolveError::Deadline),
    };
    let fail_for_body = std::sync::Arc::clone(&fail_id);
    let fetch_for_body = fetch;
    let res: Result<Vec<u64>, lgwks_bot::script::FlowError> =
        lgwks_bot::script::within(&scope, "deadline", deadline, async {
            lgwks_bot::script::each(
                &scope,
                "fetch",
                Some(limit),
                ids,
                {
                    let fetch_for_body = fetch_for_body;
                    let fail_for_body = fail_for_body;
                    move |_s: lgwks_bot::script::Scope, id: u32| {
                        let fetch = fetch_for_body.clone();
                        let fail = std::sync::Arc::clone(&fail_for_body);
                        async move {
                            match fetch.fetch(id).await {
                                Ok(v) => Ok(v),
                                Err(_) => {
                                    fail.store(
                                        id as u64,
                                        std::sync::atomic::Ordering::SeqCst,
                                    );
                                    let msg = format!("fetch:{}", id);
                                    Err(
                                        lgwks_bot::script::FlowError::failed(
                                            msg.as_str(),
                                        ),
                                    )
                                }
                            }
                        }
                    }
                },
            )
            .await
        })
        .await;
    match res {
        Ok(vals) => Ok(vals.into_iter().fold(0u64, |a, b| a.wrapping_add(b))),
        Err(e) => {
            if e.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            match e {
                lgwks_bot::script::FlowError::TimedOut { .. } => {
                    Err(SolveError::Deadline)
                }
                lgwks_bot::script::FlowError::Cancelled { .. } => {
                    Err(SolveError::Cancelled)
                }
                _ => {
                    let stored =
                        fail_id.load(std::sync::atomic::Ordering::SeqCst);
                    if stored != u64::MAX {
                        Err(SolveError::Fetch { id: stored as u32 })
                    } else {
                        Err(SolveError::Deadline)
                    }
                }
            }
        }
    }
}

