pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    if deadline.is_zero() {
        return Err(SolveError::Deadline);
    }
    let tenant = match Tenant::new("aggregate") {
        Ok(t) => t,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let max_par: usize = 4;
    let limit = match at_most(max_par) {
        Ok(l) => l,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let each_fut = each(
        &scope,
        "fetches",
        Some(limit),
        ids,
        |item_scope: Scope, id: u32| {
            let _keep = item_scope.path().len();
            let fetcher = fetch.clone();
            async move {
                match fetcher.fetch(id).await {
                    Ok(v) => Ok(v),
                    Err(_) => Err(FlowError::failed(format!("fetch:{}", id))),
                }
            }
        },
    );
    let timed: Result<Vec<u64>, FlowError> =
        within(&scope, "deadline", deadline, each_fut).await;
    match timed {
        Ok(vals) => {
            let mut sum: u64 = 0;
            for v in vals {
                sum = sum.saturating_add(v);
            }
            Ok(sum)
        }
        Err(e) => match e {
            FlowError::TimedOut { .. } => Err(SolveError::Deadline),
            FlowError::Cancelled { .. } => Err(SolveError::Cancelled),
            FlowError::Failed { reason, .. } => match reason.strip_prefix("fetch:") {
                Some(rest) => match rest.parse::<u32>() {
                    Ok(fid) => Err(SolveError::Fetch { id: fid }),
                    Err(_) => Err(SolveError::Cancelled),
                },
                None => Err(SolveError::Cancelled),
            },
            FlowError::Transient { reason, .. } => match reason.strip_prefix("fetch:") {
                Some(rest) => match rest.parse::<u32>() {
                    Ok(fid) => Err(SolveError::Fetch { id: fid }),
                    Err(_) => Err(SolveError::Cancelled),
                },
                None => Err(SolveError::Cancelled),
            },
            _ => Err(SolveError::Cancelled),
        },
    }
}

use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Debug)]
pub enum CaptureError {
    Spawn(String),
    Deadline,
    Cancelled,
}

#[derive(Debug, PartialEq, Eq)]
pub struct CaptureResult {
    head: Vec<u8>,
    total_bytes: u64,
    truncated: bool,
}

impl CaptureResult {
    pub fn new(head: Vec<u8>, total_bytes: u64, truncated: bool) -> Self {
        Self {
            head,
            total_bytes,
            truncated,
        }
    }
    pub fn head(&self) -> &[u8] {
        &self.head
    }
    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }
    pub fn truncated(&self) -> bool {
        self.truncated
    }
}

struct Acc {
    head: Vec<u8>,
    total: u64,
}

fn kill_group(pgid: u32) {
    if pgid == 0 {
        return;
    }
    let script = format!(
        "kill -9 -{} 2>/dev/null; kill -KILL -{} 2>/dev/null; exit 0",
        pgid, pgid
    );
    let _ = std::process::Command::new("sh")
        .arg("-c")
        .arg(script)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
}

struct SleepUntil {
    deadline: Instant,
}

impl std::future::Future for SleepUntil {
    type Output = ();
    fn poll(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<()> {
        let deadline = self.get_mut().deadline;
        let now = Instant::now();
        if now >= deadline {
            return std::task::Poll::Ready(());
        }
        let waker = cx.waker().clone();
        let rem = deadline.saturating_duration_since(now);
        let _ = std::thread::spawn(move || {
            std::thread::sleep(rem);
            waker.wake();
        });
        std::task::Poll::Pending
    }
}

struct Guard {
    child: Option<std::process::Child>,
    pgid: u32,
    disarmed: bool,
}

impl Drop for Guard {
    fn drop(&mut self) {
        if self.disarmed {
            return;
        }
        kill_group(self.pgid);
        if let Some(mut c) = self.child.take() {
            let _ = c.kill();
            let _ = c.wait();
        }
        kill_group(self.pgid);
        std::thread::sleep(Duration::from_millis(20));
        kill_group(self.pgid);
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let program = argv[0].clone();
    let mut cmd = std::process::Command::new(&program);
    for a in argv.iter().skip(1) {
        cmd.arg(a);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        cmd.process_group(0);
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => {
            return Err(CaptureError::Spawn(format!(
                "failed to spawn '{}': {}",
                program, e
            )));
        }
    };
    let pgid = child.id();
    let hl_for_reader = head_limit;
    let acc = Arc::new(Mutex::new(Acc {
        head: Vec::new(),
        total: 0,
    }));
    let acc_cloned = Arc::clone(&acc);
    let stdout_taken = child.stdout.take();
    let reader_handle: Option<std::thread::JoinHandle<()>> = match stdout_taken {
        Some(mut out) => {
            let h = std::thread::spawn(move || {
                use std::io::Read;
                let mut buf = [0u8; 8192];
                loop {
                    match out.read(&mut buf) {
                        Ok(0) => break,
                        Ok(n) => match acc_cloned.lock() {
                            Ok(mut a) => {
                                a.total = a.total.saturating_add(n as u64);
                                if a.head.len() < hl_for_reader {
                                    let remain =
                                        hl_for_reader.saturating_sub(a.head.len());
                                    let take = if n < remain { n } else { remain };
                                    a.head.extend_from_slice(&buf[..take]);
                                }
                            }
                            Err(_) => break,
                        },
                        Err(e) => {
                            if e.kind() == std::io::ErrorKind::Interrupted {
                                continue;
                            } else {
                                break;
                            }
                        }
                    }
                }
            });
            Some(h)
        }
        None => None,
    };

    let mut guard = Guard {
        child: Some(child),
        pgid,
        disarmed: false,
    };

    let start = Instant::now();
    let deadline_instant = match start.checked_add(deadline) {
        Some(t) => t,
        None => start + Duration::from_secs(86400 * 365),
    };

    loop {
        let exited = match guard.child.as_mut() {
            Some(c) => match c.try_wait() {
                Ok(Some(_)) => true,
                Ok(None) => false,
                Err(_) => false,
            },
            None => true,
        };
        if exited {
            break;
        }
        if Instant::now() >= deadline_instant {
            kill_group(pgid);
            if let Some(c) = guard.child.as_mut() {
                let _ = c.kill();
            }
            if let Some(mut c) = guard.child.take() {
                let _ = c.wait();
            }
            kill_group(pgid);
            std::thread::sleep(Duration::from_millis(20));
            kill_group(pgid);
            guard.disarmed = true;
            return Err(CaptureError::Deadline);
        }
        SleepUntil {
            deadline: Instant::now() + Duration::from_millis(5),
        }
        .await;
    }

    let mut handle_opt = reader_handle;
    loop {
        let finished = match handle_opt.as_ref() {
            Some(h) => h.is_finished(),
            None => true,
        };
        if finished {
            break;
        }
        SleepUntil {
            deadline: Instant::now() + Duration::from_millis(5),
        }
        .await;
    }
    if let Some(h) = handle_opt {
        let _ = h.join();
    }

    let (head, total) = match acc.lock() {
        Ok(a) => (a.head.clone(), a.total),
        Err(e) => {
            let a = e.get_ref();
            (a.head.clone(), a.total)
        }
    };
    let truncated = total > head_limit as u64;
    guard.disarmed = true;
    let _ = guard.child.take();
    Ok(CaptureResult::new(head, total, truncated))
}

use std::num::NonZeroUsize;

#[derive(Debug)]
pub enum CaptureError {
    Spawn(String),
    Deadline,
    Cancelled,
}

