pub async fn solve(argv: Vec<String>, head_limit: usize, deadline: std::time::Duration) -> Result<CaptureResult, CaptureError> {
    let mut it = argv.into_iter();
    let prog = match it.next() {
        Some(p) => p,
        None => return Err(CaptureError::Spawn(String::from("empty argv"))),
    };
    let mut spec = lgwks_bot::rt::process::ProcessSpec::new(prog);
    for a in it {
        spec.arg(a);
    }
    if let Some(nz) = NonZeroUsize::new(head_limit) {
        spec.capture_stdout(nz);
    } else if let Some(nz1) = NonZeroUsize::new(1) {
        spec.capture_stdout(nz1);
    }
    spec.deadline(deadline);
    let mut sup: lgwks_bot::rt::supervise::Supervisor = Default::default();
    match sup.run_process(&spec).await {
        Ok(run) => {
            if run.deadline_fired() {
                return Err(CaptureError::Deadline);
            }
            let total = run.stdout().total_bytes();
            let mut h = run.stdout().bytes().to_vec();
            if h.len() > head_limit {
                h.truncate(head_limit);
            }
            let t = total > head_limit as u64;
            Ok(CaptureResult::new(h, total, t))
        }
        Err(e) => {
            let dbg = format!("{:?}", e);
            if dbg.contains("NotStarted") {
                return Err(CaptureError::Spawn(dbg));
            }
            if dbg.contains("Deadline") {
                return Err(CaptureError::Deadline);
            }
            if dbg.contains("TimedOut") {
                return Err(CaptureError::Deadline);
            }
            Err(CaptureError::Cancelled)
        }
    }
}

