struct SleepUntil {
    deadline: Instant,
}

impl Future for SleepUntil {
    type Output = ();
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if Instant::now() >= self.deadline {
            Poll::Ready(())
        } else {
            let remaining = self.deadline.saturating_duration_since(Instant::now());
            let waker = cx.waker().clone();
            std::thread::spawn(move || {
                std::thread::sleep(remaining);
                waker.wake();
            });
            Poll::Pending
        }
    }
}

#[cfg(unix)]
unsafe extern "C" {
    fn killpg(pgid: i32, sig: i32) -> i32;
}

struct ChildGuard {
    child: Option<std::process::Child>,
    pgid: i32,
    reader: Option<std::thread::JoinHandle<(Vec<u8>, u64)>>,
}

impl Drop for ChildGuard {
    fn drop(&mut self) {
        #[cfg(unix)]
        {
            if self.pgid > 0 {
                unsafe {
                    killpg(self.pgid, 9);
                }
            }
        }
        if let Some(mut child) = self.child.take() {
            let _ = child.kill();
            let _ = child.wait();
        }
        if let Some(h) = self.reader.take() {
            let start = Instant::now();
            while !h.is_finished() {
                if start.elapsed() > Duration::from_millis(500) {
                    drop(h);
                    return;
                }
                std::thread::sleep(Duration::from_millis(5));
            }
            let _ = h.join();
        }
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }

    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        cmd.process_group(0);
    }

    let child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };

    let pgid: i32 = child.id() as i32;

    let mut guard = ChildGuard {
        child: Some(child),
        pgid,
        reader: None,
    };

    let stdout_taken: Option<std::process::ChildStdout> = guard
        .child
        .as_mut()
        .and_then(|c| c.stdout.take());

    if let Some(mut out) = stdout_taken {
        let h = std::thread::spawn(move || {
            use std::io::Read;
            let mut head: Vec<u8> = Vec::new();
            let mut total: u64 = 0;
            let mut buf = [0u8; 8192];
            loop {
                match out.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        total = total.wrapping_add(n as u64);
                        if head.len() < head_limit {
                            let need = head_limit - head.len();
                            let take = if need < n { need } else { n };
                            head.extend_from_slice(&buf[..take]);
                        }
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(_) => break,
                }
            }
            (head, total)
        });
        guard.reader = Some(h);
    } else {
        let h = std::thread::spawn(move || (Vec::new(), 0u64));
        guard.reader = Some(h);
    }

    let deadline_instant: Option<Instant> = Instant::now().checked_add(deadline);

    loop {
        let exited: bool = match guard.child.as_mut().map(|c| c.try_wait()) {
            Some(Ok(Some(_))) => true,
            Some(Ok(None)) => false,
            Some(Err(_)) => true,
            None => true,
        };
        if exited {
            break;
        }
        if let Some(d) = deadline_instant {
            if Instant::now() >= d {
                return Err(CaptureError::Deadline);
            }
        }
        let sleep_dur: Duration = if let Some(d) = deadline_instant {
            let remaining = d.saturating_duration_since(Instant::now());
            std::cmp::min(remaining, Duration::from_millis(10))
        } else {
            Duration::from_millis(10)
        };
        if sleep_dur.is_zero() {
            SleepUntil {
                deadline: Instant::now(),
            }
            .await;
        } else {
            let until = Instant::now()
                .checked_add(sleep_dur)
                .unwrap_or_else(|| Instant::now() + Duration::from_millis(10));
            SleepUntil { deadline: until }.await;
        }
    }

    #[cfg(unix)]
    {
        if guard.pgid > 0 {
            unsafe {
                killpg(guard.pgid, 9);
            }
        }
    }

    loop {
        let finished = guard
            .reader
            .as_ref()
            .map(|h| h.is_finished())
            .unwrap_or(true);
        if finished {
            break;
        }
        if let Some(d) = deadline_instant {
            if Instant::now() >= d {
                return Err(CaptureError::Deadline);
            }
        }
        SleepUntil {
            deadline: Instant::now() + Duration::from_millis(5),
        }
        .await;
    }

    let handle_opt = guard.reader.take();
    let (head, total): (Vec<u8>, u64) = if let Some(h) = handle_opt {
        match h.join() {
            Ok(v) => v,
            Err(_) => (Vec::new(), 0),
        }
    } else {
        (Vec::new(), 0)
    };

    let truncated: bool = total > head_limit as u64;
    let mut head_trunc = head;
    if head_trunc.len() > head_limit {
        head_trunc.truncate(head_limit);
    }
    Ok(CaptureResult::new(head_trunc, total, truncated))
}

