pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn(String::from("empty argv")));
    }
    if deadline.is_zero() {
        return Err(CaptureError::Deadline);
    }
    let program = match argv.first() {
        Some(v) => v.clone(),
        None => return Err(CaptureError::Spawn(String::from("empty argv"))),
    };
    let mut spec = lgwks_bot::rt::process::ProcessSpec::new(program.as_str());
    for arg in argv.iter().skip(1) {
        spec.arg(arg.as_str());
    }
    let keep = match NonZeroUsize::new(head_limit) {
        Some(v) => v,
        None => NonZeroUsize::MIN,
    };
    spec.capture_stdout(keep);
    spec.capture_stderr(NonZeroUsize::MIN);
    spec.deadline(deadline);
    let mut supervisor = lgwks_bot::rt::supervise::Supervisor::new(1);
    let run_result = supervisor.run_process(&spec).await;
    let run = match run_result {
        Ok(v) => v,
        Err(e) => {
            let dbg = format!("{e:?}");
            if dbg.contains("NotStarted") {
                return Err(CaptureError::Spawn(dbg));
            }
            if dbg.contains("Refused") {
                return Err(CaptureError::Cancelled);
            }
            let lower = dbg.to_ascii_lowercase();
            if lower.contains("deadline") {
                return Err(CaptureError::Deadline);
            }
            return Err(CaptureError::Cancelled);
        }
    };
    if run.deadline_fired() {
        return Err(CaptureError::Deadline);
    }
    let total = run.stdout().total_bytes();
    let mut head_vec = run.stdout().bytes().to_vec();
    head_vec.truncate(head_limit);
    let is_truncated = total > head_limit as u64;
    Ok(CaptureResult::new(head_vec, total, is_truncated))
}

