pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let did_append = apply_once(&effect_dir, &key)?;
    let release_path = effect_dir.join("release");
    let start = std::time::Instant::now();
    loop {
        if std::fs::metadata(&release_path).is_ok() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let elapsed = start.elapsed();
        let remaining = match deadline.checked_sub(elapsed) {
            Some(r) => r,
            None => std::time::Duration::ZERO,
        };
        let interval = std::time::Duration::from_millis(5);
        let sleep_for = if remaining < interval {
            remaining
        } else {
            interval
        };
        if !sleep_for.is_zero() {
            std::thread::sleep(sleep_for);
        }
        yield_once().await;
    }
    if did_append {
        Ok(format!("applied:{}", key))
    } else {
        Ok(format!("recovered:{}", key))
    }
}

struct LockGuard<'a> {
    path: &'a std::path::Path,
}

impl<'a> Drop for LockGuard<'a> {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(self.path);
    }
}

fn line_present(content: &[u8], key: &str) -> bool {
    let needle = format!("applied:{}", key);
    let needle_bytes = needle.as_bytes();
    for part in content.split(|b| *b == b'\n') {
        let mut p = part;
        if !p.is_empty() {
            let last = p.len() - 1;
            if p[last] == b'\r' {
                p = &p[..last];
            }
        }
        if p == needle_bytes {
            return true;
        }
    }
    false
}

fn acquire_lock(lock_path: &std::path::Path) {
    loop {
        match std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(lock_path)
        {
            Ok(_) => {
                return;
            }
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                let is_stale = match std::fs::metadata(lock_path) {
                    Ok(meta) => match meta.modified() {
                        Ok(m) => match m.elapsed() {
                            Ok(el) => el > std::time::Duration::from_secs(2),
                            Err(_) => false,
                        },
                        Err(_) => false,
                    },
                    Err(_) => false,
                };
                if is_stale {
                    let _ = std::fs::remove_file(lock_path);
                    continue;
                }
                std::thread::sleep(std::time::Duration::from_millis(5));
            }
            Err(_) => {
                if let Some(parent) = lock_path.parent() {
                    let _ = std::fs::create_dir_all(parent);
                }
                std::thread::sleep(std::time::Duration::from_millis(5));
            }
        }
    }
}

async fn yield_once() {
    let mut first = true;
    std::future::poll_fn(move |cx: &mut std::task::Context<'_>| {
        if first {
            first = false;
            cx.waker().wake_by_ref();
            std::task::Poll::Pending
        } else {
            std::task::Poll::Ready(())
        }
    })
    .await
}

fn apply_once(effect_dir: &std::path::Path, key: &str) -> Result<bool, RecoverError> {
    let applied_path = effect_dir.join("applied.log");
    let lock_path = effect_dir.join(".applied.lock");
    if std::fs::create_dir_all(effect_dir).is_err() {
        match std::fs::metadata(effect_dir) {
            Ok(m) if m.is_dir() => {}
            _ => {
                return Err(RecoverError::Deadline);
            }
        }
    }
    acquire_lock(&lock_path);
    let _guard = LockGuard { path: &lock_path };
    let present = match std::fs::read(&applied_path) {
        Ok(bytes) => line_present(&bytes, key),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => {
            return Err(RecoverError::Deadline);
        }
    };
    if present {
        return Ok(false);
    }
    let line = format!("applied:{}\n", key);
    match std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&applied_path)
    {
        Ok(mut f) => {
            if std::io::Write::write_all(&mut f, line.as_bytes()).is_err() {
                return Err(RecoverError::Deadline);
            }
            let _ = f.sync_all();
            Ok(true)
        }
        Err(_) => Err(RecoverError::Deadline),
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    struct YieldOnce {
        yielded: bool,
    }
    impl std::future::Future for YieldOnce {
        type Output = ();
        fn poll(
            mut self: std::pin::Pin<&mut Self>,
            cx: &mut std::task::Context<'_>,
        ) -> std::task::Poll<()> {
            if self.yielded {
                std::task::Poll::Ready(())
            } else {
                self.yielded = true;
                cx.waker().wake_by_ref();
                std::task::Poll::Pending
            }
        }
    }
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let target_text = format!("applied:{}", key);
    let target_bytes = target_text.into_bytes();
    match std::fs::create_dir_all(&effect_dir) {
        Ok(()) => {},
        Err(_) => {
            return Err(RecoverError::Deadline);
        }
    }
    let already_present: bool = match std::fs::read(&applied_path) {
        Ok(bytes) => {
            let mut found = false;
            for chunk in bytes.split(|b| *b == b'\n') {
                if chunk == target_bytes.as_slice() {
                    found = true;
                    break;
                }
            }
            found
        },
        Err(e) => match e.kind() {
            std::io::ErrorKind::NotFound => false,
            _ => {
                return Err(RecoverError::Deadline);
            }
        },
    };
    let did_append: bool = if already_present {
        false
    } else {
        let line_text = format!("applied:{}\n", key);
        let line_bytes = line_text.into_bytes();
        match std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&applied_path)
        {
            Ok(mut file) => {
                use std::io::Write;
                match file.write_all(line_bytes.as_slice()) {
                    Ok(()) => {
                        match file.sync_all() {
                            Ok(()) => {},
                            Err(_) => {},
                        }
                        drop(file);
                        drop(line_bytes);
                        true
                    },
                    Err(_) => {
                        drop(file);
                        drop(line_bytes);
                        return Err(RecoverError::Deadline);
                    }
                }
            },
            Err(_) => {
                drop(line_bytes);
                return Err(RecoverError::Deadline);
            }
        }
    };
    drop(target_bytes);
    let start = std::time::Instant::now();
    for _ in 0..u64::MAX {
        let exists: bool = match std::fs::metadata(&release_path) {
            Ok(_) => true,
            Err(e) => match e.kind() {
                std::io::ErrorKind::NotFound => false,
                _ => false,
            },
        };
        if exists {
            if did_append {
                return Ok(format!("applied:{}", key));
            } else {
                return Ok(format!("recovered:{}", key));
            }
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        YieldOnce { yielded: false }.await;
    }
    return Err(RecoverError::Deadline);
}

