async fn nap(d: std::time::Duration) {
    if d.is_zero() {
        return;
    }
    let dl = std::time::Instant::now() + d;
    std::future::poll_fn(|cx| {
        if std::time::Instant::now() >= dl {
            std::task::Poll::Ready(())
        } else {
            let w = cx.waker().clone();
            let rem = dl.saturating_duration_since(std::time::Instant::now());
            std::thread::spawn(move || {
                std::thread::sleep(rem);
                w.wake();
            });
            std::task::Poll::Pending
        }
    })
    .await
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let log = effect_dir.join("applied.log");
    let release = effect_dir.join("release");
    let _ = std::fs::create_dir_all(&effect_dir);
    let needle = format!("applied:{key}");
    let line = format!("{needle}\n");
    let already = std::fs::read_to_string(&log)
        .map(|c| c.lines().any(|l| l == needle))
        .unwrap_or(false);
    let appended = if already {
        false
    } else {
        {
            use std::io::Write;
            if let Ok(mut f) = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&log)
            {
                let _ = f.write_all(line.as_bytes());
                let _ = f.flush();
                let _ = f.sync_all();
            }
        }
        true
    };
    let start = std::time::Instant::now();
    loop {
        if release.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        nap(std::time::Duration::from_millis(5)).await;
    }
    if appended {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

