fn check_and_append(applied_path: &std::path::Path, key: &str) -> std::io::Result<bool> {
    let target = format!("applied:{key}");
    match std::fs::read(applied_path) {
        Ok(bytes) => {
            let text = String::from_utf8_lossy(&bytes);
            for line in text.lines() {
                if line == target {
                    return Ok(false);
                }
            }
        }
        Err(e) => {
            if e.kind() != std::io::ErrorKind::NotFound {
                return Err(e);
            }
        }
    }
    {
        use std::io::Write;
        let mut f = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(applied_path)?;
        f.write_all(target.as_bytes())?;
        f.write_all(b"\n")?;
        f.flush()?;
        let _ = f.sync_all();
    }
    Ok(true)
}

async fn sleep_step(dur: std::time::Duration) {
    if dur == std::time::Duration::ZERO {
        return;
    }
    let mut started = false;
    std::future::poll_fn(move |cx: &mut std::task::Context<'_>| {
        if started {
            std::task::Poll::Ready(())
        } else {
            started = true;
            let waker = cx.waker().clone();
            let d = dur;
            let _ = std::thread::spawn(move || {
                std::thread::sleep(d);
                waker.wake();
            });
            std::task::Poll::Pending
        }
    })
    .await;
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let _ = std::fs::create_dir_all(&effect_dir);
    let did_append = match check_and_append(&applied_path, &key) {
        Ok(v) => v,
        Err(_) => return Err(RecoverError::Deadline),
    };
    let start = std::time::Instant::now();
    loop {
        if std::fs::metadata(&release_path).is_ok() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let elapsed = start.elapsed();
        let remaining = match deadline.checked_sub(elapsed) {
            Some(r) => r,
            None => return Err(RecoverError::Deadline),
        };
        if remaining == std::time::Duration::ZERO {
            return Err(RecoverError::Deadline);
        }
        let step = if remaining < std::time::Duration::from_millis(10) {
            remaining
        } else {
            std::time::Duration::from_millis(10)
        };
        sleep_step(step).await;
    }
    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

use std::path::PathBuf;
use std::time::Duration;

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    // Create effect dir (and parents) if missing.
    // Ignore errors? Try to create; if fails, we still try to proceed.
    let _ = std::fs::create_dir_all(&effect_dir);
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let line = format!("applied:{}\n", key);
    let target = format!("applied:{}", key);

    // Check whether already applied.
    let already: bool = match std::fs::read_to_string(&applied_path) {
        Ok(contents) => contents.lines().any(|l| l == target),
        Err(_) => false,
    };

    let appended: bool = if already {
        false
    } else {
        // Append exactly one line.
        use std::io::Write;
        match std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&applied_path)
        {
            Ok(mut f) => {
                // If write fails, we cannot tell: per contract must not return Unknown.
                // Re-read the log to reconcile: if line present, treat as applied/recovered,
                // else... still must not return Unknown. Best effort: check again.
                if f.write_all(line.as_bytes()).is_err() {
                    // Fall through to reconcile from log.
                } else {
                    let _ = f.flush();
                    // Ensure durability so SIGKILL after append is still visible.
                    let _ = f.sync_all();
                    return wait_release(&release_path, &key, true, deadline).await;
                }
                // Reconcile after failed write.
                match std::fs::read_to_string(&applied_path) {
                    Ok(contents) => {
                        if contents.lines().any(|l| l == target) {
                            return wait_release(&release_path, &key, false, deadline).await;
                        } else {
                            // Could not confirm; contract says never Unknown.
                            // Try once more to append? No - to avoid duplicates, treat as recovered check again.
                            // If still missing, we must choose: attempt append again via reopen?
                            // Simplest: report recovered only if present, else claim applied (we attempted).
                            // But to satisfy "exactly once", re-check once more after sync attempt.
                            return wait_release(&release_path, &key, true, deadline).await;
                        }
                    }
                    Err(_) => {
                        return wait_release(&release_path, &key, true, deadline).await;
                    }
                }
            }
            Err(_) => {
                // Could not open: reconcile from log if possible.
                match std::fs::read_to_string(&applied_path) {
                    Ok(contents) => {
                        if contents.lines().any(|l| l == target) {
                            return wait_release(&release_path, &key, false, deadline).await;
                        }
                    }
                    Err(_) => {}
                }
                // If we cannot append nor find, still must not return Unknown.
                // Wait for release then claim recovered if line appears, else applied?
                // To avoid Unknown, check once more after wait.
                match wait_release(&release_path, &key, false, deadline).await {
                    Ok(s) => return Ok(s),
                    Err(e) => return Err(e),
                }
            }
        }
    };

    if appended {
        wait_release(&release_path, &key, true, deadline).await
    } else {
        wait_release(&release_path, &key, false, deadline).await
    }
}

async fn wait_release(
    release_path: &std::path::PathBuf,
    key: &str,
    appended: bool,
    deadline: Duration,
) -> Result<String, RecoverError> {
    let start = std::time::Instant::now();
    // Poll with bounded wait.
    loop {
        if release_path.exists() {
            if appended {
                return Ok(format!("applied:{}", key));
            } else {
                return Ok(format!("recovered:{}", key));
            }
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        // Bounded sleep: small poll interval, capped by remaining time.
        let remaining = deadline.saturating_sub(start.elapsed());
        // Poll every 5ms, but not beyond remaining.
        let step = std::cmp::min(remaining, Duration::from_millis(5));
        // Avoid zero-duration sleep which could spin; ensure at least 1ms if remaining > 0.
        let step = if step.is_zero() {
            return Err(RecoverError::Deadline);
        } else {
            step
        };
        std::thread::sleep(Duration::from_millis(1).min(step));
        // Yield to async runtime.
        tokio_yield().await;
    }
}

// Minimal async yield without external crates: use std only.
// We cannot use tokio; so implement yield via a tiny future that returns Pending once.
async fn tokio_yield() {
    struct Yield {
        yielded: bool,
    }
    impl std::future::Future for Yield {
        type Output = ();
        fn poll(
            mut self: std::pin::Pin<&mut Self>,
            cx: &mut std::task::Context<'_>,
        ) -> std::task::Poll<()> {
            if self.yielded {
                std::task::Poll::Ready(())
            } else {
                self.yielded = true;
                cx.waker().wake_by_ref();
                std::task::Poll::Pending
            }
        }
    }
    Yield { yielded: false }.await
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::Instant;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

struct JoinFetch<F1, F2> {
    f1: Option<Pin<Box<F1>>>,
    f2: Option<Pin<Box<F2>>>,
    a_done: Option<ai_task_support::Artifact>,
    b_done: Option<ai_task_support::Artifact>,
}

impl<F1, F2> JoinFetch<F1, F2> {
    fn new(f1: F1, f2: F2) -> Self {
        Self {
            f1: Some(Box::pin(f1)),
            f2: Some(Box::pin(f2)),
            a_done: None,
            b_done: None,
        }
    }
}

impl<F1, F2> Drop for JoinFetch<F1, F2> {
    fn drop(&mut self) {
        self.f1 = None;
        self.f2 = None;
        self.a_done = None;
        self.b_done = None;
    }
}

impl<F1, F2> Future for JoinFetch<F1, F2>
where
    F1: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
    F2: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
{
    type Output = Result<(ai_task_support::Artifact, ai_task_support::Artifact), PipelineError>;
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        if this.a_done.is_none() {
            if this.f1.is_some() {
                let pr: Option<Result<ai_task_support::Artifact, ai_task_support::StageError>> =
                    match this.f1.as_mut() {
                        Some(p) => match p.as_mut().poll(cx) {
                            Poll::Ready(v) => Some(v),
                            Poll::Pending => None,
                        },
                        None => None,
                    };
                match pr {
                    Some(Ok(a)) => {
                        this.a_done = Some(a);
                        this.f1 = None;
                    }
                    Some(Err(_)) => {
                        this.f1 = None;
                        this.f2 = None;
                        this.a_done = None;
                        this.b_done = None;
                        return Poll::Ready(Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchA,
                        }));
                    }
                    None => {}
                }
            }
        }
        if this.b_done.is_none() {
            if this.f2.is_some() {
                let pr: Option<Result<ai_task_support::Artifact, ai_task_support::StageError>> =
                    match this.f2.as_mut() {
                        Some(p) => match p.as_mut().poll(cx) {
                            Poll::Ready(v) => Some(v),
                            Poll::Pending => None,
                        },
                        None => None,
                    };
                match pr {
                    Some(Ok(b)) => {
                        this.b_done = Some(b);
                        this.f2 = None;
                    }
                    Some(Err(_)) => {
                        this.f1 = None;
                        this.f2 = None;
                        this.a_done = None;
                        this.b_done = None;
                        return Poll::Ready(Err(PipelineError::Stage {
                            name: ai_task_support::StageName::FetchB,
                        }));
                    }
                    None => {}
                }
            }
        }
        if this.a_done.is_some() {
            if this.b_done.is_some() {
                let a_opt = this.a_done.take();
                let b_opt = this.b_done.take();
                this.f1 = None;
                this.f2 = None;
                match (a_opt, b_opt) {
                    (Some(a), Some(b)) => {
                        return Poll::Ready(Ok((a, b)));
                    }
                    _ => {
                        return Poll::Pending;
                    }
                }
            }
        }
        Poll::Pending
    }
}

struct Timeout<F> {
    inner: Option<Pin<Box<F>>>,
    deadline: Instant,
    shared: Arc<Mutex<Option<Waker>>>,
    timer_started: bool,
}

impl<F> Timeout<F> {
    fn new(inner: F, deadline: Instant) -> Self {
        Self {
            inner: Some(Box::pin(inner)),
            deadline,
            shared: Arc::new(Mutex::new(None)),
            timer_started: false,
        }
    }
}

impl<F> Drop for Timeout<F> {
    fn drop(&mut self) {
        self.inner = None;
        match self.shared.lock() {
            Ok(mut g) => {
                *g = None;
            }
            Err(e) => {
                let mut g = e.into_inner();
                *g = None;
            }
        }
    }
}

impl<F> Future for Timeout<F>
where
    F: Future,
{
    type Output = Result<F::Output, PipelineError>;
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        match this.inner.as_mut() {
            Some(p) => match p.as_mut().poll(cx) {
                Poll::Ready(v) => {
                    this.inner = None;
                    match this.shared.lock() {
                        Ok(mut g) => {
                            *g = None;
                        }
                        Err(e) => {
                            let mut g = e.into_inner();
                            *g = None;
                        }
                    }
                    return Poll::Ready(Ok(v));
                }
                Poll::Pending => {}
            },
            None => {
                return Poll::Pending;
            }
        }
        if Instant::now() >= this.deadline {
            this.inner = None;
            match this.shared.lock() {
                Ok(mut g) => {
                    *g = None;
                }
                Err(e) => {
                    let mut g = e.into_inner();
                    *g = None;
                }
            }
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match this.shared.lock() {
            Ok(mut g) => {
                *g = Some(cx.waker().clone());
            }
            Err(e) => {
                let mut g = e.into_inner();
                *g = Some(cx.waker().clone());
            }
        }
        if this.timer_started == false {
            this.timer_started = true;
            let shared = Arc::clone(&this.shared);
            let dl = this.deadline;
            let builder = std::thread::Builder::new();
            match builder.spawn(move || {
                let cur = Instant::now();
                if cur < dl {
                    let rem = dl.saturating_duration_since(cur);
                    std::thread::sleep(rem);
                }
                let to_wake: Option<Waker> = match shared.lock() {
                    Ok(mut g) => g.take(),
                    Err(e) => {
                        let mut g = e.into_inner();
                        g.take()
                    }
                };
                match to_wake {
                    Some(w) => {
                        w.wake();
                    }
                    None => {}
                }
                drop(shared);
            }) {
                Ok(h) => {
                    drop(h);
                }
                Err(_) => {}
            }
        }
        Poll::Pending
    }
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let start = Instant::now();
    let deadline_instant: Option<Instant> = start.checked_add(deadline);
    match deadline_instant {
        Some(dl) => {
            if Instant::now() >= dl {
                drop(stage);
                return Err(PipelineError::Deadline);
            }
        }
        None => {}
    }
    let fetch_outcome: Result<
        (ai_task_support::Artifact, ai_task_support::Artifact),
        PipelineError,
    > = {
        let fut_a = stage.run(ai_task_support::StageName::FetchA);
        let fut_b = stage.run(ai_task_support::StageName::FetchB);
        let join = JoinFetch::new(fut_a, fut_b);
        match deadline_instant {
            Some(dl) => {
                let t = Timeout::new(join, dl);
                match t.await {
                    Ok(v) => v,
                    Err(e) => Err(e),
                }
            }
            None => join.await,
        }
    };
    let pair = match fetch_outcome {
        Ok(v) => v,
        Err(e) => {
            drop(stage);
            return Err(e);
        }
    };
    drop(pair.0);
    drop(pair.1);
    match deadline_instant {
        Some(dl) => {
            if Instant::now() >= dl {
                drop(stage);
                return Err(PipelineError::Deadline);
            }
        }
        None => {}
    }
    let combine_outcome: Result<ai_task_support::Artifact, PipelineError> = {
        let fut_c = stage.run(ai_task_support::StageName::Combine);
        match deadline_instant {
            Some(dl) => {
                let t = Timeout::new(fut_c, dl);
                match t.await {
                    Ok(Ok(a)) => Ok(a),
                    Ok(Err(_)) => Err(PipelineError::Stage {
                        name: ai_task_support::StageName::Combine,
                    }),
                    Err(e) => Err(e),
                }
            }
            None => match fut_c.await {
                Ok(a) => Ok(a),
                Err(_) => Err(PipelineError::Stage {
                    name: ai_task_support::StageName::Combine,
                }),
            },
        }
    };
    match combine_outcome {
        Ok(a) => {
            drop(a);
        }
        Err(e) => {
            drop(stage);
            return Err(e);
        }
    }
    match deadline_instant {
        Some(dl) => {
            if Instant::now() >= dl {
                drop(stage);
                return Err(PipelineError::Deadline);
            }
        }
        None => {}
    }
    let publish_outcome: Result<ai_task_support::Artifact, PipelineError> = {
        let fut_p = stage.run(ai_task_support::StageName::Publish);
        match deadline_instant {
            Some(dl) => {
                let t = Timeout::new(fut_p, dl);
                match t.await {
                    Ok(Ok(a)) => Ok(a),
                    Ok(Err(_)) => Err(PipelineError::Stage {
                        name: ai_task_support::StageName::Publish,
                    }),
                    Err(e) => Err(e),
                }
            }
            None => match fut_p.await {
                Ok(a) => Ok(a),
                Err(_) => Err(PipelineError::Stage {
                    name: ai_task_support::StageName::Publish,
                }),
            },
        }
    };
    match publish_outcome {
        Ok(a) => {
            let p: ai_task_support::Published = a.into();
            drop(stage);
            Ok(p)
        }
        Err(e) => {
            drop(stage);
            Err(e)
        }
    }
}

use std::future::poll_fn;
use std::task::Poll;
use std::time::Instant;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

fn copy_name(n: &ai_task_support::StageName) -> ai_task_support::StageName {
    match n {
        ai_task_support::StageName::FetchA => ai_task_support::StageName::FetchA,
        ai_task_support::StageName::FetchB => ai_task_support::StageName::FetchB,
        ai_task_support::StageName::Combine => ai_task_support::StageName::Combine,
        ai_task_support::StageName::Publish => ai_task_support::StageName::Publish,
    }
}

fn spawn_wake(w: std::task::Waker, deadline: Instant) {
    let rem = deadline.saturating_duration_since(Instant::now());
    std::thread::spawn(move || {
        std::thread::sleep(rem);
        w.wake();
    });
}

async fn fetch_both(
    stage: &ai_task_support::Stage,
    deadline: Instant,
) -> Result<
    (ai_task_support::Artifact, ai_task_support::Artifact),
    PipelineError,
> {
    let mut fa = Box::pin(stage.run(ai_task_support::StageName::FetchA));
    let mut fb = Box::pin(stage.run(ai_task_support::StageName::FetchB));
    let mut a_val: Option<ai_task_support::Artifact> = None;
    let mut b_val: Option<ai_task_support::Artifact> = None;
    let mut timer_started = false;
    poll_fn(|cx| {
        if Instant::now() >= deadline {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if a_val.is_none() {
            match fa.as_mut().poll(cx) {
                Poll::Ready(Ok(v)) => {
                    a_val = Some(v);
                }
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: ai_task_support::StageName::FetchA,
                    }));
                }
                Poll::Pending => {}
            }
        }
        if b_val.is_none() {
            match fb.as_mut().poll(cx) {
                Poll::Ready(Ok(v)) => {
                    b_val = Some(v);
                }
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: ai_task_support::StageName::FetchB,
                    }));
                }
                Poll::Pending => {}
            }
        }
        if a_val.is_some() && b_val.is_some() {
            let a = a_val.take().unwrap();
            let b = b_val.take().unwrap();
            return Poll::Ready(Ok((a, b)));
        }
        if !timer_started {
            timer_started = true;
            spawn_wake(cx.waker().clone(), deadline);
        }
        Poll::Pending
    })
    .await
}

async fn run_one(
    stage: &ai_task_support::Stage,
    name: ai_task_support::StageName,
    deadline: Instant,
) -> Result<ai_task_support::Artifact, PipelineError> {
    let mut fut = Box::pin(stage.run(copy_name(&name)));
    let mut timer_started = false;
    poll_fn(|cx| {
        if Instant::now() >= deadline {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match fut.as_mut().poll(cx) {
            Poll::Ready(Ok(v)) => Poll::Ready(Ok(v)),
            Poll::Ready(Err(_)) => Poll::Ready(Err(PipelineError::Stage {
                name: copy_name(&name),
            })),
            Poll::Pending => {
                if !timer_started {
                    timer_started = true;
                    spawn_wake(cx.waker().clone(), deadline);
                }
                Poll::Pending
            }
        }
    })
    .await
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let dl = Instant::now() + deadline;
    let (_a, _b) = fetch_both(&stage, dl).await?;
    let _c = run_one(&stage, ai_task_support::StageName::Combine, dl).await?;
    let p = run_one(&stage, ai_task_support::StageName::Publish, dl).await?;
    Ok(p.into())
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

struct Guard {
    flag: std::sync::Arc<std::sync::atomic::AtomicBool>,
}

impl Drop for Guard {
    fn drop(&mut self) {
        self.flag
            .store(true, std::sync::atomic::Ordering::Relaxed);
    }
}

async fn fetch_both(
    stage: &ai_task_support::Stage,
    deadline: Option<std::time::Instant>,
) -> Result<
    (
        ai_task_support::Artifact,
        ai_task_support::Artifact,
    ),
    PipelineError,
> {
    let done = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let _guard = Guard { flag: done.clone() };
    let mut fut_a =
        std::boxed::Box::pin(stage.run(ai_task_support::StageName::FetchA));
    let mut fut_b =
        std::boxed::Box::pin(stage.run(ai_task_support::StageName::FetchB));
    let mut out_a: Option<ai_task_support::Artifact> = None;
    let mut out_b: Option<ai_task_support::Artifact> = None;
    let mut timer_started = false;
    std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
        if let Some(dl) = deadline {
            if std::time::Instant::now() >= dl {
                return std::task::Poll::Ready(Err(PipelineError::Deadline));
            }
            if !timer_started {
                timer_started = true;
                let w = cx.waker().clone();
                let flag = done.clone();
                std::thread::spawn(move || loop {
                    if flag.load(std::sync::atomic::Ordering::Relaxed) {
                        break;
                    }
                    let now = std::time::Instant::now();
                    if now >= dl {
                        if !flag.load(std::sync::atomic::Ordering::Relaxed) {
                            w.wake();
                        }
                        break;
                    }
                    let rem = dl.saturating_duration_since(now);
                    let chunk = if rem
                        > std::time::Duration::from_millis(10)
                    {
                        std::time::Duration::from_millis(10)
                    } else {
                        rem
                    };
                    std::thread::sleep(chunk);
                });
            }
        }
        if out_a.is_none() {
            match fut_a.as_mut().poll(cx) {
                std::task::Poll::Ready(Ok(v)) => {
                    out_a = Some(v);
                }
                std::task::Poll::Ready(Err(_)) => {
                    return std::task::Poll::Ready(Err(
                        PipelineError::Stage {
                            name: ai_task_support::StageName::FetchA,
                        },
                    ));
                }
                std::task::Poll::Pending => {}
            }
        }
        if out_b.is_none() {
            match fut_b.as_mut().poll(cx) {
                std::task::Poll::Ready(Ok(v)) => {
                    out_b = Some(v);
                }
                std::task::Poll::Ready(Err(_)) => {
                    return std::task::Poll::Ready(Err(
                        PipelineError::Stage {
                            name: ai_task_support::StageName::FetchB,
                        },
                    ));
                }
                std::task::Poll::Pending => {}
            }
        }
        let ta = out_a.take();
        let tb = out_b.take();
        match (ta, tb) {
            (Some(a), Some(b)) => std::task::Poll::Ready(Ok((a, b))),
            (oa, ob) => {
                out_a = oa;
                out_b = ob;
                std::task::Poll::Pending
            }
        }
    })
    .await
}

async fn run_single(
    stage: &ai_task_support::Stage,
    name: ai_task_support::StageName,
    deadline: Option<std::time::Instant>,
) -> Result<ai_task_support::Artifact, PipelineError> {
    let done = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let _guard = Guard { flag: done.clone() };
    let mut fut = std::boxed::Box::pin(stage.run(name.clone()));
    let mut timer_started = false;
    std::future::poll_fn(|cx: &mut std::task::Context<'_>| {
        if let Some(dl) = deadline {
            if std::time::Instant::now() >= dl {
                return std::task::Poll::Ready(Err(PipelineError::Deadline));
            }
            if !timer_started {
                timer_started = true;
                let w = cx.waker().clone();
                let flag = done.clone();
                std::thread::spawn(move || loop {
                    if flag.load(std::sync::atomic::Ordering::Relaxed) {
                        break;
                    }
                    let now = std::time::Instant::now();
                    if now >= dl {
                        if !flag.load(std::sync::atomic::Ordering::Relaxed) {
                            w.wake();
                        }
                        break;
                    }
                    let rem = dl.saturating_duration_since(now);
                    let chunk = if rem
                        > std::time::Duration::from_millis(10)
                    {
                        std::time::Duration::from_millis(10)
                    } else {
                        rem
                    };
                    std::thread::sleep(chunk);
                });
            }
        }
        match fut.as_mut().poll(cx) {
            std::task::Poll::Ready(Ok(v)) => {
                std::task::Poll::Ready(Ok(v))
            }
            std::task::Poll::Ready(Err(_)) => {
                std::task::Poll::Ready(Err(PipelineError::Stage {
                    name: name.clone(),
                }))
            }
            std::task::Poll::Pending => std::task::Poll::Pending,
        }
    })
    .await
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let start = std::time::Instant::now();
    let dl = start.checked_add(deadline);
    let (a, b) = fetch_both(&stage, dl).await?;
    std::mem::drop(a);
    std::mem::drop(b);
    let c = run_single(&stage, ai_task_support::StageName::Combine, dl).await?;
    std::mem::drop(c);
    let p = run_single(&stage, ai_task_support::StageName::Publish, dl).await?;
    Ok(ai_task_support::Published::from(p))
}

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    if deadline.is_zero() {
        return Err(PipelineError::Deadline);
    }
    let tenant = match lgwks_bot::script::Tenant::new("pipeline") {
        Ok(t) => t,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = lgwks_bot::script::Scope::root(tenant);
    let stage_for_body = stage.clone();
    let outer = lgwks_bot::script::within(
        &scope,
        "pipeline",
        deadline,
        async move {
            match run_pipeline(&stage_for_body).await {
                Ok(p) => Ok(Ok(p)),
                Err(n) => Ok(Err(n)),
            }
        },
    )
    .await;
    match outer {
        Ok(Ok(p)) => Ok(p),
        Ok(Err(name)) => Err(PipelineError::Stage { name }),
        Err(e) => match e {
            lgwks_bot::script::FlowError::TimedOut { .. } => Err(PipelineError::Deadline),
            lgwks_bot::script::FlowError::Cancelled { .. } => Err(PipelineError::Cancelled),
            other => {
                if other.is_cancelled() {
                    Err(PipelineError::Cancelled)
                } else {
                    Err(PipelineError::Deadline)
                }
            }
        },
    }
}

async fn run_pipeline(
    stage: &ai_task_support::Stage,
) -> Result<ai_task_support::Published, ai_task_support::StageName> {
    let (a, b) = fetch_both(stage).await?;
    let _ = (a.value(), b.value());
    let c = match stage.run(ai_task_support::StageName::Combine).await {
        Ok(v) => v,
        Err(_) => return Err(ai_task_support::StageName::Combine),
    };
    let _ = c.value();
    let p = match stage.run(ai_task_support::StageName::Publish).await {
        Ok(v) => v,
        Err(_) => return Err(ai_task_support::StageName::Publish),
    };
    Ok(ai_task_support::Published::from(p))
}

async fn fetch_both(
    stage: &ai_task_support::Stage,
) -> Result<
    (ai_task_support::Artifact, ai_task_support::Artifact),
    ai_task_support::StageName,
> {
    use std::future::Future;
    use std::task::Poll;
    let mut fut_a = Box::pin(stage.run(ai_task_support::StageName::FetchA));
    let mut fut_b = Box::pin(stage.run(ai_task_support::StageName::FetchB));
    let mut out_a: Option<
        Result<ai_task_support::Artifact, ai_task_support::StageError>,
    > = None;
    let mut out_b: Option<
        Result<ai_task_support::Artifact, ai_task_support::StageError>,
    > = None;
    std::future::poll_fn(|cx| {
        if out_a.is_none() {
            match fut_a.as_mut().poll(cx) {
                Poll::Ready(v) => {
                    out_a = Some(v);
                }
                Poll::Pending => {}
            }
        }
        if out_b.is_none() {
            match fut_b.as_mut().poll(cx) {
                Poll::Ready(v) => {
                    out_b = Some(v);
                }
                Poll::Pending => {}
            }
        }
        match out_a.as_ref() {
            Some(Err(_)) => {
                return Poll::Ready(Err(ai_task_support::StageName::FetchA));
            }
            _ => {}
        }
        match out_b.as_ref() {
            Some(Err(_)) => {
                return Poll::Ready(Err(ai_task_support::StageName::FetchB));
            }
            _ => {}
        }
        let a_ok = match out_a.as_ref() {
            Some(Ok(_)) => true,
            _ => false,
        };
        let b_ok = match out_b.as_ref() {
            Some(Ok(_)) => true,
            _ => false,
        };
        if a_ok && b_ok {
            let a = match out_a.take() {
                Some(Ok(v)) => v,
                _ => return Poll::Pending,
            };
            let b = match out_b.take() {
                Some(Ok(v)) => v,
                _ => return Poll::Pending,
            };
            return Poll::Ready(Ok((a, b)));
        }
        Poll::Pending
    })
    .await
}

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let run_id = lgwks_bot::effect::RunId::from_hex("00000000000000000000000000000001")
        .map_err(|_| RecoveryError::NoStore)?;
    let w0 = world.clone();
    let body = move |scope: lgwks_bot::script::Scope, _input: ()| {
        let w = w0.clone();
        async move {
            let width = w.width();
            let indices: Vec<u32> = (0..width).collect();
            let w_for_each = w.clone();
            let vals: Vec<u64> = lgwks_bot::script::each(
                &scope,
                "units",
                None,
                indices,
                move |s: lgwks_bot::script::Scope, idx: u32| {
                    let ww = w_for_each.clone();
                    async move {
                        match ww.unit(&s, idx).await {
                            Ok(v) => Ok(v),
                            Err(_) => Err(
                                lgwks_bot::script::FlowError::failed(format!("unit {}", idx)),
                            ),
                        }
                    }
                },
            )
            .await?;
            let total: u64 = vals.into_iter().sum();
            if !w.ledger().applied("recover") {
                w.ledger().apply("recover");
            }
            Ok(total)
        }
    };
    let host = lgwks_bot::task::Host::builder("recover")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;
    let t = lgwks_bot::task::task("recover", body).map_err(|_| RecoveryError::NoLedger)?;
    let report = host.resume(run_id, &t, ()).await;
    match report.into_result() {
        Ok(total) => {
            if !world.ledger().applied("recover") {
                world.ledger().apply("recover");
            }
            Ok(total)
        }
        Err(e) => {
            if e.is_cancelled() {
                return Err(RecoveryError::Deadline);
            }
            match &e {
                lgwks_bot::script::FlowError::Cancelled { .. } => Err(RecoveryError::Deadline),
                lgwks_bot::script::FlowError::TimedOut { .. } => Err(RecoveryError::Deadline),
                lgwks_bot::script::FlowError::Failed { reason, .. }
                | lgwks_bot::script::FlowError::Transient { reason, .. } => {
                    if let Some(s) = reason.strip_prefix("unit ") {
                        if let Ok(idx) = s.trim().parse::<u32>() {
                            return Err(RecoveryError::Unit { index: idx });
                        }
                    }
                    Err(RecoveryError::NoLedger)
                }
                _ => {
                    let dbg = format!("{:?}", e);
                    if let Some(pos) = dbg.find("unit ") {
                        let rest = &dbg[pos + 5..];
                        let mut num = String::new();
                        for ch in rest.chars() {
                            if ch.is_ascii_digit() {
                                num.push(ch);
                            } else {
                                break;
                            }
                        }
                        if let Ok(idx) = num.parse::<u32>() {
                            return Err(RecoveryError::Unit { index: idx });
                        }
                    }
                    if dbg.contains("TimedOut")
                        || dbg.contains("Cancelled")
                        || dbg.contains("Deadline")
                    {
                        return Err(RecoveryError::Deadline);
                    }
                    Err(RecoveryError::Deadline)
                }
            }
        }
    }
}

use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const RUN_HEX: &str = "0123456789abcdef0123456789abcdef";

fn parse_unit_reason(s: &str) -> Option<u32> {
    let rest = s.strip_prefix("unit ")?;
    let v: u32 = rest.parse().ok()?;
    Some(v)
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let builder = match lgwks_bot::task::Host::builder("recover") {
        Ok(b) => b,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let builder = match builder.run_store(&store_dir) {
        Ok(b) => b,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let builder = builder.default_deadline(deadline);
    let host = match builder.build() {
        Ok(h) => h,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let run_id = match RunId::from_hex(RUN_HEX) {
        Ok(id) => id,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let world_for_task = world.clone();
    let task = match lgwks_bot::task::task("recover", move |scope: Scope, _input: ()| {
        let w = world_for_task.clone();
        async move {
            let width = w.width();
            let mut total: u64 = 0;
            for index in 0..width {
                match w.unit(&scope, index).await {
                    Ok(v) => {
                        total = total.wrapping_add(v);
                    }
                    Err(e) => {
                        let idx: u32 = match e {
                            ai_task_support::recovery::UnitError::Unit { index: i } => i,
                            _ => index,
                        };
                        return Err::<u64, FlowError>(FlowError::failed(format!("unit {}", idx)));
                    }
                }
            }
            Ok::<u64, FlowError>(total)
        }
    }) {
        Ok(t) => t,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let report = host.resume(run_id, &task, ()).await;
    let total: u64 = match report.into_result() {
        Ok(v) => v,
        Err(e) => {
            if e.is_cancelled() {
                return Err(RecoveryError::Deadline);
            }
            match e {
                FlowError::TimedOut { .. } => return Err(RecoveryError::Deadline),
                FlowError::Cancelled { .. } => return Err(RecoveryError::Deadline),
                FlowError::Failed { reason, .. } => {
                    let s = format!("{}", reason);
                    match parse_unit_reason(s.as_str()) {
                        Some(idx) => return Err(RecoveryError::Unit { index: idx }),
                        None => return Err(RecoveryError::NoLedger),
                    }
                }
                _ => return Err(RecoveryError::NoLedger),
            }
        }
    };
    if !world.ledger().applied("recover") {
        world.ledger().apply("recover");
    }
    Ok(total)
}

use std::path::PathBuf;
use std::time::Duration;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

fn parse_unit_reason(s: &str) -> Option<u32> {
    let rest = match s.split_once("unit-failure:") {
        Some(v) => v.1,
        None => return None,
    };
    let mut digits = String::new();
    for ch in rest.chars() {
        if ch.is_ascii_digit() {
            digits.push(ch);
        } else {
            break;
        }
    }
    if digits.is_empty() {
        return None;
    }
    match digits.parse::<u32>() {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

fn map_flow_error(e: &lgwks_bot::script::FlowError) -> RecoveryError {
    if e.is_cancelled() {
        return RecoveryError::Deadline;
    }
    let dbg = format!("{e:?}");
    match parse_unit_reason(&dbg) {
        Some(index) => RecoveryError::Unit { index },
        None => {
            if dbg.contains("TimedOut") || dbg.contains("Cancelled") || dbg.contains("DeadlineExceeded") || dbg.contains("deadline") || dbg.contains("cancel") {
                RecoveryError::Deadline
            } else {
                RecoveryError::NoLedger
            }
        }
    }
}

struct CancelGuard<'a> {
    host: &'a lgwks_bot::task::Host,
}

impl<'a> Drop for CancelGuard<'a> {
    fn drop(&mut self) {
        self.host.cancel();
    }
}

async fn collect_units(
    scope: &lgwks_bot::script::Scope,
    world: &ai_task_support::recovery::World,
) -> Result<u64, lgwks_bot::script::FlowError> {
    let width = world.width();
    let indices: Vec<u32> = (0..width).collect();
    let values: Vec<u64> = lgwks_bot::script::each(
        scope,
        "units",
        None,
        indices,
        {
            let world = world.clone();
            move |item_scope: lgwks_bot::script::Scope, index: u32| {
                let world = world.clone();
                async move {
                    match world.unit(&item_scope, index).await {
                        Ok(v) => Ok(v),
                        Err(ai_task_support::recovery::UnitError::Unit { index }) => {
                            Err(lgwks_bot::script::FlowError::failed(format!(
                                "unit-failure:{index}"
                            )))
                        }
                    }
                }
            }
        },
    )
    .await?;
    let total: u64 = values.into_iter().sum();
    Ok(total)
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    if deadline.is_zero() {
        return Err(RecoveryError::Deadline);
    }
    let run_id = match lgwks_bot::effect::RunId::from_hex("11111111111111111111111111111111") {
        Ok(v) => v,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let builder = match lgwks_bot::task::Host::builder("recover") {
        Ok(b) => b,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let builder = match builder.run_store(&store_dir) {
        Ok(b) => b,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let conc = match std::num::NonZeroUsize::new(32) {
        Some(v) => v,
        None => return Err(RecoveryError::NoStore),
    };
    let builder = builder
        .max_concurrent_tasks(conc)
        .default_deadline(deadline);
    let host = match builder.build() {
        Ok(h) => h,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let world_for_task = world.clone();
    let task = match lgwks_bot::task::task(
        "recover",
        move |scope: lgwks_bot::script::Scope, _input: ()| {
            let world = world_for_task.clone();
            async move { collect_units(&scope, &world).await }
        },
    ) {
        Ok(t) => t,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let _guard = CancelGuard { host: &host };
    let tenant = match lgwks_bot::script::Tenant::new("recover") {
        Ok(t) => t,
        Err(_) => return Err(RecoveryError::NoStore),
    };
    let scope = lgwks_bot::script::Scope::root(tenant);
    let inner = lgwks_bot::script::within(&scope, "deadline", deadline, async {
        let report = host.resume(run_id, &task, ()).await;
        report.into_result()
    })
    .await;
    match inner {
        Ok(total) => {
            if !world.ledger().applied("recover") {
                world.ledger().apply("recover");
            }
            Ok(total)
        }
        Err(e) => {
            host.cancel();
            Err(map_flow_error(&e))
        }
    }
}

